package com.ascent.climb.data.i18n

/**
 * 英文题库（第一批：u1 的 l1–l4）。
 *
 * key 结构：`q.<questionId>.p`（题干）/ `.c`（情境）/ `.o<n>`（选项，n 从 0 起）
 * / `.e`（解析）/ `.l<n>`、`.r<n>`（配对左右）/ `.a<n>`（填空答案）
 * / `.s<si>.p`、`.s<si>.o<n>`、`.s<si>.e`（情景题子问题）。
 */
internal val PACK_EN_QUIZ: Map<String, String> = mapOf(

    // ---------- l1 ----------
    "q.l1#0.p" to "Which of the following is an objective hazard?",
    "q.l1#0.o0" to "Rockfall and icefall",
    "q.l1#0.o1" to "An error of judgement",
    "q.l1#0.o2" to "Running out of energy",
    "q.l1#0.o3" to "A competitive mindset",
    "q.l1#0.e" to "Objective hazards are environmental factors that do not change with your skill or attitude: rockfall, icefall, avalanches, weather, crevasses. The other three are subjective hazards that training and self-discipline can control.",

    "q.l1#1.p" to "As altitude increases, how do air temperature and oxygen partial pressure change?",
    "q.l1#1.o0" to "Temperature rises and oxygen partial pressure falls",
    "q.l1#1.o1" to "Temperature falls by about 6.5 °C per 1,000 m, and oxygen partial pressure falls with it",
    "q.l1#1.o2" to "Neither one changes",
    "q.l1#1.o3" to "Temperature falls and oxygen partial pressure rises",
    "q.l1#1.e" to "For every 1,000 m of ascent the air cools by roughly 6.5 °C, while air pressure and oxygen partial pressure fall in step. That is why altitude illness and cold exposure arrive together.",

    "q.l1#2.p" to "Which statement about the role of training is correct?",
    "q.l1#2.o0" to "Good training removes all objective hazards",
    "q.l1#2.o1" to "Training reduces subjective hazards but cannot remove objective ones",
    "q.l1#2.o2" to "Objective hazards are purely a matter of luck",
    "q.l1#2.o3" to "If you are fit enough there is no danger",
    "q.l1#2.e" to "Technical training improves how you judge and respond, but rockfall, avalanches and weather do not disappear because you are experienced. The right attitude to objective hazards is to avoid them and keep an exit.",

    "q.l1#3.p" to "Why do mountaineers emphasise leaving a margin rather than fixing things on the spot?",
    "q.l1#3.o0" to "Because a margin raises your summit rate",
    "q.l1#3.o1" to "Because a margin acts early in the accident chain, while fixing things happens at the last link",
    "q.l1#3.o2" to "Because a margin saves money",
    "q.l1#3.o3" to "Because the rules require a reserve",
    "q.l1#3.e" to "Margins take many forms: time, energy, supplies, a weather window. What they share is that you create the space while you can still choose. Repair always begins after something has already gone wrong, when few options remain.",

    "q.l1#4.p" to "What is the best measure of a climbing team's level?",
    "q.l1#4.o0" to "The highest altitude anyone has summited",
    "q.l1#4.o1" to "How many trips it makes each year",
    "q.l1#4.o2" to "Whether it can retreat safely when needed and keep risk acceptable",
    "q.l1#4.o3" to "The total value of its equipment",
    "q.l1#4.e" to "Summit records only prove that something once worked; the ability to retreat proves control. In high-altitude climbing the next chance always comes, a serious accident does not. What really separates teams is how well they decide under unfavourable conditions.",

    "q.l1#5.p" to "China's domestic mountaineering regulations limit climbing to 'independent peaks'. How is an independent peak defined on a topographic map?",
    "q.l1#5.o0" to "Any massif higher than 5,000 m",
    "q.l1#5.o1" to "A massif enclosed by a closed contour line",
    "q.l1#5.o2" to "A massif with a visible glacier",
    "q.l1#5.o3" to "A massif nobody has summited",
    "q.l1#5.e" to "On a topographic map an independent peak appears as a closed contour loop, meaning the massif falls away on every side. The definition separates 'mountaineering' from 'walking up to some high point', and it underpins how the activity is administered and counted.",

    "q.l1#6.p" to "What is the most common pattern in accident reviews?",
    "q.l1#6.o0" to "Almost every accident comes from one major error",
    "q.l1#6.o1" to "Serious accidents are usually several small errors stacked together",
    "q.l1#6.o2" to "Accidents are unrelated to experience",
    "q.l1#6.o3" to "Equipment failure is the main cause",
    "q.l1#6.e" to "A typical accident is a chain: an over-optimistic route decision, then running later than planned, then simplifying the protection to save time, then fatigue degrading your movement. Break any single link and the accident does not happen — which is exactly why a margin beats a repair.",

    "q.l1#7.p" to "[Multiple choice] Which of these are objective hazards in mountaineering?",
    "q.l1#7.o0" to "Rockfall and icefall",
    "q.l1#7.o1" to "Avalanche",
    "q.l1#7.o2" to "A sudden change in weather",
    "q.l1#7.o3" to "Crevasses",
    "q.l1#7.o4" to "A competitive mindset",
    "q.l1#7.e" to "The first four do not change with your skill or attitude — they are properties of the environment. Against objective hazards you can only avoid, choose the timing and keep an exit. Subjective hazards — misjudgement, poor preparation, comparison with others — are the part training can actually reduce.",

    "q.l1#8.p" to "Before a high-altitude climb, which three things should you confirm first?",
    "q.l1#8.o0" to "Fitness, equipment, itinerary and insurance",
    "q.l1#8.o1" to "Your partners' reputation, the peak's fame, the equipment brands",
    "q.l1#8.o2" to "Photos, video and your social media plan",
    "q.l1#8.o3" to "The forecast, flights and hotels",
    "q.l1#8.e" to "Fitness decides whether you can finish, equipment decides whether you survive bad conditions, and itinerary plus insurance decide whether help exists when something goes wrong. All three are fully within your control before departure — which is exactly why there is no excuse when they fail.",

    "q.l1#9.p" to "Why can experienced climbers still get into trouble?",
    "q.l1#9.o0" to "Because experience gradually raises what you accept as normal risk",
    "q.l1#9.o1" to "Because experienced people attempt harder routes",
    "q.l1#9.o2" to "Because experience has nothing to do with safety",
    "q.l1#9.o3" to "Because experienced people tire more easily",
    "q.l1#9.e" to "It is called risk normalisation: after passing safely through the same conditions many times, you unconsciously reclassify them as 'safe' and widen the standard a little at a time. The more experienced you are, the more you need explicit rules — a turnaround time, for instance — to hold your judgement in check.",

    // ---------- l2 ----------
    "q.l2#0.p" to "What is a type T (technical) ice axe mainly used for?",
    "q.l2#0.o0" to "Strolling up gentle snow slopes",
    "q.l2#0.o1" to "Steep ice faces and technical climbing",
    "q.l2#0.o2" to "Photography only",
    "q.l2#0.o3" to "Snow camping only",
    "q.l2#0.e" to "A type T shaft can be planted in ice and take a pull, which suits steep ice. A type B shaft is weaker: it is rated for walking and self-arrest loads and must not be used as a technical anchor.",

    "q.l2#1.p" to "Which crampon class goes with a fully rigid B3 boot?",
    "q.l2#1.o0" to "C1, full strap",
    "q.l2#1.o1" to "C2, strap front and clip rear",
    "q.l2#1.o2" to "C3, full clip",
    "q.l2#1.o3" to "Any class will do",
    "q.l2#1.e" to "A B3 boot has front and rear welts, and a C3 full-clip crampon is the most secure match. B1 with C1, B2 with C2 and B3 with C3 is the basic matching rule.",

    "q.l2#2.p" to "What happens if you put C3 full-clip crampons on a soft-soled hiking boot?",
    "q.l2#2.o0" to "No problem at all, and it is quicker to fit",
    "q.l2#2.o1" to "The boot deforms under load, the clips lose grip and the crampon can come off — a dangerous setup",
    "q.l2#2.o2" to "You will walk faster",
    "q.l2#2.o3" to "It only looks bad",
    "q.l2#2.e" to "Full-clip crampons rely on a rigid boot to hold their shape. On a soft boot the boot flexes, the clips lose purchase and the crampon may come off on a steep slope. It is a clearly dangerous mismatch.",

    "q.l2#3.p" to "Ice axe length is usually chosen by height. What is recommended for a climber of about 173–180 cm?",
    "q.l2#3.o0" to "50 cm",
    "q.l2#3.o1" to "55 cm",
    "q.l2#3.o2" to "60 cm",
    "q.l2#3.o3" to "70 cm",
    "q.l2#3.e" to "A common reference: under about 157 cm take 50 cm; 157–170 cm take 55 cm; 173–180 cm take 60 cm; above 183 cm take 65–70 cm. Only the right length lets you drive the pick effectively into the snow during self-arrest.",

    "q.l2#4.p" to "When choosing crampons, what is the most basic and most important requirement?",
    "q.l2#4.o0" to "As light as possible",
    "q.l2#4.o1" to "They must fit the boot, ideally 12-point steel with anti-balling plates",
    "q.l2#4.o2" to "The colour should match your other gear",
    "q.l2#4.o3" to "More points is always better — 20 or more",
    "q.l2#4.e" to "A crampon is only as good as its connection to the boot. More points is not automatically better; fit and anti-balling plates (which stop snow balling up underfoot) are what matter. A poor fit is the classic way to lose a crampon on a steep slope.",

    "q.l2#5.p" to "[Scenario] For a high-altitude technical summit day carrying crampons, an axe, a spare insulation layer, food, water and emergency kit, what net pack volume is recommended?",
    "q.l2#5.c" to "There is no single right answer for pack volume — it depends on the route, whether you carry the technical gear yourself, and who carries the group equipment.",
    "q.l2#5.o0" to "15–25 litres",
    "q.l2#5.o1" to "35–50 litres",
    "q.l2#5.o2" to "60–75 litres",
    "q.l2#5.o3" to "90 litres or more",
    "q.l2#5.e" to "For 'own technical gear + spare insulation + emergency kit', 35–50 litres is the usual range, ideally with a dedicated crampon pocket.\nBut volume is not fixed: on a well-travelled snow slope with group gear carried by staff and stable weather, a 15–25 litre summit pack can be entirely adequate; if you must carry a tent or ropes yourself, you need more.\nThe criterion is always what you actually have to carry, not a universal number.",

    "q.l2#6.p" to "What is the main purpose of an ice axe leash?",
    "q.l2#6.o0" to "Decoration and team identification",
    "q.l2#6.o1" to "To stop you losing the axe, so you can still control it after a slip",
    "q.l2#6.o2" to "To add weight so the axe presses down harder",
    "q.l2#6.o3" to "To hang the axe on your pack",
    "q.l2#6.e" to "The leash matters at the instant of a slip: once the axe leaves your hand you have lost the only thing that can brake. The leash keeps it with you through violent movement — which is why so many manuals insist on wearing it.",

    "q.l2#7.p" to "[Multiple choice] Which factors matter when choosing crampons?",
    "q.l2#7.o0" to "How they attach to the boot (strap / semi-clip / full clip)",
    "q.l2#7.o1" to "Whether the number and shape of points suit the terrain",
    "q.l2#7.o2" to "Whether they have anti-balling plates",
    "q.l2#7.o3" to "The reliability of the bindings and straps",
    "q.l2#7.o4" to "Whether the colour matches your pack",
    "q.l2#7.e" to "All four matter. The attachment decides whether they go on at all, the point shape decides whether they suit the terrain (front points for steep ice, flat points for gentle snow), the plates decide whether snow balls up underneath, and the bindings decide whether they stay on.",

    "q.l2#8.p" to "Why check the crampon straps and bindings before every departure?",
    "q.l2#8.o0" to "To keep the gear tidy",
    "q.l2#8.o1" to "Because a crampon coming off on a steep slope is a direct threat to life",
    "q.l2#8.o2" to "Because straps age and change colour",
    "q.l2#8.o3" to "Because team discipline requires it",
    "q.l2#8.e" to "Crampons tend to fail at the worst moment: on a steep face, during a traverse, on the first weighted step. Losing the grip under one foot shifts your centre of mass instantly. Checking costs almost nothing; the consequence is entirely disproportionate.",

    "q.l2#9.p" to "Which statement about ice axe pick shape is correct?",
    "q.l2#9.o0" to "All ice axe picks are straight",
    "q.l2#9.o1" to "A curved pick enters ice more easily and is less likely to pop out, so it is common on technical ice tools",
    "q.l2#9.o2" to "A curved pick is only for walking on snow",
    "q.l2#9.o3" to "Pick shape has nothing to do with use",
    "q.l2#9.e" to "A long mountaineering axe usually has a pick curved downward, so it bites when you swing or arrest and does not easily pull out. Ice-climbing tools have sharper, steeper picks for fast placement and easy removal on steep ice. Use dictates shape.",

    // ---------- l3 ----------
    "q.l3#0.p" to "What is the main advantage of double boots over single boots?",
    "q.l3#0.o0" to "Lighter",
    "q.l3#0.o1" to "Warmer, and the inner boot can be taken out to dry",
    "q.l3#0.o2" to "Cheaper",
    "q.l3#0.o3" to "Easier to put on and take off",
    "q.l3#0.e" to "The inner boot comes out, so it can be dried against your body or in the sleeping bag overnight and will not freeze — the key point on multi-day high routes. The cost is weight and price.",

    "q.l3#1.p" to "What is the most important specification for snow goggles?",
    "q.l3#1.o0" to "How dark the lens is",
    "q.l3#1.o1" to "UV400 ultraviolet protection",
    "q.l3#1.o2" to "The frame brand",
    "q.l3#1.o3" to "Whether the lens is mirrored",
    "q.l3#1.e" to "Snow reflects a great deal of ultraviolet. UV400 means almost complete UV blocking and is the key to preventing snow blindness; lens tint only affects visual comfort.",

    "q.l3#2.p" to "What matters when choosing the size of a mountaineering boot?",
    "q.l3#2.o0" to "Tighter is better, to stop the foot sliding",
    "q.l3#2.o1" to "Toes must not touch the front, with a little room so descents do not injure them",
    "q.l3#2.o2" to "Bigger is better, to allow thicker socks",
    "q.l3#2.o3" to "Exactly the same as your everyday shoe size",
    "q.l3#2.e" to "On a descent the foot slides forward. If the toes jam against the front, a long descent can bruise or even lose a nail. Leave a little room and lock the heel with the lacing.",

    "q.l3#3.p" to "What is the key design feature of an 8,000 m summit boot?",
    "q.l3#3.o0" to "As light as possible",
    "q.l3#3.o1" to "A removable insulated liner with a waterproof, windproof, abrasion-resistant upper",
    "q.l3#3.o2" to "It must be single-layered",
    "q.l3#3.o3" to "The softer the sole the more comfortable",
    "q.l3#3.e" to "A removable liner can be taken out at night to dry or to be kept warm against your body, so it never freezes — the key to keeping feet functional on multi-day high routes. The upper is usually a three-layer laminate for waterproofing, wind resistance and durability.",

    "q.l3#4.p" to "Why should a base layer never be cotton?",
    "q.l3#4.o0" to "Cotton is too expensive",
    "q.l3#4.o1" to "Cotton holds sweat and dries slowly, so damp fabric against the skin accelerates heat loss",
    "q.l3#4.o2" to "Cotton causes allergies",
    "q.l3#4.o3" to "Cotton does not breathe, so it feels colder",
    "q.l3#4.e" to "The base layer's job is to move sweat away from the skin. Cotton absorbs water and hardly releases it, so damp cold fabric keeps drawing heat away. Choose polyester or merino wool, which move moisture quickly.",

    "q.l3#5.p" to "What material is recommended for a 6,000 m boot?",
    "q.l3#5.o0" to "Ordinary leather",
    "q.l3#5.o1" to "A waterproof, breathable material such as GORE-TEX",
    "q.l3#5.o2" to "Pure cotton fabric",
    "q.l3#5.o3" to "A hard plastic shell",
    "q.l3#5.e" to "A 6,000 m boot prizes lightness, comfort and grip, and must also walk well for hours. A waterproof-breathable membrane such as GORE-TEX keeps water out while letting vapour escape — waterproof without breathability simply traps sweat, and you end up wet and cold anyway.",

    "q.l3#6.p" to "Which material should mountaineering socks avoid?",
    "q.l3#6.o0" to "Merino wool",
    "q.l3#6.o1" to "Synthetic fibres such as polyester",
    "q.l3#6.o2" to "Cotton",
    "q.l3#6.o3" to "Nylon",
    "q.l3#6.e" to "Same logic as the base layer: cotton absorbs sweat and hardly releases it, so damp cold fabric keeps draining heat and sharply raises the risk of blisters. Choose synthetics (no cotton) or merino, in a knee-length cut that balances warmth with circulation.",

    "q.l3#7.p" to "What is the right approach to choosing gaiters?",
    "q.l3#7.o0" to "Use the same short gaiters on every trip",
    "q.l3#7.o1" to "For high peaks, prefer longer gaiters that keep snow out of the boot",
    "q.l3#7.o2" to "Gaiters are only for rain",
    "q.l3#7.o3" to "Shorter and lighter is always better",
    "q.l3#7.e" to "Gaiters are a fabric tube over the boot that keeps snow and debris out. On deep high-altitude snow a short pair is quickly buried and useless, so longer is recommended; short pairs suit well-known trekking routes and shallow Alpine-style snow.",

    "q.l3#8.p" to "What are camp boots and slippers for, and what do they need?",
    "q.l3#8.o0" to "For the summit; they must be very stiff",
    "q.l3#8.o1" to "For moving around camp; they must be warm, waterproof and non-slip",
    "q.l3#8.o2" to "For technical climbing; they need front points",
    "q.l3#8.o3" to "Purely decorative; optional",
    "q.l3#8.e" to "They let your main boots rest: change into camp boots or slippers inside the tent so the liners can dry and the feet are not compressed all day. They carry no technical function, but they directly affect the state of your feet the next morning.",

    "q.l3#9.p" to "What does a knee-length sock design contribute on a long expedition?",
    "q.l3#9.o0" to "It looks more professional",
    "q.l3#9.o1" to "It keeps the foot warm while supporting circulation",
    "q.l3#9.o2" to "It is easier to put on",
    "q.l3#9.o3" to "It adds cushioning thickness",
    "q.l3#9.e" to "On long days the feet swell and circulation suffers. A knee-length sock covers the calf, warming it and, through even pressure, helping venous return — which on a multi-day trip decides whether your feet still work on day three.",

    // ---------- l4 ----------
    "q.l4#0.p" to "What is the correct way to kick steps?",
    "q.l4#0.o0" to "Take long strides to use fewer steps",
    "q.l4#0.o1" to "Kick small steps at an even rhythm and keep your centre of mass stable",
    "q.l4#0.o2" to "Use only the toes",
    "q.l4#0.o3" to "Drive the heel into the snow the whole way",
    "q.l4#0.e" to "Small steps at an even rhythm keep your centre of mass stable and waste less energy. Long strides swing the body from side to side, which is the easiest way to lose balance on a snow slope.",

    "q.l4#1.p" to "Which hand should carry the axe while moving?",
    "q.l4#1.o0" to "The downhill hand",
    "q.l4#1.o1" to "The uphill hand, ready to go straight into an arrest",
    "q.l4#1.o2" to "Neither hand",
    "q.l4#1.o3" to "On the outside of the pack",
    "q.l4#1.e" to "Carry it in the uphill hand in the piolet canne position, pick back and head forward. If you slip you can press down into self-arrest without changing hands — and those few seconds of swapping are often the whole accident window.",

    "q.l4#2.p" to "What technique eases breathlessness at altitude on the way up?",
    "q.l4#2.o0" to "Holding your breath while moving",
    "q.l4#2.o1" to "Pressure breathing: a deep inhale and a forceful exhale, synchronised with your step rate",
    "q.l4#2.o2" to "Fast shallow breathing",
    "q.l4#2.o3" to "Breathing through a glove",
    "q.l4#2.e" to "Pressure breathing raises positive pressure in the lungs by exhaling actively, which improves gas exchange. Paired with your step rate — one breath every two or three steps, say — it noticeably reduces the suffocating feeling of altitude.",

    "q.l4#3.p" to "When a rope team moves up a snow slope, what is the right way to kick steps?",
    "q.l4#3.o0" to "Everyone kicks their own separate line",
    "q.l4#3.o1" to "The lead kicks an even staircase and everyone behind uses the same steps",
    "q.l4#3.o2" to "Anyone kicks whatever they like",
    "q.l4#3.o3" to "Kick them as deep and as wide as possible",
    "q.l4#3.e" to "A single set of steps greatly reduces the effort for everyone behind and keeps the team on one line and one rhythm. A level staircase with even spacing is itself a mark of team efficiency and safety.",

    "q.l4#4.p" to "At altitude, what is the core principle of pacing?",
    "q.l4#4.o0" to "Go as fast as possible and rest earlier",
    "q.l4#4.o1" to "Hold a sustainable even pace and avoid repeated explosive efforts",
    "q.l4#4.o2" to "Alternate fast and slow to save energy",
    "q.l4#4.o3" to "Just match your partner and ignore your own state",
    "q.l4#4.e" to "Oxygen uptake is limited at altitude, so repeated explosive efforts pile up lactate and deepen hypoxia. A steady pace with pressure breathing takes you further, and stops the whole team being disrupted by one person sprinting.",

    "q.l4#5.p" to "Who should set the pace for a team on a snow slope?",
    "q.l4#5.o0" to "The fittest person in the team",
    "q.l4#5.o1" to "It should follow the slowest member so the team stays together",
    "q.l4#5.o2" to "The leader, fixed to the schedule",
    "q.l4#5.o3" to "Everyone at their own pace",
    "q.l4#5.e" to "Once gaps open on a snow slope, the people behind lose both protection and support; and too fast a pace exhausts the weaker members before they even reach the dangerous ground. Moving at the slowest person's pace keeps the safety margin with the whole team.",

    "q.l4#6.p" to "When crossing an ice slope with a noticeable angle, what does the manual recommend?",
    "q.l4#6.o0" to "Move as a normal rope team",
    "q.l4#6.o1" to "Fix a route rope or use an alternating belay; generally do not move together",
    "q.l4#6.o2" to "Hurry across as fast as possible",
    "q.l4#6.o3" to "Take crampons off for more friction",
    "q.l4#6.e" to "Arresting on ice is far less reliable than on snow, and a rope team on ice can pull the whole group down. The correct approach on angled ice is to fix a route rope or use an alternating belay — protection from the system, not from individual braking ability.",

    "q.l4#7.p" to "What is the main advantage of zig-zagging up a snow slope rather than going straight up?",
    "q.l4#7.o0" to "A shorter distance",
    "q.l4#7.o1" to "It reduces the effective angle of each section and saves energy",
    "q.l4#7.o2" to "Better views",
    "q.l4#7.o3" to "You do not need the axe",
    "q.l4#7.e" to "Zig-zagging breaks a steep slope into several gentler sections, greatly reducing the load on calves and ankles and suiting the French (flat-foot) technique. The cost is distance, so adjust your time budget — one more reason to keep a margin in the turnaround time.",

    // ---------- l5 ----------
    "q.l5#0.p" to "What is the key point of the French (flat-foot) technique?",
    "q.l5#0.o0" to "Stab the ice with the front points only",
    "q.l5#0.o1" to "Lay every bottom point of the crampon flat on the slope, with the foot flat",
    "q.l5#0.o2" to "Hop up on one foot",
    "q.l5#0.o3" to "Edge the side of the boot into the ice",
    "q.l5#0.e" to "The French technique is about flat: all twelve bottom points engage and the load spreads through the thigh and the whole body, so it is the least tiring. That is why it suits long stretches of gentle snow.",

    "q.l5#1.p" to "Why is front-pointing (the German technique) the most tiring?",
    "q.l5#1.o0" to "Because it uses the arms",
    "q.l5#1.o1" to "Because the load sits on the front points and the calf has to work continuously",
    "q.l5#1.o2" to "Because you have to hold your breath",
    "q.l5#1.o3" to "Because friction is higher",
    "q.l5#1.e" to "Front-pointing puts your weight on two or three points, so the calf holds a sustained contraction to keep the position. It is extremely tiring and cannot be held for long — which is exactly why it is reserved for steep ground.",

    "q.l5#2.p" to "Which footwork should you use when traversing a snow slope?",
    "q.l5#2.o0" to "Front-pointing, kicking the points straight in",
    "q.l5#2.o1" to "The duck step: heels together, toes turned out, so the whole crampon lies on the slope",
    "q.l5#2.o2" to "Sideways jumps",
    "q.l5#2.o3" to "Crawling on your knees",
    "q.l5#2.e" to "The duck step lets the side points and the bottom points bite at the same time, so your weight is not concentrated on the inner points where it can slip. Lean slightly into the slope as you traverse.",

    "q.l5#3.p" to "Which terrain suits the French (flat-foot) technique best?",
    "q.l5#3.o0" to "Vertical ice",
    "q.l5#3.o1" to "Low to moderate angle hard snow, where you travel for hours",
    "q.l5#3.o2" to "Overhanging roofs",
    "q.l5#3.o3" to "Flat ground only",
    "q.l5#3.e" to "The French technique spreads load through the whole body and thigh, so it is the least tiring and the workhorse for low to moderate angles and long snow slopes. Steep ground needs front-pointing, but front-pointing cannot be sustained.",

    "q.l5#4.p" to "What happens if you front-point for a long time on a steep slope?",
    "q.l5#4.o0" to "It gets easier as you go",
    "q.l5#4.o1" to "The calf fatigues quickly until you can no longer hold the position",
    "q.l5#4.o2" to "The crampons fall off by themselves",
    "q.l5#4.o3" to "Nothing at all",
    "q.l5#4.e" to "Front-pointing concentrates your weight on two or three points and keeps the calf in sustained contraction, so fatigue comes fast. That is why it suits only short steep sections — and why your energy budget has to account for it when planning a route.",

    "q.l5#5.p" to "In the mixed (American) technique, how do the two feet divide the work?",
    "q.l5#5.o0" to "Both feet stay flat on the slope",
    "q.l5#5.o1" to "Both feet use the front points",
    "q.l5#5.o2" to "One foot flat for support, the other driving on the front points, alternating",
    "q.l5#5.o3" to "One foot does all the work while the other rests",
    "q.l5#5.e" to "The mixed technique bridges French and German: the flat foot gives stability and a moment of rest, the front-pointing foot provides drive. On moderate-to-steep slopes it keeps you efficient without exhausting the calves the way pure front-pointing does.",

    "q.l5#6.p" to "[Matching] Match each crampon class to the boot it belongs with.",
    "q.l5#6.l0" to "C1, full strap",
    "q.l5#6.l1" to "C2, strap front and clip rear",
    "q.l5#6.l2" to "C3, full clip",
    "q.l5#6.r0" to "B1 soft boot",
    "q.l5#6.r1" to "B2 semi-rigid boot",
    "q.l5#6.r2" to "B3 fully rigid boot",
    "q.l5#6.e" to "Boot and crampon must match: soft boots with C1, semi-rigid with C2, rigid with C3. Full-clip crampons on a soft boot let the boot flex, the clips lose purchase and the crampon can come off on a steep slope — a clearly dangerous setup.",

    "q.l5#7.p" to "What are the two most basic techniques for moving on ice?",
    "q.l5#7.o0" to "Flat-footing and side-stepping",
    "q.l5#7.o1" to "The flat-crampon technique (French) and the front-point technique (German)",
    "q.l5#7.o2" to "Hopping and glissading",
    "q.l5#7.o3" to "Ascent technique and descent technique",
    "q.l5#7.e" to "The flat-crampon technique engages every upright point except the front points; the front-point technique drives the front points straight into the ice. Complex terrain usually mixes the two — which is why you master both before touching the mixed technique.",

    "q.l5#8.p" to "With the flat-crampon (French) technique, which muscles take the load?",
    "q.l5#8.o0" to "The calves",
    "q.l5#8.o1" to "The thighs",
    "q.l5#8.o2" to "The forearms",
    "q.l5#8.o3" to "The lower back",
    "q.l5#8.e" to "Because the foot stays flat, the thighs and the whole body carry the load, so it is economical and can be sustained for hours. Front-pointing is the opposite: the load sits on two or three points and the calf does all the work — two very different energy accounts.",

    "q.l5#9.p" to "The flat-crampon (French) technique is particularly suited to which slope angle?",
    "q.l5#9.o0" to "0°–30°",
    "q.l5#9.o1" to "30°–50°",
    "q.l5#9.o2" to "50°–70°",
    "q.l5#9.o3" to "Above 70°",
    "q.l5#9.e" to "The manuals give 0°–30° explicitly. Any steeper and the foot can no longer stay flat, so you must switch to front points. Knowing the angle range for each technique is really knowing when to change technique.",

    // ---------- l6 ----------
    "q.l6#0.p" to "Where should your feet be during a self-arrest?",
    "q.l6#0.o0" to "Driving into the snow to brake",
    "q.l6#0.o1" to "Lifted off the snow, toes up, so all your weight goes through the axe",
    "q.l6#0.o2" to "Toes stabbed into the snow to anchor",
    "q.l6#0.o3" to "Together and flat on the snow",
    "q.l6#0.e" to "The moment a foot touches the snow it takes weight off the axe, braking efficiency collapses and you risk ankle and knee injury. Lift both feet so your full body weight passes through the pick into the snow.",

    "q.l6#1.p" to "You are sliding head-first with your feet uphill. What is the first thing to do?",
    "q.l6#1.o0" to "Try to grab the rope",
    "q.l6#1.o1" to "Roll immediately into a prone position with your feet downhill, then establish the arrest",
    "q.l6#1.o2" to "Keep sliding and wait for the speed to drop",
    "q.l6#1.o3" to "Throw your pack away first",
    "q.l6#1.e" to "Head-first, the pick cannot be pressed effectively into the snow, and a head-first impact is extremely dangerous. Use your trunk and core to roll into the prone arrest position first, then press the pick in.",

    "q.l6#2.p" to "What is the right way to learn self-arrest?",
    "q.l6#2.o0" to "Watching a video is enough",
    "q.l6#2.o1" to "Read the manual and memorise the key points",
    "q.l6#2.o2" to "Practise repeatedly on a safe soft snow slope with an instructor belaying, until it is instinct",
    "q.l6#2.o3" to "Learn it by crashing once on a real steep slope",
    "q.l6#2.e" to "Self-arrest is a reflex-level skill: it takes hundreds of repetitions in controlled conditions to become reliable. Practise on a gentle slope with a clean run-out, soft snow and an instructor on belay.",

    "q.l6#3.p" to "What is the most effective way to apply force in a self-arrest?",
    "q.l6#3.o0" to "Press down hard with the arms",
    "q.l6#3.o1" to "Press the pick down with your body weight, vertically",
    "q.l6#3.o2" to "Drag the shaft sideways across the snow",
    "q.l6#3.o3" to "Sweep the pick quickly across the surface",
    "q.l6#3.e" to "Arm strength fails under fatigue and panic; only body weight drives the pick deeper. That is why position — prone, feet lifted — matters more than brute force.",

    "q.l6#4.p" to "On hard snow or ice, how well does a self-arrest work?",
    "q.l6#4.o0" to "Better — it stops at once",
    "q.l6#4.o1" to "The stopping distance grows greatly and it may fail entirely",
    "q.l6#4.o2" to "No different from soft snow",
    "q.l6#4.o3" to "It turns into a glissade automatically",
    "q.l6#4.e" to "The pick struggles to bite on hard snow and ice. That is why you do not walk onto a steep hard-snow slope unprotected — technique cannot replace avoidance, and knowing a technique's limits matters just as much.",

    "q.l6#5.p" to "In a self-arrest, how should the two hands divide the work?",
    "q.l6#5.o0" to "Both hands on the shaft",
    "q.l6#5.o1" to "Both hands pressing the head",
    "q.l6#5.o2" to "One hand pressing the head near the pick for downward force, the other on the shaft for direction and stability",
    "q.l6#5.o3" to "One hand is enough; keep the other free",
    "q.l6#5.e" to "The hand on the head transmits body weight to the pick; the hand on the shaft stabilises and corrects direction. With the roles clear, the arrest is both powerful and straight.",

    "q.l6#6.p" to "[Order] Put the steps of a fall arrest in the correct order.",
    "q.l6#6.o0" to "Grip the axe firmly and press the head under your body in the arrest grip",
    "q.l6#6.o1" to "Roll into a prone position, head uphill and face to the snow",
    "q.l6#6.o2" to "Press the pick into the snow and ice with your body weight, legs apart, knees against the surface",
    "q.l6#6.o3" to "Lift both feet so the crampons cannot catch and throw you over",
    "q.l6#6.e" to "The step most often forgotten is the last one: lifting the feet. The moment a foot touches the snow it steals weight from the axe, and the crampons can suddenly bite and flip you over — interrupting the arrest itself.",

    "q.l6#7.p" to "During a self-arrest, where should the adze (the flat side of the head) sit?",
    "q.l6#7.o0" to "Outside the knee",
    "q.l6#7.o1" to "In the shoulder hollow",
    "q.l6#7.o2" to "At the hip",
    "q.l6#7.o3" to "Far out to the side of the head",
    "q.l6#7.e" to "With the adze at the shoulder hollow, the shaft lies near the body's midline and the load is centred under the trunk, which is where downward force works best. Further out, the load spreads, the pick wanders and the stopping distance grows markedly.",

    "q.l6#8.p" to "[Multiple choice] What mainly determines whether a fall arrest succeeds?",
    "q.l6#8.o0" to "The angle of the snow or ice",
    "q.l6#8.o1" to "The hardness of the snow or ice",
    "q.l6#8.o2" to "The falling climber's position",
    "q.l6#8.o3" to "Reaction speed",
    "q.l6#8.o4" to "The brand and price of the equipment",
    "q.l6#8.e" to "The manuals are candid: besides reaction speed, success depends on angle, hardness and position — 'sometimes even the most practised action cannot arrest the fall'. Accepting that limit is what makes it clear why not falling matters more than arresting.",

    "q.l6#9.p" to "What is the correct position of the legs and knees during an arrest?",
    "q.l6#9.o0" to "Legs together, knees off the ground",
    "q.l6#9.o1" to "Legs apart, knees pressed against the snow and ice",
    "q.l6#9.o2" to "One leg straight, the other bent",
    "q.l6#9.o3" to "Both legs raised off the snow",
    "q.l6#9.e" to "Legs apart give lateral stability and stop you rolling; knees against the surface add a support point that helps keep your weight on the axe. Note the difference: the knees may touch lightly, while the feet — and the crampons — must come up.",

    // ---------- l7 ----------
    "q.l7#0.p" to "What is the most effective way to prevent a slip while moving?",
    "q.l7#0.o0" to "Walk faster",
    "q.l7#0.o1" to "Use the axe for self-belay, giving yourself a temporary anchor with every step",
    "q.l7#0.o2" to "Put the axe away in the pack",
    "q.l7#0.o3" to "Rely on the rope alone",
    "q.l7#0.e" to "Self-belay is the most direct line of defence while moving: the axe hand plants the shaft in the snow with each step, creating a third point of contact. The overwhelming majority of slips happen at the moment that support is missing.",

    "q.l7#1.p" to "Your partner suddenly falls while you are moving together. What do you do first?",
    "q.l7#1.o0" to "Run down and grab them",
    "q.l7#1.o1" to "Go straight into the arrest position and take in rope to hold them",
    "q.l7#1.o2" to "Untie so you are not dragged",
    "q.l7#1.o3" to "Shout for help and wait",
    "q.l7#1.e" to "A rope team works because you hold yourself first — then the rope transmits the arrest. Running down or untying sends the whole team sliding, which is the classic chain failure in glacier accidents.",

    "q.l7#2.p" to "At the instant you lose your footing, what is the first action?",
    "q.l7#2.o0" to "Sort out your equipment",
    "q.l7#2.o1" to "Shout a warning and immediately roll prone to arrest",
    "q.l7#2.o2" to "Estimate the slope angle",
    "q.l7#2.o3" to "Look at what is below",
    "q.l7#2.e" to "The first two seconds decide the outcome. The warning brings your partners into a protective stance at the same moment that you roll prone — that roll is the core damage-limiting action.",

    "q.l7#3.p" to "When moving as a rope team, what state should the rope be in?",
    "q.l7#3.o0" to "As slack as possible for freedom of movement",
    "q.l7#3.o1" to "Moderately tensioned, without large loops hanging down",
    "q.l7#3.o2" to "Completely taut",
    "q.l7#3.o3" to "Whatever feels comfortable",
    "q.l7#3.e" to "Big loops mean the falling person first drops freely before the rope takes load, which multiplies the impact and lets the rope saw into the snow. Moderate tension lets the arrest engage earlier.",

    "q.l7#4.p" to "Why is 'do not slip' more fundamental than 'learn to arrest'?",
    "q.l7#4.o0" to "Because arrest technique is useless",
    "q.l7#4.o1" to "Because arrest can fail on hard snow and steep slopes — not losing your footing is the reliable protection",
    "q.l7#4.o2" to "Because arresting is too tiring",
    "q.l7#4.o3" to "Because instructors forbid practising it",
    "q.l7#4.e" to "Self-arrest is essential, but it has clear limits. The reliable strategy is not to enter terrain where you could slide without protection. Technique is the last line of defence, not the first.",

    "q.l7#5.p" to "During an arrest the pick bounces on hard snow and will not bite. What should you do?",
    "q.l7#5.o0" to "Lift it and swing again",
    "q.l7#5.o1" to "Stay prone and keep pressing with your body weight so the pick gradually bites",
    "q.l7#5.o2" to "Drag the shaft sideways across the snow",
    "q.l7#5.o3" to "Give up the arrest and protect your head",
    "q.l7#5.e" to "Lifting the axe cancels the arrest completely and costs you the pressing position you had built. Stay prone and keep pressing; the pick deepens its bite as you slide. Arrest is a progressive process, not a single action.",

    "q.l7#6.p" to "Why is arresting on ice said to be very difficult?",
    "q.l7#6.o0" to "Because ice is too cold",
    "q.l7#6.o1" to "Because the pick struggles to bite ice, so on ice slopes you fix a rope instead of relying on arrest",
    "q.l7#6.o2" to "Because friction on ice is too high",
    "q.l7#6.o3" to "Because ice breaks easily",
    "q.l7#6.e" to "Arrest depends on the pick biting, and ice is the hardest surface to bite. The manuals answer systemically: on angled ice, fix a route rope or use an alternating belay and generally do not move together — solve it with the system, not with hope in individual technique.",

    "q.l7#7.p" to "[Order] Your partner falls while moving together. What is the correct sequence?",
    "q.l7#7.o0" to "Go into the arrest position immediately and hold yourself",
    "q.l7#7.o1" to "Take in rope to arrest the fall",
    "q.l7#7.o2" to "Build an independent anchor (snow picket, buried axe, and so on)",
    "q.l7#7.o3" to "Transfer the load to the anchor, then start the rescue",
    "q.l7#7.e" to "The four steps cannot be reordered: you must hold yourself before you can do anything else, and rescuing without an anchor puts both people's weight on you. In reality these steps take minutes, so they have to be rehearsed beforehand.",

    "q.l7#8.p" to "The arrest worked and the slide has stopped. What comes next?",
    "q.l7#8.o0" to "Stand up and carry on",
    "q.l7#8.o1" to "Keep the arrest, build protection step by step and transfer your weight to the anchor",
    "q.l7#8.o2" to "Untie the rope",
    "q.l7#8.o3" to "Check whether the gear is damaged",
    "q.l7#8.e" to "A stopped slide is not safety — you are still in an unprotected position and would struggle to arrest again. Keep the arrest while you build reliable protection, free yourself, and only then deal with injuries and the route.",

    "q.l7#9.p" to "[Multiple choice] Which of these effectively prevent slips?",
    "q.l7#9.o0" to "Self-belaying with the axe continuously while moving",
    "q.l7#9.o1" to "Fixing a route rope on hard snow or ice slopes",
    "q.l7#9.o2" to "Holding a sustainable even pace and avoiding sudden efforts that break balance",
    "q.l7#9.o3" to "Moving at the slowest member's pace so the team does not string out",
    "q.l7#9.o4" to "Moving faster to shorten exposure",
    "q.l7#9.e" to "These four work at different levels: personal technique, system protection, pacing and team cohesion. Slip prevention is never one action — it is all of these layers at once.",

    // ---------- l8 ----------
    "q.l8#0.p" to "Why are accidents more frequent during the descent?",
    "q.l8#0.o0" to "Because downhill ground is harder",
    "q.l8#0.o1" to "Because fatigue degrades attention and movement quality",
    "q.l8#0.o2" to "Because the weather is always worse on the way down",
    "q.l8#0.o3" to "Because equipment fails",
    "q.l8#0.e" to "With the summit reached, alertness drops while the body is already near empty. A large share of mountaineering accidents happen on the descent — hence the saying that the summit is only half the journey.",

    "q.l8#1.p" to "Under what conditions may you glissade?",
    "q.l8#1.o0" to "Whenever the slope is steep enough",
    "q.l8#1.o1" to "No crevasses, no rockfall risk, a clear run-out below, and the ability to arrest at any moment",
    "q.l8#1.o2" to "On any snow slope",
    "q.l8#1.o3" to "Whenever your partners agree",
    "q.l8#1.e" to "A glissade is irreversible acceleration — once started it is hard to stop. You must rule out crevasses, rockfall and people below, and be sure you can roll into an arrest at any point. Otherwise, climb down properly.",

    "q.l8#2.p" to "What is the preferred way to descend technical ground?",
    "q.l8#2.o0" to "Climb down facing the slope, keeping three points of contact",
    "q.l8#2.o1" to "Run down facing out",
    "q.l8#2.o2" to "Glissade",
    "q.l8#2.o3" to "Sit and slide",
    "q.l8#2.e" to "Facing the slope lets you see your footholds, keeps your centre of mass close to the surface and leaves both hands free for support. Facing out hides your footholds — a very common mistake.",

    "q.l8#3.p" to "What is the most dangerous and common error on the descent?",
    "q.l8#3.o0" to "Facing the slope and climbing down on three points",
    "q.l8#3.o1" to "Leaning forward and climbing down facing out",
    "q.l8#3.o2" to "Keeping a steady rhythm",
    "q.l8#3.o3" to "Self-belaying with the axe",
    "q.l8#3.e" to "Facing out you cannot see your footholds, and leaning forward makes you less stable still. Add fatigue reducing leg control and you have the real reason descents are so accident-prone.",

    "q.l8#4.p" to "What must be done before starting a glissade?",
    "q.l8#4.o0" to "Put the axe away in the pack",
    "q.l8#4.o1" to "Confirm nobody is below, no crevasses or rockfall on the line, and keep the axe ready to arrest",
    "q.l8#4.o2" to "Tighten the pack straps",
    "q.l8#4.o3" to "Tell your family the itinerary",
    "q.l8#4.e" to "A glissade is irreversible acceleration. Before starting you must rule out people below, crevasses and rockfall, and keep the axe in your hand — otherwise, if something goes wrong, you have no way to slow down.",

    "q.l8#5.p" to "How do you manage team fatigue on a long descent?",
    "q.l8#5.o0" to "Walk straight through with as few stops as possible",
    "q.l8#5.o1" to "Take short scheduled breaks, drink and eat, and reassess the team's state",
    "q.l8#5.o2" to "Speed up to shorten exposure",
    "q.l8#5.o3" to "Stop only if someone is injured",
    "q.l8#5.e" to "The descent is the high-risk half, and fatigue is the main driver. Regular short breaks restore energy and let you re-read the weather, the route and your partners — judgements that are the first thing to disappear on a long push.",

    "q.l8#6.p" to "[Order] Put the steps of preparing a descent in a sensible order.",
    "q.l8#6.o0" to "Confirm the descent line and landing, and clear people from below",
    "q.l8#6.o1" to "Check that rope, belay device, carabiners and slings are all present",
    "q.l8#6.o2" to "Build a reliable anchor, or confirm the existing station",
    "q.l8#6.o3" to "Sort the rope to avoid knots and tangles, then start the descent",
    "q.l8#6.e" to "A descent hands your life to a single point, so the order is: decide where you are going, confirm the equipment, then commit. Sorting the rope matters just as much — a knot or tangle leaves you stuck hanging on the rope for a long time.",

    "q.l8#7.p" to "What mainly decides between rappelling and climbing down?",
    "q.l8#7.o0" to "The shorter the descent, the more you should rappel",
    "q.l8#7.o1" to "The difficulty of the terrain, the available anchors and the team's ability",
    "q.l8#7.o2" to "The weather",
    "q.l8#7.o3" to "How new the equipment is",
    "q.l8#7.e" to "Rappelling is fast but depends on anchors and execution; climbing down is slower but self-reliant. Terrain, anchor reliability and team skill decide together. Remember that rappelling has a high accident rate because the margin for operator error is so small.",

    "q.l8#8.p" to "What technical gear does a rappel normally require?",
    "q.l8#8.o0" to "One carabiner and one sling",
    "q.l8#8.o1" to "Several carabiners, a long sling or personal anchor, prusik cord and so on",
    "q.l8#8.o2" to "Just a rope",
    "q.l8#8.o3" to "Just a belay device",
    "q.l8#8.e" to "The manuals list several carabiners, a long sling or daisy chain, and prusik cord. A descent often means stripping anchors as you go and still keeping a backup — too little gear forces you to improvise high off the ground, which is exactly where accidents are born.",

    "q.l8#9.p" to "[Multiple choice] What are the main risks during a descent?",
    "q.l8#9.o0" to "Anchor failure",
    "q.l8#9.o1" to "Rappelling off the end of the rope because the ends were not knotted",
    "q.l8#9.o2" to "The rope jamming or tangling",
    "q.l8#9.o3" to "Rockfall and people below",
    "q.l8#9.o4" to "Descent is less risky than ascent because gravity helps",
    "q.l8#9.e" to "The first four are the usual causes of rappel accidents. The most overlooked is the unknotted rope end: if the rope is too short and the ends are free, you slide off the end without noticing and fall. That error is especially common on a tired descent.",

    // ---------- l9 ----------
    "q.l9#0.p" to "Which knot ties the rope to the harness and is the usual choice on glacier routes?",
    "q.l9#0.o0" to "Figure-8 follow-through",
    "q.l9#0.o1" to "Reef knot",
    "q.l9#0.o2" to "Overhand knot",
    "q.l9#0.o3" to "Bowline",
    "q.l9#0.e" to "The figure-8 follow-through is strong, easy to read and easy for others to check, and still comes apart after loading. A reef knot can slip or jam under load and must never be used for a life-bearing connection.",

    "q.l9#1.p" to "Which knot lets you adjust length one-handed to fix the rope to a carabiner?",
    "q.l9#1.o0" to "Double fisherman's",
    "q.l9#1.o1" to "Clove hitch",
    "q.l9#1.o2" to "Alpine butterfly",
    "q.l9#1.o3" to "Water knot",
    "q.l9#1.e" to "A clove hitch can be pushed and pulled to length on a carabiner with one hand, and is the standard way to self-anchor at a belay station. The double fisherman's joins two ropes; the butterfly makes a mid-rope attachment point.",

    "q.l9#2.p" to "What is the key property of a friction hitch such as the prusik?",
    "q.l9#2.o0" to "It grips the rope under load and slides along the rope when unloaded",
    "q.l9#2.o1" to "It can permanently replace the main rope",
    "q.l9#2.o2" to "It is only decorative",
    "q.l9#2.o3" to "It unties itself under load",
    "q.l9#2.e" to "One-way grip is what makes friction hitches useful for ascending, for backups and in mechanical-advantage systems. And because reliability depends on cord-to-rope diameter and the number of wraps, you must test it in the field before trusting it.",

    "q.l9#3.p" to "How much tail should be left after finishing a knot?",
    "q.l9#3.o0" to "About 1 cm is enough",
    "q.l9#3.o1" to "At least ten rope diameters",
    "q.l9#3.o2" to "No tail is needed",
    "q.l9#3.o3" to "As long as possible — at least 1 m",
    "q.l9#3.e" to "Enough tail is the basic safeguard against a knot slipping under load or working loose as it is shaken. Build the habit of checking each other too — knots are the only part of the protection system made entirely by hand, with no factory inspection.",

    "q.l9#4.p" to "Which knot joins two ropes or makes a prusik loop?",
    "q.l9#4.o0" to "Reef knot",
    "q.l9#4.o1" to "Double fisherman's",
    "q.l9#4.o2" to "Overhand knot",
    "q.l9#4.o3" to "Bowline",
    "q.l9#4.e" to "The double fisherman's is extremely stable and reluctant to work loose, but hard to untie after loading — which suits joining ropes and closing cord loops. A reef knot can slip under load and must never carry weight.",

    "q.l9#5.p" to "Why does a friction hitch's reliability depend on cord diameter?",
    "q.l9#5.o0" to "Diameter makes no difference",
    "q.l9#5.o1" to "If the cord is much thinner than the rope, contact area and clamping force are too small to grip",
    "q.l9#5.o2" to "The thinner the cord the better it grips",
    "q.l9#5.o3" to "The thicker the cord the better it grips",
    "q.l9#5.e" to "A friction hitch grips by squeezing the main rope. Too thin and both contact area and clamping force fall short; too thick and it will not wrap tightly. So check the combination every time, and test it somewhere safe before depending on it.",

    "q.l9#6.p" to "What is the alpine butterfly mainly used for?",
    "q.l9#6.o0" to "Joining two ropes",
    "q.l9#6.o1" to "Creating a fixed loop mid-rope that can take load in more than one direction",
    "q.l9#6.o2" to "Replacing the figure-8 as a harness tie-in",
    "q.l9#6.o3" to "Making a prusik loop",
    "q.l9#6.e" to "The butterfly forms a loop in the middle of the rope that holds load from either direction, which is why it appears in rope teams, glacier travel and rescue systems. It is also tied between climbers to add friction where the rope runs over snow.",

    "q.l9#7.p" to "[Matching] Match each knot to its main use.",
    "q.l9#7.l0" to "Figure-8 knot",
    "q.l9#7.l1" to "Double fisherman's",
    "q.l9#7.l2" to "Friction hitch (prusik)",
    "q.l9#7.l3" to "Bowline",
    "q.l9#7.r0" to "The usual tie-in to an anchor or harness",
    "q.l9#7.r1" to "Joining two ropes, or closing a cord loop",
    "q.l9#7.r2" to "A friction hitch: grips under load, slides when free",
    "q.l9#7.r3" to "Attaching to an anchor; also common when mooring a boat",
    "q.l9#7.e" to "These four cover most of glacier travel and basic protection. The manuals group them by function — attach to an anchor, join ropes, friction hitch. Learning them by function sticks far better than learning them by shape.",

    "q.l9#8.p" to "Which statement about knots and rope strength is correct?",
    "q.l9#8.o0" to "Knots do not affect rope strength",
    "q.l9#8.o1" to "Every knot reduces the rope's strength at that point, by different amounts",
    "q.l9#8.o2" to "Knots make the rope stronger",
    "q.l9#8.o3" to "A well-tied knot has no effect on strength",
    "q.l9#8.e" to "At a knot the rope bends, and under load the fibres carry unevenly, so strength always drops — only the amount varies. That is why the manuals print a table of strength loss by knot: choose a knot for how it works and for what it costs in strength.",

    "q.l9#9.p" to "The manual sums up the point of knots in one line: 'A knot gives the rope ( ).'",
    "q.l9#9.a0" to "life",
    "q.l9#9.a1" to "its life",
    "q.l9#9.e" to "The original reads 'a knot gives the rope life'. It captures the essence: a rope on its own is just a line, and only through knots — joining it to protection, anchors and other ropes — does it become a system that can carry a life.",

    // ---------- l10 ----------
    "q.l10#0.p" to "What is the ideal team size for glacier travel on a rope?",
    "q.l10#0.o0" to "2",
    "q.l10#0.o1" to "3",
    "q.l10#0.o2" to "6 or more",
    "q.l10#0.o3" to "One person alone",
    "q.l10#0.e" to "A three-person rope team has enough people to build an anchor and run a rescue system when one falls into a crevasse. With two, if one goes in, the other must arrest and build and haul at the same time — almost no margin.",

    "q.l10#1.p" to "What rope spacing is usual for glacier travel?",
    "q.l10#1.o0" to "2–3 m",
    "q.l10#1.o1" to "8–12 m",
    "q.l10#1.o2" to "More than 30 m",
    "q.l10#1.o3" to "As short as possible",
    "q.l10#1.e" to "8–12 m gives partners enough time and distance to react and arrest, while still allowing communication and cooperation. Too short and there is almost no rope to absorb the impact.",

    "q.l10#2.p" to "What does a rope team require before it actually provides protection?",
    "q.l10#2.o0" to "Simply being tied in makes you safe",
    "q.l10#2.o1" to "Partners who can arrest effectively and build protection",
    "q.l10#2.o2" to "A long enough rope",
    "q.l10#2.o3" to "A large enough team",
    "q.l10#2.e" to "Safety on a rope team comes from two actions done reliably: arresting and anchoring. A team without arrest skills or anchor technique is simply several people tied together falling into the same hole.",

    "q.l10#3.p" to "Why tie knots (such as the butterfly) between climbers on a glacier?",
    "q.l10#3.o0" to "Purely decoration",
    "q.l10#3.o1" to "To add friction where the rope runs over snow and limit how far a falling climber drops",
    "q.l10#3.o2" to "To recognise your partners",
    "q.l10#3.o3" to "To make the rope lighter",
    "q.l10#3.e" to "Each knot creates an extra drag point on the snow surface, which markedly shortens the drop and buys the partners above time to build protection. It is a very cheap, very effective brake.",

    "q.l10#4.p" to "Where should rescue gear be carried while travelling on a glacier?",
    "q.l10#4.o0" to "At the bottom of the pack",
    "q.l10#4.o1" to "Within reach, ready to use at any moment",
    "q.l10#4.o2" to "Left in the tent at camp",
    "q.l10#4.o3" to "Given to a partner to carry",
    "q.l10#4.e" to "The golden window in a crevasse rescue is a few minutes. If the prusik cords, carabiners and pickets are buried at the bottom of your pack, by the time you dig them out your partner may be hypothermic or the rope cut through the lip.",

    "q.l10#5.p" to "What is the main risk of a two-person rope team compared with three?",
    "q.l10#5.o0" to "It moves more slowly",
    "q.l10#5.o1" to "If one falls, the remaining person cannot both hold the arrest and run the rescue",
    "q.l10#5.o2" to "The rope is not long enough",
    "q.l10#5.o3" to "You need to carry more equipment",
    "q.l10#5.e" to "With two, if one goes into a crevasse the other must hold the arrest, build an anchor and work a hauling system at the same time — there is almost no margin. If you must travel as two, choose a more conservative route and plan further ahead.",

    "q.l10#6.p" to "Why should you not untie at will while travelling on a glacier?",
    "q.l10#6.o0" to "Because untying and retying is a nuisance",
    "q.l10#6.o1" to "Because the risk in crevasse terrain is continuous — the moment you untie you have no protection",
    "q.l10#6.o2" to "Because the rope might get lost",
    "q.l10#6.o3" to "Because your partners will complain",
    "q.l10#6.e" to "Risk on a glacier is unevenly distributed and hard to predict, and people usually untie on the misjudgement that 'this bit is fine'. If you really must untie, stop first, confirm the terrain and snow, then act as a team.",

    "q.l10#7.p" to "[Matching] Match the international climbing calls to their meaning.",
    "q.l10#7.l0" to "On belay",
    "q.l10#7.l1" to "Climbing",
    "q.l10#7.l2" to "Falling",
    "q.l10#7.l3" to "Off belay",
    "q.l10#7.r0" to "Belay is ready, you may start",
    "q.l10#7.r1" to "I am starting to climb",
    "q.l10#7.r2" to "I am falling (warning)",
    "q.l10#7.r3" to "Belay released, protection is over",
    "q.l10#7.e" to "The call system works because it needs no explanation. Wind is loud and distances are long at altitude, so short words with identical meaning on both sides remove ambiguity. The most dangerous moment in belaying is when each person assumes the other knows. The manuals list the international calls because they are the minimum agreement across teams and languages.",

    "q.l10#8.p" to "What basic technical equipment does a belayer need?",
    "q.l10#8.o0" to "One harness, one carabiner, one belay device, one pair of gloves, one helmet",
    "q.l10#8.o1" to "Just a belay device and a carabiner",
    "q.l10#8.o2" to "A helmet and sunglasses",
    "q.l10#8.o3" to "A harness and a rope",
    "q.l10#8.e" to "The list looks simple, but every missing item has a concrete consequence: no gloves and your hands get burned and your rope control suffers; no helmet and you have no answer to rockfall. A belayer is the person who catches others, so their own kit has to be complete first.",

    "q.l10#9.p" to "Why do a partner check before starting to climb?",
    "q.l10#9.o0" to "Because team discipline requires it",
    "q.l10#9.o1" to "Because mistakes in the harness, knot and belay device are often invisible to the person wearing them",
    "q.l10#9.o2" to "To record progress",
    "q.l10#9.o3" to "To warm up",
    "q.l10#9.e" to "Checking yourself, you see what you think you tied. A partner sees from behind and from the side, into the places you cannot see. The manuals put the partner check first in belay communication — it uses someone else's eyes to cover your blind spot.",

    // ---------- l11 ----------
    "q.l11#0.p" to "In the SRENE principles, what does the R stand for?",
    "q.l11#0.o0" to "Rapid",
    "q.l11#0.o1" to "Redundant",
    "q.l11#0.o2" to "Rope",
    "q.l11#0.o3" to "Rigid",
    "q.l11#0.e" to "Redundant means the system has several independent protection points, so if any one fails the others still carry the load. It is the most important single element of anchor safety.",

    "q.l11#1.p" to "What does the No Extension principle mean?",
    "q.l11#1.o0" to "The longer the rope the better",
    "q.l11#1.o1" to "If one point fails, the system must not extend and shock-load the rest",
    "q.l11#1.o2" to "Anchors should not be built low down",
    "q.l11#1.o3" to "No spare equipment is needed",
    "q.l11#1.e" to "If there is slack between points, a failure drops the load onto the remaining points as a sudden shock, far greater than static load. No Extension means equalising and pre-tensioning so that shock never enters the system.",

    "q.l11#2.p" to "What is the core idea behind anchor design?",
    "q.l11#2.o0" to "Use as little gear as possible",
    "q.l11#2.o1" to "A single point failing must not collapse the whole system",
    "q.l11#2.o2" to "Build as high as possible",
    "q.l11#2.o3" to "Use only the thickest rope",
    "q.l11#2.e" to "Rock and snow anchors can never be absolutely certain, so the system is designed to tolerate error: no single failure is fatal, which buys the climber time to react and a backup to fall back on.",

    "q.l11#3.p" to "Which two dimensions does EARNEST add to SRENE?",
    "q.l11#3.o0" to "Efficient and Timely",
    "q.l11#3.o1" to "Easy and Tight",
    "q.l11#3.o2" to "Equal and Nice",
    "q.l11#3.o3" to "Empty and True",
    "q.l11#3.e" to "An anchor must not only be safe, it must go in fast and handle simply — because the time spent building it is time spent exposed. That is exactly where EARNEST gets closer to real terrain than SRENE.",

    "q.l11#4.p" to "What does the reliability of a snow anchor mainly depend on?",
    "q.l11#4.o0" to "The brand of the gear",
    "q.l11#4.o1" to "Snow quality and how well it is buried",
    "q.l11#4.o2" to "The colour of the rope",
    "q.l11#4.o3" to "The altitude",
    "q.l11#4.e" to "The same picket or deadman holds vastly different loads in deep snow, wet snow and at the edge of a snow bridge. Snow anchors require reading the snowpack on the spot — a fixed procedure will not do.",

    "q.l11#5.p" to "Why does an anchor need equalised loading?",
    "q.l11#5.o0" to "To make the anchor look tidy",
    "q.l11#5.o1" to "So the load is shared among the points as designed and no single point is overloaded",
    "q.l11#5.o2" to "To save equipment",
    "q.l11#5.o3" to "To make it easier to dismantle",
    "q.l11#5.e" to "Equalising means each point carries close to its design load rather than one taking everything. If a point reaches its limit and fails, the load jumps suddenly to the others and can trigger a chain failure.",

    "q.l11#6.p" to "Which of these violates the redundancy principle?",
    "q.l11#6.o0" to "Using pieces of different strengths",
    "q.l11#6.o1" to "Two protection points that in fact depend on the same crack or the same block",
    "q.l11#6.o2" to "Connecting the points with slings",
    "q.l11#6.o3" to "Placing three protection points",
    "q.l11#6.e" to "Redundancy requires each point to fail independently. If two points share one crack, the crack opening takes both out at once — it looks like two, but works as one. This false redundancy is common and lethal.",

    "q.l11#7.p" to "[Matching] Match each anchor-assessment term to its meaning.",
    "q.l11#7.l0" to "S (Solid)",
    "q.l11#7.l1" to "R (Redundant)",
    "q.l11#7.l2" to "E (Equalized)",
    "q.l11#7.l3" to "No Extension",
    "q.l11#7.r0" to "Strong: each point can carry the expected load",
    "q.l11#7.r1" to "Redundant: several independent protection points",
    "q.l11#7.r2" to "Equalised: load shared sensibly among the points",
    "q.l11#7.r3" to "No extension: a failure does not create a shock-loading extension",
    "q.l11#7.e" to "These four form the basic framework, abbreviated SRENE. The order is worth remembering: first ask whether each point is solid, then whether the system is redundant — if a single point is unreliable, discussing redundancy is pointless.",

    "q.l11#8.p" to "Based on the load figures, what angle between sling legs should you aim for?",
    "q.l11#8.o0" to "Within 60°",
    "q.l11#8.o1" to "Within 90°",
    "q.l11#8.o2" to "Within 120°",
    "q.l11#8.o3" to "Angle does not affect load",
    "q.l11#8.e" to "At 0° each point carries about 50%, at 60° about 58%, at 90° about 71% — the wider the angle, the greater the load one person's weight puts on each point. The rule of thumb 'keep it within 60°' comes straight from those figures.",

    "q.l11#9.p" to "Why are efficiency and timeliness part of anchor assessment?",
    "q.l11#9.o0" to "To make the work look better",
    "q.l11#9.o1" to "Because building the anchor is itself time spent exposed to risk",
    "q.l11#9.o2" to "To save equipment",
    "q.l11#9.o3" to "To make teaching easier",
    "q.l11#9.e" to "While building an anchor you are often unprotected or poorly protected. The shorter that exposure, the lower the risk — so 'quick to build, simple to handle' is not laziness, it is part of the safety metric.",

    "q.l11#10.p" to "[Multiple choice] What does an adequate anchor look like?",
    "q.l11#10.o0" to "Each protection point is strong in itself",
    "q.l11#10.o1" to "The points fail independently of one another",
    "q.l11#10.o2" to "The load is shared sensibly among the points",
    "q.l11#10.o3" to "The system is left with slack to absorb shock",
    "q.l11#10.e" to "The first three are requirements; the last is the opposite. An anchor must have no extension, not reserve slack — slack lets one point failing shock-load the others, and shock loads are far greater than static ones.",

    "q.l11#11.p" to "If conditions allow only a single protection point, what is the right approach?",
    "q.l11#11.o0" to "Abandon the climb and go back the way you came",
    "q.l11#11.o1" to "Make it as reliable as you can and minimise the time the system spends on it",
    "q.l11#11.o2" to "Add any second point at all, to make two",
    "q.l11#11.o3" to "Tie the rope straight to your harness",
    "q.l11#11.e" to "Single-point situations really do occur — one good ice screw, for instance. The honest attitude is to admit it has no margin: make that point as good as it can be and move people past it quickly, rather than adding a useless second point that manufactures false confidence.",

    // ---------- l12 ----------
    "q.l12#0.p" to "Your partner falls into a crevasse. What is the first step?",
    "q.l12#0.o0" to "Jump in after them",
    "q.l12#0.o1" to "Go into self-arrest, build an anchor and transfer the load to it",
    "q.l12#0.o2" to "Call for help first",
    "q.l12#0.o3" to "Cut the rope",
    "q.l12#0.e" to "The fallen climber's full weight is on you right now. Arrest first to hold yourself, then build an independent anchor and transfer the load — only then do you have hands free for the rescue system. Jumping in or cutting the rope makes things worse immediately.",

    "q.l12#1.p" to "What is the most common mechanical-advantage system for rescue hauling?",
    "q.l12#1.o0" to "Direct 1:1 pulling",
    "q.l12#1.o1" to "The 3:1 Z-system (Z-pulley)",
    "q.l12#1.o2" to "A 10:1 system",
    "q.l12#1.o3" to "No advantage is needed",
    "q.l12#1.e" to "The 3:1 Z-system uses a prusik plus one pulley to gain three times the force. It is simple, quick to build and needs little gear, which is why it is the standard in crevasse rescue.",

    "q.l12#2.p" to "Why are snow bridges especially dangerous?",
    "q.l12#2.o0" to "Because they always make noise",
    "q.l12#2.o1" to "Because once covered by fresh snow they look like ordinary ground and are hard to identify",
    "q.l12#2.o2" to "Because they only appear at night",
    "q.l12#2.o3" to "Because they are always thin",
    "q.l12#2.e" to "A snow bridge is the most concealed glacier hazard: the surface looks smooth and thick while the space below is empty. Judging one means reading crack lines, snowpack structure and the season — which is precisely why you travel roped up.",

    "q.l12#3.p" to "What state should the rope be in while crossing crevasse terrain?",
    "q.l12#3.o0" to "Completely slack for freedom of movement",
    "q.l12#3.o1" to "Moderately tensioned, without large loops hanging down",
    "q.l12#3.o2" to "As tight as possible",
    "q.l12#3.o3" to "Roping up is unnecessary",
    "q.l12#3.e" to "Slack lets the falling climber drop freely before the rope loads, multiplying the impact and increasing the chance of the rope cutting into the lip. Moderate tension engages the arrest earlier and reduces that risk.",

    "q.l12#4.p" to "What is the safest way to cross a snow bridge?",
    "q.l12#4.o0" to "Run across alone, quickly",
    "q.l12#4.o1" to "Travel roped up with the rope tensioned, one person crossing while the others stand ready to arrest",
    "q.l12#4.o2" to "Avoid every snow bridge",
    "q.l12#4.o3" to "Stamp hard to test it, then cross",
    "q.l12#4.e" to "You cannot judge a snow bridge by looking at it. Roping up and being ready to arrest turns uncertainty into managed risk. Stamping hard to test it can simply collapse it under you.",

    "q.l12#5.p" to "While a partner hangs on the rope inside a crevasse, what is the greatest danger?",
    "q.l12#5.o0" to "Your partner falling asleep down there",
    "q.l12#5.o1" to "The loaded rope sawing through the snow lip until it suddenly fails",
    "q.l12#5.o2" to "Gear falling off",
    "q.l12#5.o3" to "A sudden change in weather",
    "q.l12#5.e" to "A loaded rope cuts back and forth across the lip, carving a deeper and deeper groove. That is the main source of time pressure in a rescue — you must haul or transfer the load to a sound anchor before the lip is cut through.",

    "q.l12#6.p" to "When building a Z-system with prusiks, why is a backup necessary?",
    "q.l12#6.o0" to "To make the system look complete",
    "q.l12#6.o1" to "If the main prusik fails you instantly lose the advantage and the climber drops again",
    "q.l12#6.o2" to "To add friction",
    "q.l12#6.o3" to "To save rope",
    "q.l12#6.e" to "A prusik grips by friction, and ice, dirt or rope wear can defeat it. A backup prusik catches the load if the main one fails, avoiding a second fall and the extra injury and delay that come with it.",

    "q.l12#7.p" to "[Order] Put the standard crevasse-rescue sequence in order.",
    "q.l12#7.o0" to "Self-arrest immediately and hold yourself",
    "q.l12#7.o1" to "Build an independent anchor",
    "q.l12#7.o2" to "Transfer the weight from your body to the anchor",
    "q.l12#7.o3" to "Haul with a 3:1 mechanical-advantage system",
    "q.l12#7.e" to "The four steps cannot be reordered. Step three is the one most often skipped: without transferring the load you must keep holding your partner with your body and have no hands to work the system — the most common reason rescues fail.",

    "q.l12#8.p" to "What should the person in the crevasse do?",
    "q.l12#8.o0" to "Shake the rope hard to attract attention",
    "q.l12#8.o1" to "Stay calm, try to prusik up, and avoid letting the rope keep cutting into the lip",
    "q.l12#8.o2" to "Untie immediately",
    "q.l12#8.o3" to "Climb down to look for a way out",
    "q.l12#8.e" to "The fallen climber's cooperation makes the rescue far easier. Shaking the rope worsens the sawing, and untying severs your only connection. Stay still, reduce the cutting, and where possible take some of your weight on a prusik.",

    "q.l12#9.p" to "[Multiple choice] Which rescue items should be on your person and within reach on a glacier?",
    "q.l12#9.o0" to "Prusik cord",
    "q.l12#9.o1" to "Carabiners and a pulley",
    "q.l12#9.o2" to "A snow picket or ice screw",
    "q.l12#9.o3" to "Slings",
    "q.l12#9.o4" to "Trekking poles",
    "q.l12#9.e" to "Together these four make the improvised system: prusik cord for one-way grip, carabiners and pulley for mechanical advantage, picket or screw for the anchor, slings for connection and extension. The critical part is within reach — gear at the bottom of the pack may as well not exist.",

    "q.l12#10.p" to "Why must the load be transferred to the anchor before hauling?",
    "q.l12#10.o0" to "To spread the load more evenly on the rope",
    "q.l12#10.o1" to "Because otherwise your hands stay committed to holding the arrest and cannot work the system",
    "q.l12#10.o2" to "To save energy",
    "q.l12#10.o3" to "To protect the rope",
    "q.l12#10.e" to "With the fallen climber's full weight on you, you must keep holding the arrest and can neither free your hands nor operate steadily. Handing the load to the anchor is the only way to stop being a human anchor and become the operator.",

    "q.l12#11.p" to "What role does the prusik play in a rescue system?",
    "q.l12#11.o0" to "Decoration",
    "q.l12#11.o1" to "One-way grip — it holds under load and slides along the rope when free",
    "q.l12#11.o2" to "It increases rope strength",
    "q.l12#11.o3" to "Waterproofing",
    "q.l12#11.e" to "One-way grip is exactly what makes a mechanical-advantage system possible: the prusik advances along the rope but will not run back under load. Its reliability depends on cord diameter and the number of wraps, so test it before you rely on it.",

    // ---------- l13 ----------
    "q.l13#0.p" to "Under the Lake Louise criteria, which symptom must be present to diagnose AMS?",
    "q.l13#0.o0" to "Headache plus at least one of nausea, dizziness, fatigue or insomnia",
    "q.l13#0.o1" to "Cough alone",
    "q.l13#0.o2" to "Sore legs alone",
    "q.l13#0.o3" to "An improved appetite alone",
    "q.l13#0.e" to "Headache is the core symptom of AMS. Fatigue or insomnia on their own are not enough; they must come together with headache. The practical value of the criteria is that you can score yourself in camp and act on it.",

    "q.l13#1.p" to "What is the correct response when AMS symptoms appear?",
    "q.l13#1.o0" to "Take a painkiller and continue up as planned",
    "q.l13#1.o1" to "Stop ascending; descend immediately if symptoms worsen",
    "q.l13#1.o2" to "Drink more coffee for energy and keep walking",
    "q.l13#1.o3" to "Ignore it and push through",
    "q.l13#1.e" to "AMS can progress to fatal HACE or HAPE. Stopping the ascent gives the body time to adapt; once symptoms worsen, descent is the only definitive treatment. Any plan to push through is a bet with your life.",

    "q.l13#2.p" to "The headache is gone after a painkiller. Can you continue ascending?",
    "q.l13#2.o0" to "Yes, the symptom has gone",
    "q.l13#2.o1" to "No — masking a symptom does not mean the body has acclimatised",
    "q.l13#2.o2" to "Yes, but walk more slowly",
    "q.l13#2.o3" to "Yes, as long as you drink more water",
    "q.l13#2.e" to "A painkiller suppresses the signal; the physiological stress of altitude continues. Ascending under that cover can let AMS progress to HACE or HAPE with no warning.",

    "q.l13#3.p" to "How long after arriving at altitude do AMS symptoms usually appear?",
    "q.l13#3.o0" to "Immediately",
    "q.l13#3.o1" to "6–12 hours",
    "q.l13#3.o2" to "After three days",
    "q.l13#3.o3" to "After a week",
    "q.l13#3.e" to "The timing matters: symptoms often begin after you reach camp, finish dinner and get ready for bed — and night is exactly when they are easiest to overlook and most likely to worsen.",

    "q.l13#4.p" to "What is the right field management for mild AMS?",
    "q.l13#4.o0" to "Continue ascending as planned",
    "q.l13#4.o1" to "Stop gaining height, rest at the current altitude, and descend if symptoms persist or worsen",
    "q.l13#4.o2" to "Take a painkiller and keep ascending",
    "q.l13#4.o3" to "Descend 2,000 m immediately",
    "q.l13#4.e" to "For mild AMS the first choice is to stop ascending and give the body time. A painkiller eases the headache but does not change acclimatisation. If symptoms persist or worsen after rest, descent is the definitive treatment.",

    "q.l13#5.p" to "Why does climb high, sleep low improve acclimatisation?",
    "q.l13#5.o0" to "Because daytime is warmer",
    "q.l13#5.o1" to "Daytime hypoxia provides the stimulus, while returning lower to sleep protects sleep quality",
    "q.l13#5.o2" to "Because you carry less gear",
    "q.l13#5.o3" to "Because travelling at night is safer",
    "q.l13#5.e" to "Acclimatisation needs hypoxic stress, but sleep quality is also a requirement — severe nocturnal hypoxia worsens periodic breathing and symptoms. Climb high, sleep low reconciles the two, which is why it works better than staying high throughout.",

    "q.l13#6.p" to "What is the worst consequence of continuing to ascend with AMS?",
    "q.l13#6.o0" to "You feel a bit more tired",
    "q.l13#6.o1" to "Progression to HACE or HAPE, which can be life-threatening within hours",
    "q.l13#6.o2" to "A poorer appetite",
    "q.l13#6.o3" to "Worse sleep",
    "q.l13#6.e" to "AMS usually settles with rest or descent, but it can be the precursor of critical illness. That is exactly why 'do not ascend with symptoms' is repeated so often — it blocks the first link of the whole deterioration chain.",

    "q.l13#7.p" to "When judging whether AMS is worsening, what should you watch most?",
    "q.l13#7.o0" to "Whether the headache has gone",
    "q.l13#7.o1" to "Whether symptoms are progressively worsening, especially consciousness, gait and breathing",
    "q.l13#7.o2" to "Whether body temperature is normal",
    "q.l13#7.o3" to "Whether the oxygen reading has risen",
    "q.l13#7.e" to "The turn from AMS to HACE/HAPE shows up in three dimensions: consciousness, gait and breathing. Watching those three is more reliable than watching a single symptom or one oximeter number.",

    "q.l13#8.p" to "What is typical of the headache in AMS?",
    "q.l13#8.o0" to "It is usually the first symptom",
    "q.l13#8.o1" to "It only appears at night",
    "q.l13#8.o2" to "It only appears during exertion",
    "q.l13#8.o3" to "It is usually the last symptom to appear",
    "q.l13#8.e" to "Headache is often the earliest signal and is a required element of the Lake Louise criteria. Because it is so common it is easily dismissed as ordinary tiredness — so the key is the context: it appeared after gaining altitude.",

    "q.l13#9.p" to "When acetazolamide is used to prevent altitude illness, what regimen does the manual recommend?",
    "q.l13#9.o0" to "250 mg three times daily",
    "q.l13#9.o1" to "125 mg twice daily, starting about a day before ascent and stopping about two days after",
    "q.l13#9.o2" to "500 mg once daily",
    "q.l13#9.o3" to "Only after symptoms appear",
    "q.l13#9.e" to "Following newer medical guidance, the recommended dose is 125 mg twice daily, lower than the older 250 mg three times daily. The lower dose works while being less likely to cause severe side effects. It is prescription-only and must follow medical advice.",

    "q.l13#10.p" to "Why is symptom relief after medication not a reason to keep ascending?",
    "q.l13#10.o0" to "Because the drug creates an illusion",
    "q.l13#10.o1" to "Because the drug relieves symptoms but does not improve acclimatisation to hypoxia",
    "q.l13#10.o2" to "Because the drug stops working",
    "q.l13#10.o3" to "Because the dose has to keep increasing",
    "q.l13#10.e" to "This is the most important idea in managing altitude illness: the symptom is the alarm, not the disease. Medication silences the alarm while the physiological stress of hypoxia keeps accumulating — ascending under that cover lets the illness advance silently.",

    "q.l13#11.p" to "[Multiple choice] Which conditions are easily confused with AMS and need careful differentiation?",
    "q.l13#11.o0" to "Dehydration",
    "q.l13#11.o1" to "Upper respiratory infections such as a cold",
    "q.l13#11.o2" to "Overfatigue",
    "q.l13#11.o3" to "Lack of sleep",
    "q.l13#11.o4" to "Snow blindness (ultraviolet keratitis)",
    "q.l13#11.e" to "All four cause headache, fatigue, nausea or poor sleep — heavily overlapping with AMS. The useful discriminators are whether symptoms appeared with the gain in altitude, whether they improve with rest, and whether gait or consciousness has changed.",

    "q.l13#12.p" to "According to clinical and guide sources, roughly what proportion of people above 4,000 m develop acute mountain sickness?",
    "q.l13#12.o0" to "5–10%",
    "q.l13#12.o1" to "20–30%",
    "q.l13#12.o2" to "50–65%",
    "q.l13#12.o3" to "Almost 100%",
    "q.l13#12.e" to "The higher and faster you go, the more common it is: about 50–65% of people above 4,000 m develop acute mountain sickness, and studies between 2,500 and 4,300 m give roughly 25–43%. Altitude illness is therefore normal, not exceptional — which is why a planned acclimatisation schedule is a necessity, not conservatism.",

    "q.l13#13.p" to "Which statement about age and altitude-illness risk is correct?",
    "q.l13#13.o0" to "Young people do not get altitude illness",
    "q.l13#13.o1" to "The older you are, the higher the risk must be",
    "q.l13#13.o2" to "Age does not significantly raise the risk; ascent rate and sleeping altitude are what matter",
    "q.l13#13.o3" to "Only unfit people get it",
    "q.l13#13.e" to "Studies show older trekkers at moderate altitude (average 65) have rates similar to younger people. What actually decides risk is ascent rate, sleeping altitude and individual physiology — blaming age or fitness is a dangerous misjudgement.",

    // ---------- l14 ----------
    "q.l14#0.p" to "Which signs should raise the alarm for HACE?",
    "q.l14#0.o0" to "Unsteady gait (cannot walk a straight line) and altered consciousness",
    "q.l14#0.o1" to "A mild headache",
    "q.l14#0.o2" to "A slightly poor appetite",
    "q.l14#0.o3" to "Mild aching in the legs",
    "q.l14#0.e" to "Ataxia and altered consciousness are the core markers of HACE: brain oedema is already affecting movement and cognition. With these signs you must descend immediately and seek medical support — no more watching and waiting.",

    "q.l14#1.p" to "What is the most typical early sign of HAPE?",
    "q.l14#1.o0" to "Breathlessness at rest, with a sharp drop in exercise capacity",
    "q.l14#1.o1" to "A slightly runny nose",
    "q.l14#1.o2" to "Slight numbness in the fingers",
    "q.l14#1.o3" to "Thirst",
    "q.l14#1.e" to "HAPE is characterised by being breathless even at rest. Unlike simple exhaustion it does not ease with rest, it keeps worsening, and it can progress to frothy sputum and cyanosis — a signal to descend immediately.",

    "q.l14#2.p" to "What is the fundamental treatment for HACE and HAPE?",
    "q.l14#2.o0" to "Take a painkiller and keep climbing",
    "q.l14#2.o1" to "Descend to a lower altitude immediately, with oxygen and other supportive measures",
    "q.l14#2.o2" to "Rest in place for two days",
    "q.l14#2.o3" to "Drink more water and sleep more",
    "q.l14#2.e" to "Descent is the only measure that reliably reverses the illness, because it removes the cause — hypoxia. Oxygen, a hyperbaric bag and drugs are adjuncts that buy time when descent cannot start immediately.",

    "q.l14#3.p" to "According to clinical sources, what is the usual dexamethasone regimen for treating HACE?",
    "q.l14#3.o0" to "8–10 mg initially, then 4 mg every 6 hours",
    "q.l14#3.o1" to "2 mg once daily",
    "q.l14#3.o2" to "10 mg every 2 hours",
    "q.l14#3.o3" to "Only if the patient is unconscious",
    "q.l14#3.e" to "This is a treatment dose and must be given under medical supervision. The drug buys time for the descent; it never replaces it. Descent remains the fundamental treatment for both HACE and HAPE.",

    "q.l14#4.p" to "Roughly how often do HAPE and HACE occur together?",
    "q.l14#4.o0" to "Almost never",
    "q.l14#4.o1" to "About 13–20% of HAPE cases also develop HACE",
    "q.l14#4.o2" to "In 100% of cases",
    "q.l14#4.o3" to "Only in children",
    "q.l14#4.e" to "The figure shows that the two critical forms of altitude illness often appear together. So when a team member shows signs of pulmonary oedema, watch consciousness and gait as well, prepare for the worst and descend immediately.",

    "q.l14#5.p" to "If a team member can no longer walk, what is the priority?",
    "q.l14#5.o0" to "Encourage them to keep walking",
    "q.l14#5.o1" to "Organise a carry, give oxygen, consider a hyperbaric chamber and descend as fast as possible",
    "q.l14#5.o2" to "Rest in place and wait for recovery",
    "q.l14#5.o3" to "Go back to camp for the gear first",
    "q.l14#5.e" to "Losing the ability to walk means critical illness. Descent then depends on the team carrying the patient or on outside rescue — so the real safety strategy is never letting anyone reach this point, which is exactly the value of recognising AMS early.",

    "q.l14#6.p" to "What does a portable hyperbaric chamber (such as a Gamow bag) do?",
    "q.l14#6.o0" to "Cures altitude illness completely",
    "q.l14#6.o1" to "Simulates a lower altitude to stabilise the patient when immediate descent is impossible",
    "q.l14#6.o2" to "Replaces descent",
    "q.l14#6.o3" to "Mainly provides warmth",
    "q.l14#6.e" to "A hyperbaric chamber buys time; it is not the endpoint of treatment. It can hold the illness in check in bad weather, while waiting for a helicopter, or when descent cannot start at once — but descent is still required in the end.",

    "q.l14#7.p" to "What is the right attitude to altitude-illness medication?",
    "q.l14#7.o0" to "If symptoms ease, keep ascending",
    "q.l14#7.o1" to "It is an adjunct that buys time, used on medical advice, and never replaces descent",
    "q.l14#7.o2" to "It can be shared freely with team mates",
    "q.l14#7.o3" to "The sooner the better, no medical assessment needed",
    "q.l14#7.e" to "These drugs have specific indications, contraindications and side effects, and ascending under their cover hides the signs of progression. The standard is use after medical assessment, with descent as the fundamental treatment.",

    "q.l14#8.p" to "What dose of dexamethasone is usual for high-altitude cerebral oedema?",
    "q.l14#8.o0" to "20 mg every 12 hours",
    "q.l14#8.o1" to "4 mg every 6 hours",
    "q.l14#8.o2" to "8 mg once daily",
    "q.l14#8.o3" to "10 mg every 2 hours",
    "q.l14#8.e" to "The manual gives 4 mg every 6 hours. It lowers intracranial pressure and eases cerebral oedema, usually with clear improvement within six hours — but it only buys time for the descent and never replaces it.",

    "q.l14#9.p" to "Does dexamethasone treat high-altitude pulmonary oedema?",
    "q.l14#9.o0" to "Yes, it is the first-choice drug",
    "q.l14#9.o1" to "No, it has no therapeutic effect on pulmonary oedema",
    "q.l14#9.o2" to "Yes, but the dose must be doubled",
    "q.l14#9.o3" to "It only works in children",
    "q.l14#9.e" to "This is easy to confuse: dexamethasone targets cerebral oedema and is ineffective for pulmonary oedema, while nifedipine targets pulmonary oedema and has limited effect on cerebral oedema. The two critical illnesses need different drugs — the wrong one is no treatment at all.",

    "q.l14#10.p" to "For high-altitude pulmonary oedema, what is the recommended nifedipine regimen and its important side effect?",
    "q.l14#10.o0" to "20–30 mg slow-release every 12 hours; blood pressure may drop quickly, so standing up fast can cause fainting",
    "q.l14#10.o1" to "4 mg every 6 hours; it makes people drowsy",
    "q.l14#10.o2" to "125 mg once daily; it raises blood pressure",
    "q.l14#10.o3" to "Intravenous only; no side effects",
    "q.l14#10.e" to "Nifedipine relieves the hypoxic pulmonary vasoconstriction and is used to prevent and treat pulmonary oedema. Its side effect is very practical: blood pressure can fall quickly, so standing up from sitting or lying can cause fainting — especially dangerous on a steep slope or getting up at night.",

    "q.l14#11.p" to "How should dexamethasone be given to an altitude-illness patient who keeps vomiting?",
    "q.l14#11.o0" to "Orally, at a higher dose",
    "q.l14#11.o1" to "It must be given by injection",
    "q.l14#11.o2" to "Under the tongue",
    "q.l14#11.o3" to "It cannot be given; just wait",
    "q.l14#11.e" to "Persistent vomiting means oral drugs are not absorbed and may simply be thrown up. The manual states clearly that injection is required — a reminder that the route of administration is itself something to think through in advance in any altitude emergency plan.",

    // ---------- l15 ----------
    "q.l15#0.p" to "Above 3,000 m, how much should sleeping altitude rise per day?",
    "q.l15#0.o0" to "No more than 500 m",
    "q.l15#0.o1" to "No more than 1,500 m",
    "q.l15#0.o2" to "As fast as possible",
    "q.l15#0.o3" to "There is no limit",
    "q.l15#0.e" to "Keeping the daily rise in sleeping altitude within 500 m, with a rest day roughly every 1,000 m, is the baseline advice repeated across international guidelines. It gives the body time to compensate. (Sources suggest values between 300 and 700 m; this course uses one of the more common sets.)",

    "q.l15#1.p" to "What does climb high, sleep low mean?",
    "q.l15#1.o0" to "Go higher during the day and return to a lower altitude to sleep",
    "q.l15#1.o1" to "Rest by day and travel by night",
    "q.l15#1.o2" to "Stay at the same altitude throughout",
    "q.l15#1.o3" to "Sleep only at the highest point",
    "q.l15#1.e" to "Daytime exposure at altitude stimulates red-cell production and respiratory adaptation, while returning lower to sleep eases symptoms and protects sleep quality. Combining the two is the most efficient way to acclimatise.",

    "q.l15#2.p" to "Which of these adds to the acclimatisation burden?",
    "q.l15#2.o0" to "Drinking enough water",
    "q.l15#2.o1" to "Alcohol or sedative medication",
    "q.l15#2.o2" to "Eating mainly carbohydrates",
    "q.l15#2.o3" to "Getting enough sleep",
    "q.l15#2.e" to "Alcohol and sedatives suppress respiratory drive and worsen nocturnal periodic breathing and hypoxia, sharply raising the risk of illness. At altitude, the quality of your breathing during sleep is itself part of acclimatisation.",

    "q.l15#3.p" to "What is the point of monitoring oxygen saturation with a pulse oximeter?",
    "q.l15#3.o0" to "It can replace symptom assessment entirely",
    "q.l15#3.o1" to "It gives an objective reference, especially for people with a history of altitude illness",
    "q.l15#3.o2" to "Only to keep a record",
    "q.l15#3.o3" to "It has no practical value",
    "q.l15#3.e" to "Saturation is a useful reference, but individual variation is wide and it cannot be the sole basis for decisions. Symptoms and functional state — can the person walk a straight line, can they function — remain the primary criterion.",

    "q.l15#4.p" to "For people at high risk of HAPE, which preventive drugs might a doctor consider?",
    "q.l15#4.o0" to "Nifedipine or sildenafil (a PDE inhibitor)",
    "q.l15#4.o1" to "Broad-spectrum antibiotics",
    "q.l15#4.o2" to "Ordinary painkillers",
    "q.l15#4.o3" to "Vitamin supplements",
    "q.l15#4.e" to "Both classes lower pulmonary artery pressure and are used to prevent HAPE in high-risk people, after medical assessment. They act at a different point from acetazolamide and cannot substitute for it.",

    "q.l15#5.p" to "Why is ascending too fast one of the strongest risk factors for altitude illness?",
    "q.l15#5.o0" to "Because it is tiring",
    "q.l15#5.o1" to "Because the body has no time to develop respiratory adaptation and increased red cells",
    "q.l15#5.o2" to "Because you carry more weight",
    "q.l15#5.o3" to "Because mountain weather changes quickly",
    "q.l15#5.e" to "Acclimatisation is the accumulation of a series of physiological compensations, and it takes time measured in days. When the ascent outruns the compensation, the gap shows up as symptoms — which is where every ascent-rate recommendation comes from.",

    "q.l15#6.p" to "What does drinking enough water do for acclimatisation?",
    "q.l15#6.o0" to "Only quenches thirst",
    "q.l15#6.o1" to "Maintains circulation and metabolism; dehydration markedly worsens symptoms",
    "q.l15#6.o2" to "Prevents pulmonary oedema",
    "q.l15#6.o3" to "Replaces preventive medication",
    "q.l15#6.e" to "Dry air and faster breathing at altitude increase fluid loss substantially, and dehydration thickens the blood, worsening the feeling of hypoxia and headache. Equally, avoid overdrinking — steady, adequate intake is the aim.",

    "q.l15#7.p" to "Why avoid overexertion at altitude?",
    "q.l15#7.o0" to "Because you tire quickly",
    "q.l15#7.o1" to "Overexertion can trigger HAPE, especially before acclimatisation",
    "q.l15#7.o2" to "Because it causes dehydration",
    "q.l15#7.o3" to "Because it slows the team down",
    "q.l15#7.e" to "Hard exercise pushes pulmonary artery pressure higher and is a clear trigger for HAPE in people who are not yet acclimatised. Controlling your pace is not only about saving energy; it lowers the risk of illness.",

    "q.l15#8.p" to "When should acetazolamide be started and stopped?",
    "q.l15#8.o0" to "Start on arrival at altitude and stop once acclimatised",
    "q.l15#8.o1" to "Start about a day before the ascent and stop about two days after",
    "q.l15#8.o2" to "Take it continuously for the whole trip",
    "q.l15#8.o3" to "Only after symptoms appear",
    "q.l15#8.e" to "Starting a day early means the drug is already working as you ascend; stopping about two days after ascent is because the body has begun to acclimatise on its own. Acetazolamide speeds acclimatisation; it does not replace it.",

    "q.l15#9.p" to "Does stopping acetazolamide cause symptoms to rebound?",
    "q.l15#9.o0" to "Yes, the dose must be tapered",
    "q.l15#9.o1" to "No, acclimatisation simply returns to its normal rate",
    "q.l15#9.o2" to "Yes, symptoms come back doubled",
    "q.l15#9.o3" to "It depends on the altitude",
    "q.l15#9.e" to "The manual states plainly that stopping does not cause a rebound — the rate of acclimatisation just returns to normal. That matters: it shows the drug is not suppressing anything, only accelerating the process for a while.",

    "q.l15#10.p" to "How is aspirin used to relieve altitude headache?",
    "q.l15#10.o0" to "500 mg once, after the headache starts",
    "q.l15#10.o1" to "Start one day before ascent, 320 mg three times daily until acclimatisation is complete",
    "q.l15#10.o2" to "100 mg once daily",
    "q.l15#10.o3" to "Only at bedtime",
    "q.l15#10.e" to "This is preventive use rather than take-it-when-it-hurts: start early, dose regularly, continue until the acclimatisation process is finished. Note that aspirin carries gastrointestinal and bleeding risks — it is a medical decision and should be assessed by a doctor.",

    "q.l15#11.p" to "What is the correct view of ginkgo extract for preventing altitude illness?",
    "q.l15#11.o0" to "It works better than acetazolamide and can replace it",
    "q.l15#11.o1" to "It has some preventive effect, but controlled trials show it is far less effective than acetazolamide",
    "q.l15#11.o2" to "It is completely ineffective",
    "q.l15#11.o3" to "It only works for cerebral oedema",
    "q.l15#11.e" to "The manual is cautious: some trials show symptom relief, but doses and conditions vary too much for a reliable dose, and head-to-head trials show it is much weaker than acetazolamide. Also note its interaction with anticoagulant drugs.",

    // ---------- l16 ----------
    "q.l16#0.p" to "What does it mean when shivering stops?",
    "q.l16#0.o0" to "The body has adapted to the cold",
    "q.l16#0.o1" to "Hypothermia is worsening — a danger sign",
    "q.l16#0.o2" to "You can keep moving",
    "q.l16#0.o3" to "You need to drink water immediately",
    "q.l16#0.e" to "Shivering is the body's last means of producing heat. When it stops, heat production has failed and core temperature is falling faster — the key boundary between mild and moderate or severe hypothermia, and a reason to act at once.",

    "q.l16#1.p" to "What is the correct field rewarming method for frostbite?",
    "q.l16#1.o0" to "Rub the area with snow",
    "q.l16#1.o1" to "Immerse in water at 37–40 °C for about 30 minutes, until the skin reddens and softens",
    "q.l16#1.o2" to "Warm it by a fire",
    "q.l16#1.o3" to "Apply a hot-water bottle directly",
    "q.l16#1.e" to "Frostbitten tissue contains ice crystals, and rubbing causes secondary cell damage; high heat burns skin that has lost sensation. Rapid rewarming in warm water is the only standard method — the uninjured hand or armpit can be used as an emergency measure.",

    "q.l16#2.p" to "When should frostbite not be rewarmed in the field?",
    "q.l16#2.o0" to "Always rewarm any frostbite",
    "q.l16#2.o1" to "When there is a risk of refreezing, since freeze-thaw-refreeze causes worse damage",
    "q.l16#2.o2" to "Never rewarm during the day",
    "q.l16#2.o3" to "Only mild frostbite should be rewarmed",
    "q.l16#2.e" to "A rewarm-refreeze cycle destroys far more tissue than staying frozen. So when further cold exposure is likely and warmth cannot be guaranteed, protect the area, avoid friction, and descend to somewhere sustained warmth is possible before rewarming.",

    "q.l16#3.p" to "Why avoid vigorous limb movement in moderate or worse hypothermia?",
    "q.l16#3.o0" to "Because it uses energy",
    "q.l16#3.o1" to "Because the cold heart muscle is easily thrown into arrhythmia",
    "q.l16#3.o2" to "Because it makes the patient irritable",
    "q.l16#3.o3" to "Because it worsens frostbite",
    "q.l16#3.e" to "This is the most counter-intuitive point in hypothermia care: making the patient walk is often fatal. In a cold heart the myocardium is highly irritable, and sudden limb movement or rough handling can trigger ventricular fibrillation outright.",

    "q.l16#4.p" to "What water temperature is correct for rewarming frostbite?",
    "q.l16#4.o0" to "0–5 °C",
    "q.l16#4.o1" to "20–25 °C",
    "q.l16#4.o2" to "37–40 °C",
    "q.l16#4.o3" to "Above 60 °C",
    "q.l16#4.e" to "Too cool and rewarming fails; too hot and skin without sensation is burned. 37–40 °C melts the ice crystals quickly without causing thermal injury. Rewarming is intensely painful and needs analgesia.",

    "q.l16#5.p" to "Why warm the trunk before the limbs in hypothermia?",
    "q.l16#5.o0" to "Because the limbs do not matter",
    "q.l16#5.o1" to "Warming the limbs sends cold peripheral blood back to the core, lowering core temperature further",
    "q.l16#5.o2" to "Because the trunk is easier to work on",
    "q.l16#5.o3" to "Because the limbs may already be frostbitten",
    "q.l16#5.e" to "This is one of the key principles of hypothermia care. Treating the limbs first drives cold peripheral blood back into the core, which can drop core temperature further and provoke arrhythmia — core first, limbs second.",

    "q.l16#6.p" to "What is the field management of mild hypothermia?",
    "q.l16#6.o0" to "Send them to hospital immediately",
    "q.l16#6.o1" to "Get out of wind and cold, change wet clothing, supply heat, and keep watching for deterioration",
    "q.l16#6.o2" to "Keep them walking to generate heat",
    "q.l16#6.o3" to "Rub the body with snow to stimulate circulation",
    "q.l16#6.e" to "A mildly hypothermic person can still generate heat, so the priority is stopping further heat loss and supplying energy. But keep watching: shivering stopping is usually a sign of progression to moderate hypothermia, not improvement.",

    "q.l16#7.p" to "Can you apply a hot-water bottle directly to frostbitten tissue?",
    "q.l16#7.o0" to "Yes, the faster the rewarming the better",
    "q.l16#7.o1" to "No — skin without sensation burns easily; use water at 37–40 °C only",
    "q.l16#7.o2" to "Yes, as long as it is wrapped in a towel",
    "q.l16#7.o3" to "Yes, as long as the temperature is not too high",
    "q.l16#7.e" to "Frostbitten skin has lost both pain and temperature sensation, so it cannot signal that something is too hot. A direct heat source easily adds a burn and can destroy tissue that might otherwise have recovered.",

    "q.l16#8.p" to "[Multiple choice] Which of these are wrong in hypothermia first aid?",
    "q.l16#8.o0" to "Giving the patient alcohol to warm them up",
    "q.l16#8.o1" to "Making a severely hypothermic patient walk to generate heat",
    "q.l16#8.o2" to "Rubbing frostbitten limbs vigorously",
    "q.l16#8.o3" to "Warming the limbs before the trunk",
    "q.l16#8.o4" to "Moving the patient out of the wind and changing wet clothing",
    "q.l16#8.e" to "The first four are all wrong, each for its own reason: alcohol dilates peripheral vessels and accelerates heat loss; walking can trigger arrhythmia in severe hypothermia; rubbing causes secondary damage to frostbitten tissue; and warming the limbs sends cold blood to the core and lowers core temperature further.",

    "q.l16#9.p" to "What is the core priority order in hypothermia care?",
    "q.l16#9.o0" to "Warm the limbs first, then the trunk",
    "q.l16#9.o1" to "Warm the trunk core first, while avoiding rough handling and vigorous limb movement",
    "q.l16#9.o2" to "Give the patient hot water first",
    "q.l16#9.o3" to "Remove all clothing first",
    "q.l16#9.e" to "Core first is the first principle: once the trunk is warm the heart and brain can function again and the blood can safely be sent to the limbs. Reversing the order directly lowers core temperature further.",

    "q.l16#10.p" to "What is the correct aftercare once frostbite has been rewarmed?",
    "q.l16#10.o0" to "Pierce the blisters to relieve pressure",
    "q.l16#10.o1" to "Do not pierce the blisters; dress loosely with sterile material and avoid weight-bearing",
    "q.l16#10.o2" to "Massage vigorously to improve circulation",
    "q.l16#10.o3" to "Put the area next to a heat source immediately",
    "q.l16#10.e" to "Rewarmed tissue is extremely fragile: blisters are a natural dressing and piercing invites infection, massage causes mechanical damage, and heat burns skin without sensation. Protect it, keep it dry, avoid weight-bearing and get to medical care.",

    "q.l16#11.p" to "What long-term sequelae can frostbite leave?",
    "q.l16#11.o0" to "Usually full recovery with no after-effects",
    "q.l16#11.o1" to "Cold sensitivity, abnormal sensation and abnormal sweating, possibly taking months or longer to settle",
    "q.l16#11.o2" to "Only cosmetic effects",
    "q.l16#11.o3" to "Only a loss of athletic ability",
    "q.l16#11.e" to "Frostbite damages deep tissue and nerve endings, so even when the skin looks recovered, cold sensitivity, numbness, tingling and abnormal sweating can persist long term. That is exactly why preventing frostbite matters far more than treating it.",

    // ---------- l17 ----------
    "q.l17#0.p" to "How should you swing an ice tool?",
    "q.l17#0.o0" to "Hack hard with the upper arm",
    "q.l17#0.o1" to "Swing from the wrist so the pick enters the ice vertically",
    "q.l17#0.o2" to "Hammer the surface with the adze",
    "q.l17#0.o3" to "Cut into the ice horizontally",
    "q.l17#0.e" to "A wrist swing drives the pick in vertically, fast: it bites more easily and costs less energy. Hacking with the whole arm tends to land the pick at an angle, shattering the surface into a shell that cannot hold.",

    "q.l17#1.p" to "In ice climbing, what does three-point contact mean?",
    "q.l17#1.o0" to "Two hands and one foot (or two feet and one hand) hold three stable contacts while the fourth moves",
    "q.l17#1.o1" to "Three people climb together",
    "q.l17#1.o2" to "Three knots share the load",
    "q.l17#1.o3" to "The rack must have three attachment points",
    "q.l17#1.e" to "Three-point contact is the movement rule shared by ice and rock: always keep three reliable contacts and move only one. That way, if a contact fails, you still have support.",

    "q.l17#2.p" to "What is typical of WI4?",
    "q.l17#2.o0" to "Low-angle ice you can walk up",
    "q.l17#2.o1" to "Nearly vertical with short vertical steps, and protection that may be poor",
    "q.l17#2.o2" to "All overhangs",
    "q.l17#2.o3" to "You only need one walking pole",
    "q.l17#2.e" to "WI4 means the ground is close to vertical with short vertical sections, and the places you can place a screw may not be good. It demands better technique and judgement. WI1–WI2 is learning terrain.",

    "q.l17#3.p" to "Why be sparing with swings when ice climbing?",
    "q.l17#3.o0" to "To save energy",
    "q.l17#3.o1" to "Beaten ice turns into a shell that cannot hold",
    "q.l17#3.o2" to "Because the tool wears out",
    "q.l17#3.o3" to "Because it disturbs your partners",
    "q.l17#3.e" to "Every missed swing leaves a crater. Hammering repeatedly destroys the load-bearing ice over a whole panel and forces you to hang on your arms instead — a vicious circle.",

    "q.l17#4.p" to "Why is ice climbing more dangerous than sport climbing?",
    "q.l17#4.o0" to "Because it is colder",
    "q.l17#4.o1" to "Ice screws can rip out under load, and the ice changes from day to day",
    "q.l17#4.o2" to "Because there is no protection",
    "q.l17#4.o3" to "Because you cannot use a rope",
    "q.l17#4.e" to "A well-placed nut or bolt in rock stays reliable; a screw depends on the ice itself, and ice melts, turns brittle and develops voids — a placement that was solid yesterday may mean nothing today.",

    "q.l17#5.p" to "Why get your feet stable before swinging the tool?",
    "q.l17#5.o0" to "Because arms tire faster than legs",
    "q.l17#5.o1" to "The feet carry the weight and provide the rest; the arms only assist",
    "q.l17#5.o2" to "Because ice tools are expensive",
    "q.l17#5.o3" to "Because it looks more professional",
    "q.l17#5.e" to "Arm strength drains very fast on ice; the feet are what can carry weight for hours. Swinging before the feet are set burns out your arms early and actually increases the chance of falling off.",

    "q.l17#6.p" to "Under what conditions does ice typically turn bad?",
    "q.l17#6.o0" to "After a cold night",
    "q.l17#6.o1" to "After strong sun or rising temperature, when the ice softens and becomes honeycombed",
    "q.l17#6.o2" to "Just after fresh snow",
    "q.l17#6.o3" to "When the wind picks up",
    "q.l17#6.e" to "Ice is a function of temperature. Hard morning ice takes precise placements; afternoon slush feels easy but its screws pull out more readily. Judging ice means weighing time of day, aspect, temperature and sun history.",

    "q.l17#7.p" to "Before placing an ice screw, what should you confirm?",
    "q.l17#7.o0" to "Whether the screw is a visible colour",
    "q.l17#7.o1" to "Whether the ice there is solid, with no voids or honeycombing",
    "q.l17#7.o2" to "Whether it photographs well",
    "q.l17#7.o3" to "How far it is above the ground",
    "q.l17#7.e" to "A screw's strength comes from the ice, not from technique. A screw in a void or honeycombed ice can barely hold a fall — this is the most fundamental difference between ice and rock protection.",

    "q.l17#8.p" to "Your forearms are pumping out on an ice pitch. What should you do?",
    "q.l17#8.o0" to "Climb faster to get through it",
    "q.l17#8.o1" to "Get to a stance as soon as you can, put your weight on your feet and shake out your arms",
    "q.l17#8.o2" to "Grip harder to stay stable",
    "q.l17#8.o3" to "Back off immediately",
    "q.l17#8.e" to "Pump is forearm ischaemia; keep going and you lose grip altogether. The right response is to move weight onto your feet while you can still control it and let blood return — which is what 'don't let your feet be lazy' really means in practice.",

    "q.l17#9.p" to "[Matching] Match each WI water-ice grade to its typical character.",
    "q.l17#9.l0" to "WI2",
    "q.l17#9.l1" to "WI3",
    "q.l17#9.l2" to "WI4",
    "q.l17#9.l3" to "WI5",
    "q.l17#9.r0" to "Sustained ice around 60° with possible bulges; good protection",
    "q.l17#9.r1" to "Sustained 60–75°; usually good protection but strenuous",
    "q.l17#9.r2" to "Nearly vertical with short vertical steps; protection may be poor",
    "q.l17#9.r3" to "Sustained vertical; poor protection and very demanding",
    "q.l17#9.e" to "A WI grade combines three variables: angle, protection quality and physical cost. The higher the grade, the less room there is to retreat or self-rescue — which is why the grade is only a reference and the day's ice and team condition decide the outcome.",

    "q.l17#10.p" to "[Multiple choice] Which gear should be on your harness, within reach, when ice climbing?",
    "q.l17#10.o0" to "Several ice screws",
    "q.l17#10.o1" to "Carabiners and quickdraws",
    "q.l17#10.o2" to "Prusik cord",
    "q.l17#10.o3" to "A belay device",
    "q.l17#10.o4" to "A spare sleeping bag",
    "q.l17#10.e" to "Ice climbing means building protection as you move, so anything buried in the pack may as well not exist. The manual's rescue kit list — screws, carabiners, slings, pulley, prusiks, ascender — follows the same logic: everything you might need stays within reach.",

    "q.l17#11.p" to "Why can an ice screw rip out?",
    "q.l17#11.o0" to "Because the screw is too short",
    "q.l17#11.o1" to "Because the ice itself may contain voids, be honeycombed or be melting, and cannot hold",
    "q.l17#11.o2" to "Because too much is clipped to it",
    "q.l17#11.o3" to "Because the screw is blunt",
    "q.l17#11.e" to "The strength comes from the ice, not the placement. A screw in a void or honeycombed ice can barely take a fall — the essential difference from rock protection, and the reason you check the ice before you place.",

    "q.l17#12.p" to "Why is an ice grade only a reference?",
    "q.l17#12.o0" to "Because grades are arbitrary",
    "q.l17#12.o1" to "Because the ice changes daily — sun, temperature and season can markedly alter the same route",
    "q.l17#12.o2" to "Because grades differ between countries",
    "q.l17#12.o3" to "Because grades only describe length",
    "q.l17#12.e" to "Ice is a function of temperature: hard morning ice needs precise placements, while soft afternoon ice looks easy but its screws pull out more easily. The same route can vary by more than a grade — so what you see in front of you always outranks the number in the guidebook.",

    "q.l17#13.p" to "[Order] Put the three-point-contact rhythm of ice climbing in the correct order.",
    "q.l17#13.o0" to "Read the ice and choose where the tool and feet will go",
    "q.l17#13.o1" to "Kick the front points in to establish both feet",
    "q.l17#13.o2" to "With the feet stable, swing the tool and confirm it is solid",
    "q.l17#13.o3" to "With three points stable, move the fourth",
    "q.l17#13.e" to "This order explains why 'don't let your feet be lazy' is the core discipline of ice climbing: feet carry weight for hours, arms only assist. Swinging before the feet are set exhausts the arms early — on steep ice that is fatal.",

    // ---------- l18 ----------
    "q.l18#0.p" to "On which slope angles do avalanches cluster most?",
    "q.l18#0.o0" to "10°–25°",
    "q.l18#0.o1" to "34°–45°",
    "q.l18#0.o2" to "55°–70°",
    "q.l18#0.o3" to "Vertical ice",
    "q.l18#0.e" to "Statistics show the great majority of avalanches occur between 34° and 45° (96% fall within 30–50°). That is exactly steep enough to slide while still able to hold snow — the danger window, and the angle mountaineering routes most often cross.",

    "q.l18#1.p" to "Why do most accidents happen at danger level 3, considerable?",
    "q.l18#1.o0" to "Because the snowpack is at its most unstable",
    "q.l18#1.o1" to "Because conditions look acceptable and are most easily underestimated",
    "q.l18#1.o2" to "Because everyone stays home",
    "q.l18#1.o3" to "Because the forecast is inaccurate",
    "q.l18#1.e" to "The paradox of level 3 is that avalanches are genuinely possible while the terrain looks 'fine', so large numbers of people enter avalanche terrain. At levels 4 and 5 most people stay away, so the share of accidents drops. The most dangerous condition is never the extreme one — it is the moderate one that gets underestimated.",

    "q.l18#2.p" to "What is the avalanche trio?",
    "q.l18#2.o0" to "Transceiver (beacon), probe and shovel",
    "q.l18#2.o1" to "Helmet, rope and harness",
    "q.l18#2.o2" to "Axe, crampons and ice screws",
    "q.l18#2.o3" to "Tent, sleeping bag and mat",
    "q.l18#2.e" to "The transceiver locates, the probe pinpoints and the shovel digs. All three are needed, and all three have to be practised if you are to complete a rescue inside the ten-odd-minute golden window.",

    "q.l18#3.p" to "Why are slopes that do not look steep often the most dangerous?",
    "q.l18#3.o0" to "Because the snow is deeper",
    "q.l18#3.o1" to "Because 34–45° is where avalanches cluster, and people systematically underestimate angle",
    "q.l18#3.o2" to "Because people move faster on them",
    "q.l18#3.o3" to "Because the sun is stronger",
    "q.l18#3.e" to "Below about 30° it is too gentle for slab avalanches; above about 50° snow does not accumulate. The danger window falls exactly in the range that feels walkable — which is precisely why it is underestimated.",

    "q.l18#4.p" to "What is the right way to cross avalanche terrain?",
    "q.l18#4.o0" to "Move the whole team through quickly together",
    "q.l18#4.o1" to "Spread out, cross one at a time, post a watcher and plan an escape route",
    "q.l18#4.o2" to "Take the shortest line along the valley floor",
    "q.l18#4.o3" to "Stay where the snow is deepest",
    "q.l18#4.e" to "One at a time limits the risk to a single person, and a watcher can locate and organise a rescue immediately. Everyone crossing together means one trigger buries the whole team — the worst possible outcome.",

    "q.l18#5.p" to "You hear a whumpf as the snowpack collapses. What does it mean?",
    "q.l18#5.o0" to "You merely stepped in a hole",
    "q.l18#5.o1" to "There is an easily triggered weak layer and the snowpack is unstable",
    "q.l18#5.o2" to "The snow is deep and travel is good",
    "q.l18#5.o3" to "The snowpack has stabilised",
    "q.l18#5.e" to "A whumpf is the sound of the snowpack collapsing as a weak layer fails. It is a very direct stability signal — carrying on onto that slope means using yourself to test whether it will release as a slab.",

    "q.l18#6.p" to "Why are slab avalanches more deadly than loose-snow avalanches?",
    "q.l18#6.o0" to "Because they are colder",
    "q.l18#6.o1" to "A whole slab releases at once and buries you, leaving almost no chance of self-rescue",
    "q.l18#6.o2" to "Because they are louder",
    "q.l18#6.o3" to "Because they happen more often",
    "q.l18#6.e" to "A slab breaks across the whole slope at once, so you lose your support while still on the face. Once buried, the weight of the snow and its rapid setting make self-rescue nearly impossible — which is why companion rescue has to be immediate.",

    "q.l18#7.p" to "How should a transceiver be carried and used?",
    "q.l18#7.o0" to "Anywhere in the pack is fine",
    "q.l18#7.o1" to "Check each other's transmit status before setting out, and rehearse search routines regularly",
    "q.l18#7.o2" to "Carried by the team leader only",
    "q.l18#7.o3" to "Switched off to save battery",
    "q.l18#7.e" to "A transceiver in a pack is nearly useless — under the snow your arms may not move at all, so it must be worn on the body, usually on the chest. The search routine also has to be rehearsed, or you will not locate anyone within the golden ten minutes.",

    "q.l18#8.p" to "Before entering avalanche terrain, what is the most important preparation?",
    "q.l18#8.o0" to "Having all the gear is enough",
    "q.l18#8.o1" to "Read the day's avalanche forecast and keep adjusting route and plan from field observations",
    "q.l18#8.o2" to "Trust personal experience completely",
    "q.l18#8.o3" to "Follow the tracks someone else left",
    "q.l18#8.e" to "The forecast gives a regional judgement, field observation gives slope-scale evidence; you need both. Following old tracks is especially dangerous — they may be hours old, and the snowpack has already changed.",

    "q.l18#9.p" to "According to the statistics, which cause accounts for the most mountaineering fatalities?",
    "q.l18#9.o0" to "Avalanche first, then falls",
    "q.l18#9.o1" to "Falls first, then avalanche",
    "q.l18#9.o2" to "Illness first, then rockfall",
    "q.l18#9.o3" to "Hypothermia first, then avalanche",
    "q.l18#9.e" to "The manual is explicit: falls first, avalanche second. That ordering matters — avalanches are feared most, but the everyday slip is what kills most people. Rank risks by data, not by impression.",

    "q.l18#10.p" to "After a burial, roughly how long is the golden rescue window?",
    "q.l18#10.o0" to "About ten to fifteen minutes",
    "q.l18#10.o1" to "Two hours",
    "q.l18#10.o2" to "Six hours",
    "q.l18#10.o3" to "24 hours",
    "q.l18#10.e" to "Ten to fifteen minutes — a timescale that means the rescue must be done by your partners, because organised rescue will arrive far too late. That is why the trio has to be worn, and practised, rather than merely packed.",

    "q.l18#11.p" to "[Multiple choice] Which field signals are worth watching when judging avalanche risk?",
    "q.l18#11.o0" to "A whumpf as the snowpack collapses",
    "q.l18#11.o1" to "Fresh cracks appearing on the slope",
    "q.l18#11.o2" to "Recent new snow or obvious wind loading",
    "q.l18#11.o3" to "Audible settling and sinking underfoot on the way up",
    "q.l18#11.o4" to "Cirrus cloud and excellent visibility",
    "q.l18#11.e" to "These are direct evidence that stability is falling right now. Their value is immediacy: the forecast gives a regional picture, while these signals describe the slope under your feet at this moment. You need both.",

    "q.l18#12.p" to "The image shows three sections of the same mountain. Tap the section with the highest avalanche risk.",
    "q.l18#12.e" to "Avalanches cluster between 34° and 45°. The gentle slope on the left (about 16°) is too flat for slab avalanches; the steep one on the right (about 60°) is too steep for snow to build a thick slab. Only the middle slope at about 40° sits in the window where snow both accumulates and can slide — and that is exactly the angle climbing routes most often cross, which is why it is so easily underestimated.",

    // ---------- l19 ----------
    "q.l19#0.p" to "What is the purpose of setting a turnaround time?",
    "q.l19#0.o0" to "To turn back unconditionally at that hour and avoid being taken hostage by the objective",
    "q.l19#0.o1" to "To calculate your climbing speed",
    "q.l19#0.o2" to "To decide how much food to carry",
    "q.l19#0.o3" to "A formality",
    "q.l19#0.e" to "A turnaround time takes the decision out of on-the-spot emotion: a rule set while you were rational enforces judgement for you when you are tired and reluctant. It is the most effective tool against summit fever.",

    "q.l19#1.p" to "What typically causes summit fever?",
    "q.l19#1.o0" to "Very good weather",
    "q.l19#1.o1" to "Sunk cost plus team pressure distorting judgement",
    "q.l19#1.o2" to "Inadequate equipment",
    "q.l19#1.o3" to "Too low an altitude",
    "q.l19#1.e" to "Time, money and effort already invested make it hard to admit you should stop; silence or mutual encouragement in the team suppresses doubt further. Understanding the mechanism is the precondition for setting objective rules in advance.",

    "q.l19#2.p" to "When should a team settle its retreat decision?",
    "q.l19#2.o0" to "Before departure, agreeing objective triggers and who decides",
    "q.l19#2.o1" to "At the summit",
    "q.l19#2.o2" to "When danger appears, by improvising",
    "q.l19#2.o3" to "On the spot by the fittest person",
    "q.l19#2.e" to "Debating retreat while tired, hypoxic and emotional almost always tips towards continuing. Agree objective triggers in advance — a time, a weather change, a type of team condition — and name who has the final say.",

    "q.l19#3.p" to "Why do so many accidents happen on the descent?",
    "q.l19#3.o0" to "Because downhill ground is harder",
    "q.l19#3.o1" to "Because alertness drops once the goal is met, while the body is already near its limit",
    "q.l19#3.o2" to "Because the weather is always worse on the way down",
    "q.l19#3.o3" to "Because equipment fails",
    "q.l19#3.e" to "'The summit is only half the journey' really means the trip's risk is released on the way down. Roping up, belaying and pacing on the descent cannot be relaxed just because you summited.",

    "q.l19#4.p" to "What is the value of agreeing the retreat decision in advance?",
    "q.l19#4.o0" to "It saves time",
    "q.l19#4.o1" to "It removes the decision from fatigue and emotion and lets your pre-departure judgement execute",
    "q.l19#4.o2" to "It gives the leader more authority",
    "q.l19#4.o3" to "It avoids arguments",
    "q.l19#4.e" to "Deciding while hypoxic, tired and reluctant almost always tips towards continuing. Agreeing objective triggers and decision rights in advance is letting the calm version of you decide for the exhausted version.",

    "q.l19#5.p" to "Why must a retreat plan be written into the climb plan?",
    "q.l19#5.o0" to "To make the plan look complete",
    "q.l19#5.o1" to "Retreat needs gear, a route and a time budget; improvised decisions leave no time to prepare",
    "q.l19#5.o2" to "To satisfy an inspection",
    "q.l19#5.o3" to "Because regulations require it",
    "q.l19#5.e" to "Retreat is a real technical operation: it may need an anchor, a rappel and movement in the dark. If the plan never budgeted time and equipment for it, retreat becomes a high-risk improvisation.",

    "q.l19#6.p" to "When team members disagree about the route or the weather, what is the right approach?",
    "q.l19#6.o0" to "Majority vote",
    "q.l19#6.o1" to "Adopt the most conservative view until new evidence convinces everyone",
    "q.l19#6.o2" to "Let the fittest person decide",
    "q.l19#6.o3" to "Vote, then stop discussing it",
    "q.l19#6.e" to "In high-risk settings the most conservative view should carry weight. Majority voting suppresses a minority's legitimate concern — and the most common line in accident reviews is 'someone felt uneasy but nobody said anything'.",

    "q.l19#7.p" to "Which view of 'with a guide you are safe' is correct?",
    "q.l19#7.o0" to "A guide makes you absolutely safe",
    "q.l19#7.o1" to "A guide reduces risk but cannot remove objective hazards; members still need to keep judging",
    "q.l19#7.o2" to "Guides only show the way; safety is your own job",
    "q.l19#7.o3" to "Members need not judge anything",
    "q.l19#7.e" to "A guide's value is experience and decision quality, but avalanches, rockfall and weather do not disappear because someone is leading. Members who understand the risk, spot danger signs and speak up are themselves part of the team's safety capacity.",

    "q.l19#8.p" to "What is goal creep in mountaineering?",
    "q.l19#8.o0" to "Lowering the route's difficulty grade",
    "q.l19#8.o1" to "Gradually relaxing the safety standards you set, in order to reach the summit",
    "q.l19#8.o2" to "Changing the target peak mid-trip",
    "q.l19#8.o3" to "Reducing team size",
    "q.l19#8.e" to "Goal creep is the classic signature of summit fever: the turnaround keeps sliding, the acceptable weather window keeps widening, symptoms keep being tolerated. The only defence is to quantify the standards in advance, so that relaxing them becomes explicit and has to be explained to your partners.",

    "q.l19#9.p" to "[Multiple choice] What should a complete climb plan contain?",
    "q.l19#9.o0" to "Route and schedule, including the turnaround time",
    "q.l19#9.o1" to "Retreat plan and alternative routes",
    "q.l19#9.o2" to "Team condition assessment and role allocation",
    "q.l19#9.o3" to "Communication method, contact person and emergency procedure",
    "q.l19#9.o4" to "A media and publicity plan",
    "q.l19#9.e" to "The first four are all required. The ones most often skipped are the second and fourth — because they are not needed when things go well. But a plan earns its value precisely when things go badly, and by then there is no time to write it.",

    "q.l19#10.p" to "Why budget spare days into an itinerary?",
    "q.l19#10.o0" to "To absorb delays such as a later weather window or a team member feeling unwell",
    "q.l19#10.o1" to "To rest more",
    "q.l19#10.o2" to "To save money",
    "q.l19#10.o3" to "To make the itinerary look comfortable",
    "q.l19#10.e" to "High-altitude trips almost always slip: weather refuses to cooperate, someone needs an extra acclimatisation day, the approach is slower than expected. Without margin, any delay forces you to cut acclimatisation or lengthen daily stages — both sharply raise the risk.",

    "q.l19#11.p" to "[Order] Put the steps of building a climb plan in a sensible order.",
    "q.l19#11.o0" to "Fix the objective and route; gather information and historical weather",
    "q.l19#11.o1" to "Assess team ability and time; schedule the acclimatisation rhythm",
    "q.l19#11.o2" to "Set the turnaround time and quantifiable retreat triggers",
    "q.l19#11.o3" to "Write the retreat plan and emergency procedure, and brief the home contact",
    "q.l19#11.e" to "The order says: set the objective, check capability, draw the red line, then keep the exit. Many people reverse it — objective first, exit last — which is why the exit ends up at the bottom of the list and never gets designed properly.",

    "q.l19#12.p" to "Why is descent time so often underestimated?",
    "q.l19#12.o0" to "Because downhill is faster",
    "q.l19#12.o1" to "Because you are worn out, the surface may be worse, and you still have to belay and clean the gear",
    "q.l19#12.o2" to "Because maps are inaccurate",
    "q.l19#12.o3" to "Because guides hurry you",
    "q.l19#12.e" to "The ascent may have taken six hours, but the descent often takes longer: less energy, softer or icier snow, poorer visibility, and possibly rappels and gear recovery. Estimating descent from ascent time is one of the commonest planning errors.",

    "q.l19#13.p" to "Why spell out communication and contact arrangements in the plan?",
    "q.l19#13.o0" to "For the record",
    "q.l19#13.o1" to "Because if you go missing, the people at home need to know where to search and when to start",
    "q.l19#13.o2" to "To report to the company",
    "q.l19#13.o3" to "To satisfy permit requirements",
    "q.l19#13.e" to "The hardest part of search and rescue is not knowing where the person is. Itinerary, route, alternatives and check-in times are what compress a search from days to hours — and that information can only be provided before you leave.",

    "q.l19#14.p" to "How does team size affect the plan?",
    "q.l19#14.o0" to "Size is irrelevant to planning",
    "q.l19#14.o1" to "More people means slower movement, heavier logistics and harder-to-synchronise acclimatisation",
    "q.l19#14.o2" to "More people is safer, so no adjustment is needed",
    "q.l19#14.o3" to "More people is faster",
    "q.l19#14.e" to "A big team shares manpower and resources, at the cost of speed and flexibility: everyone has their own rhythm, and the team can only move at the slowest pace. Team size belongs in your timing estimate — not in a complaint afterwards.",

    "q.l19#15.p" to "Fill in: high-altitude itineraries usually budget about ( )% spare days.",
    "q.l19#15.a0" to "20",
    "q.l19#15.a1" to "30",
    "q.l19#15.a2" to "25",
    "q.l19#15.a3" to "20-30",
    "q.l19#15.a4" to "20–30",
    "q.l19#15.a5" to "twenty",
    "q.l19#15.e" to "The usual recommendation is 20–30% margin. A ten-day trip, for example, should be planned as twelve or thirteen days for supplies, leave and permits — which looks conservative until you compare it with how often delays actually happen.",

    // ---------- l20 ----------
    "q.l20#0.p" to "What is the first principle of rescue?",
    "q.l20#0.o0" to "Move the casualty as quickly as possible",
    "q.l20#0.o1" to "Make the scene safe so you do not create a second casualty",
    "q.l20#0.o2" to "Photograph the scene first",
    "q.l20#0.o3" to "Give the casualty water first",
    "q.l20#0.e" to "Around rockfall, avalanches, crevasses or steep ground, rushing to the casualty often turns the rescuer into a second casualty and halves the available manpower. Assessing the scene is the first step and the one you cannot skip.",

    "q.l20#1.p" to "Where does the correct emergency sequence start?",
    "q.l20#1.o0" to "Make the scene safe first, then assess injuries",
    "q.l20#1.o1" to "Move the casualty to safety first",
    "q.l20#1.o2" to "Look for food and water",
    "q.l20#1.o3" to "Build a rope system",
    "q.l20#1.e" to "The standard sequence is safety, assessment, calling for help, treatment, transfer. Skipping the safety assessment and going straight to the casualty is the most common rescue error.",

    "q.l20#2.p" to "Why does prevention matter far more than rescue at altitude?",
    "q.l20#2.o0" to "Because rescue is expensive",
    "q.l20#2.o1" to "Because rescue is limited by weather, oxygen and manpower and often cannot arrive in time",
    "q.l20#2.o2" to "Because rescue teams are unwilling",
    "q.l20#2.o3" to "Because there is no phone signal",
    "q.l20#2.e" to "Altitude degrades both sides: helicopters are limited by turbulence and height, ground teams need hours to arrive, and a casualty deteriorates faster in hypoxia and cold. That time gap is the only rescue resource you actually have.",

    "q.l20#3.p" to "Why does mountain rescue often take hours or days?",
    "q.l20#3.o0" to "Because teams are unwilling to go",
    "q.l20#3.o1" to "Strict limits from weather, oxygen, communication and manpower; helicopters are constrained by turbulence and altitude",
    "q.l20#3.o2" to "Because the distances are too great",
    "q.l20#3.o3" to "Because it costs too much",
    "q.l20#3.e" to "At altitude a helicopter struggles with lift and turbulence, and a ground team needs hours to reach you. That gap means one thing: up high, you are your own first rescue team.",

    "q.l20#4.p" to "What is the point of leaving an itinerary and a contact person?",
    "q.l20#4.o0" to "A formality",
    "q.l20#4.o1" to "If you go missing, rescuers know where to search, which sharply shortens the search",
    "q.l20#4.o2" to "To make expense claims easier",
    "q.l20#4.o3" to "To comply with rules",
    "q.l20#4.e" to "The hardest part of search and rescue is not knowing where the person is. Itinerary, route, alternative plans and contact arrangements are what compress a search from days to hours.",

    "q.l20#5.p" to "In casualty assessment, what is treated first?",
    "q.l20#5.o0" to "Splinting fractures",
    "q.l20#5.o1" to "Life-threatening problems such as airway and breathing",
    "q.l20#5.o2" to "Recording the injuries in detail",
    "q.l20#5.o3" to "Cleaning visible wounds",
    "q.l20#5.e" to "Assessment follows life-threats-first: airway, breathing and circulation before fractures and wounds that are not immediately fatal. Get the order wrong and everything else matters much less.",

    "q.l20#6.p" to "At altitude, why is insulation a critical part of first aid?",
    "q.l20#6.o0" to "Because it makes the casualty comfortable",
    "q.l20#6.o1" to "Because an immobilised casualty loses heat fast, which worsens the injury",
    "q.l20#6.o2" to "Because regulations require it",
    "q.l20#6.o3" to "To make carrying easier",
    "q.l20#6.e" to "In cold and hypoxia, a casualty who cannot move loses heat production quickly. Hypothermia deepens shock and masks symptoms, so insulating from the ground, blocking wind and changing wet clothing matter as much as stopping bleeding.",

    "q.l20#7.p" to "What should the team's emergency plan be when communications fail?",
    "q.l20#7.o0" to "Wait in place until contact resumes",
    "q.l20#7.o1" to "Agree in advance a rendezvous, a lost-contact deadline and the follow-up actions",
    "q.l20#7.o2" to "Split up and search immediately",
    "q.l20#7.o3" to "Everyone descend at once",
    "q.l20#7.e" to "Losing communications in the mountains is normal, not exceptional. Agreeing in advance what happens if you have not checked in by a certain time prevents panic on the ground and tells the home contact when to raise the alarm.",

    "q.l20#8.p" to "What is the right attitude to first-aid and rescue training?",
    "q.l20#8.o0" to "Watching a tutorial and memorising the steps is enough",
    "q.l20#8.o1" to "You must rehearse hands-on regularly; reading alone will not carry into a real scene",
    "q.l20#8.o2" to "Only the leader needs it",
    "q.l20#8.o3" to "It is only for professional rescuers",
    "q.l20#8.e" to "First aid and rescue are highly procedural skills, and under pressure you revert to the level you actually trained at. Reading builds the framework; only repeated rehearsal keeps the actions correct when you are frightened.",

    "q.l20#9.p" to "[Order] Put the standard casualty assessment and treatment sequence in order.",
    "q.l20#9.o0" to "Make the scene safe so you do not create a second casualty",
    "q.l20#9.o1" to "Assess consciousness, airway, breathing and circulation",
    "q.l20#9.o2" to "Treat immediate life threats: bleeding, insulation, splinting",
    "q.l20#9.o3" to "Call for help and arrange transfer, or wait for professional rescue",
    "q.l20#9.e" to "Steps one and four are the ones most often skipped — under stress people run straight to the casualty. But an unsafe scene turns the rescuer into a second casualty and halves your manpower, and without calling for help there is no backup for anything that follows.",

    "q.l20#10.p" to "[Multiple choice] What key information should a call for help include?",
    "q.l20#10.o0" to "Exact location (coordinates or an identifiable landmark)",
    "q.l20#10.o1" to "Number of casualties, consciousness and breathing status",
    "q.l20#10.o2" to "Terrain and weather on scene",
    "q.l20#10.o3" to "Available communication method and check-in times",
    "q.l20#10.o4" to "The casualty's climbing CV",
    "q.l20#10.e" to "These four decide what gets sent, how much and by which route. A vague location wastes hours, unknown injuries mean the wrong kit, and unknown weather can put the rescue team in danger too. Calling for help is a communication skill worth rehearsing.",

    "q.l20#11.p" to "Why is helicopter rescue at altitude often impossible?",
    "q.l20#11.o0" to "Because it is too expensive",
    "q.l20#11.o1" to "Because thin air reduces lift and payload, turbulence is severe and weather windows are short",
    "q.l20#11.o2" to "Because pilots refuse to fly there",
    "q.l20#11.o3" to "Because there are no airways at altitude",
    "q.l20#11.e" to "A helicopter's lift comes from air, and the air is thin up high — which directly limits how much it can lift and how high it can operate. Add turbulent mountain air and fast-changing weather and the flyable window may be only tens of minutes. That is why rescue cannot be your plan.",

    "q.l20#12.p" to "[Matching] Match each first-aid measure to when it applies.",
    "q.l20#12.l0" to "Insulation",
    "q.l20#12.l1" to "Bleeding control",
    "q.l20#12.l2" to "Splinting",
    "q.l20#12.l3" to "Oxygen",
    "q.l20#12.r0" to "A priority for any casualty at altitude, to stop hypothermia deepening shock",
    "q.l20#12.r1" to "First response to an open wound or limb bleeding",
    "q.l20#12.r2" to "Suspected fracture or joint injury, to avoid further damage when moving",
    "q.l20#12.r3" to "Breathing difficulty, clearly low saturation or suspected pulmonary oedema",
    "q.l20#12.e" to "All four are basic actions at altitude rather than specialist procedures. What they share is that they need no complex equipment but do need the right order — insulation, for instance, often comes late in general first aid but is a priority up high.",

    "q.l20#13.p" to "Why assess the risk of the rescue itself?",
    "q.l20#13.o0" to "Because rescue is tiring",
    "q.l20#13.o1" to "Because the rescue may put more people in danger and lower overall survival odds",
    "q.l20#13.o2" to "Because insurance requires it",
    "q.l20#13.o3" to "Because regulations require it",
    "q.l20#13.e" to "Rescue decisions are resource allocation: if reaching the casualty injures two rescuers, you go from one casualty and two rescuers to three casualties and nobody. That is not coldness; it is the arithmetic that maximises overall survival.",

    "q.l20#14.p" to "When should self-rescue stop and professional rescue be awaited?",
    "q.l20#14.o0" to "Keep self-rescuing as long as you have strength",
    "q.l20#14.o1" to "When self-rescue risks further injury, or conditions exceed the team's ability",
    "q.l20#14.o2" to "Only when completely exhausted",
    "q.l20#14.o3" to "Never stop self-rescuing",
    "q.l20#14.e" to "Self-rescue is about buying time, not about taking chances. When continuing could injure the casualty or the rescuers more severely, or when a storm makes moving riskier than staying, holding the situation and waiting for backup is the better answer.",

    "q.l20#15.p" to "Fill in: in the SAMPLE assessment, E stands for ( ).",
    "q.l20#15.a0" to "event",
    "q.l20#15.a1" to "Event",
    "q.l20#15.a2" to "the event",
    "q.l20#15.a3" to "incident",
    "q.l20#15.e" to "E stands for Event — what happened. This item is often undervalued: the mechanism (how the fall occurred, whether the head was struck, how long the burial lasted) points directly at the likely injuries, and is a key clue in assessment.",

    // ---------- m01 ----------
    "q.m01#0.p" to "Roughly how much does air temperature fall for every 1,000 m of ascent?",
    "q.m01#0.o0" to "About 1.5 °C",
    "q.m01#0.o1" to "About 3 °C",
    "q.m01#0.o2" to "About 6.5 °C",
    "q.m01#0.o3" to "About 10 °C",
    "q.m01#0.e" to "Temperature drops about 6.5 °C per 1,000 m — the environmental lapse rate. It explains the height of the snowline and why a 5,000 m peak stays snow-covered even in summer.",

    "q.m01#1.p" to "What is the fundamental cause of hypoxia at altitude?",
    "q.m01#1.o0" to "The proportion of oxygen in the air is lower",
    "q.m01#1.o1" to "Air pressure falls, so the partial pressure of oxygen in each breath drops",
    "q.m01#1.o2" to "Ultraviolet light breaks down the oxygen",
    "q.m01#1.o3" to "The air thins and oxygen is replaced by other gases",
    "q.m01#1.e" to "This is a very common misconception. Oxygen is still about 21% of the air at altitude — the proportion does not change. What changes is pressure: with lower pressure there are fewer oxygen molecules in the same volume, so partial pressure falls and the body receives less oxygen.",

    "q.m01#2.p" to "[Multiple choice] Which of these are typical features of a high-altitude environment?",
    "q.m01#2.o0" to "Low pressure and low oxygen partial pressure",
    "q.m01#2.o1" to "Low temperature with a large day-night swing",
    "q.m01#2.o2" to "Markedly stronger ultraviolet radiation",
    "q.m01#2.o3" to "Extremely dry air",
    "q.m01#2.o4" to "A significantly lower proportion of oxygen in the air",
    "q.m01#2.e" to "The first four are right, and they amplify each other: cold plus hypoxia means the body struggles both to make heat and to get oxygen; dryness plus strong UV damages airways, skin and eyes faster. Kit and itinerary have to cover all four at once.",

    "q.m01#3.p" to "Sea-level pressure is about 1,013 hPa. What is the pressure at 5,000 m?",
    "q.m01#3.o0" to "About 900 hPa",
    "q.m01#3.o1" to "About 700 hPa",
    "q.m01#3.o2" to "About 540 hPa",
    "q.m01#3.o3" to "About 300 hPa",
    "q.m01#3.e" to "At 5,000 m the pressure is roughly half of sea level. Each breath therefore contains about half the oxygen molecules — the body compensates by raising breathing rate and heart rate, which is the physical reason you are breathless and slower up high.",

    "q.m01#4.p" to "Fill in: temperature falls by about ( ) °C for every 1,000 m of ascent.",
    "q.m01#4.a0" to "6.5",
    "q.m01#4.a1" to "six point five",
    "q.m01#4.e" to "6.5 °C per 1,000 m. The figure is genuinely useful in planning: walking from a 3,000 m base camp to 5,000 m means roughly 13 °C colder, which directly decides how thick your down jacket and sleeping bag need to be.",

    "q.m01#5.p" to "[Order] Put the causal chain of altitude hypoxia in order.",
    "q.m01#5.o0" to "Air pressure falls, lowering the oxygen partial pressure you inhale",
    "q.m01#5.o1" to "Arterial oxygen saturation drops",
    "q.m01#5.o2" to "The body compensates by raising breathing and heart rate",
    "q.m01#5.o3" to "Sustained hypoxia may progress to altitude illness",
    "q.m01#5.e" to "This chain is the skeleton of altitude medicine: environment, physiology, compensation, decompensation. Once you see it, AMS, HACE and HAPE stop being separate facts and become different stages along one chain.",

    "q.m01#6.p" to "What is the reflectance of fresh snow?",
    "q.m01#6.o0" to "About 20%",
    "q.m01#6.o1" to "About 40%",
    "q.m01#6.o2" to "About 60%",
    "q.m01#6.o3" to "About 80–90%",
    "q.m01#6.e" to "Fresh snow reflects roughly 80–90% of solar radiation. UV exposure on a snowfield is therefore almost double — direct from above plus reflected from the surface. That is why snow blindness and severe sunburn are so common in the mountains.",

    "q.m01#7.p" to "Why is sun protection at altitude mandatory rather than optional?",
    "q.m01#7.o0" to "Because the sun is closer to the earth up there",
    "q.m01#7.o1" to "Because UV rises with altitude and snow reflects it back onto your face",
    "q.m01#7.o2" to "Because the ozone layer is thinner so visible light is stronger",
    "q.m01#7.o3" to "Because cold weakens the skin's resistance",
    "q.m01#7.e" to "UV intensity rises about 10–12% per 1,000 m, and snow adds another 80–90% reflection. Together the dose far exceeds a low-altitude site at the same latitude. Sunscreen, lip balm and UV400 goggles are equipment, not extras.",

    "q.m01#8.p" to "Dry air at altitude has one easily overlooked consequence. What is it?",
    "q.m01#8.o0" to "Better skin",
    "q.m01#8.o1" to "Insensible water loss through breathing and sweating, worsening dehydration and altitude symptoms",
    "q.m01#8.o2" to "A bigger appetite",
    "q.m01#8.o3" to "Deeper sleep",
    "q.m01#8.e" to "Dry air plus faster breathing continuously strips moisture from the airways, and you often feel no thirst at all. Dehydration thickens the blood and worsens the sense of hypoxia and headache — so regular drinking is part of acclimatisation, not an afterthought.",

    "q.m01#9.p" to "[Multiple choice] Which of these injuries are caused directly by the high-altitude environment?",
    "q.m01#9.o0" to "Sunburn",
    "q.m01#9.o1" to "Snow blindness",
    "q.m01#9.o2" to "Dehydration",
    "q.m01#9.o3" to "Cracked lips",
    "q.m01#9.o4" to "A sprained ankle",
    "q.m01#9.e" to "The first four are environmental injuries, and they share one trait: they are almost entirely preventable. Unlike avalanches they are not hard to predict — they depend purely on kit and habits, so seeing them in a team usually means something went wrong in preparation.",

    "q.m01#10.p" to "Which statement about the composition of air at altitude is correct?",
    "q.m01#10.o0" to "The proportion of oxygen falls as you go higher",
    "q.m01#10.o1" to "The proportion stays about the same; lower pressure reduces the partial pressure",
    "q.m01#10.o2" to "The proportion of nitrogen rises with altitude",
    "q.m01#10.o3" to "Oxygen is squeezed out by other gases at altitude",
    "q.m01#10.e" to "Within the troposphere the mix is essentially constant (about 21% oxygen, 78% nitrogen). What changes with altitude is pressure — how many molecules are in that same lungful. Get that distinction clear and a lot of equipment and physiology questions become easy.",

    "q.m01#11.p" to "Why are 5,000 m peaks still snow-covered in summer?",
    "q.m01#11.o0" to "Because high places are farther from the sun",
    "q.m01#11.o1" to "Because high-altitude air is much colder than lowlands at the same latitude, so precipitation falls as snow",
    "q.m01#11.o2" to "Because strong summit winds stop it melting",
    "q.m01#11.o3" to "Because compacted snow turns to ice and never melts again",
    "q.m01#11.e" to "The 6.5 °C per 1,000 m rule keeps summer temperatures at 5,000 m below freezing. It also explains why the same mountain is harder in one season than another — the snowline moves, and so does the route.",

    "q.m01#12.p" to "From a 3,000 m base camp to a 5,000 m camp, using the average lapse rate, roughly how many degrees colder is it?",
    "q.m01#12.a0" to "13",
    "q.m01#12.e" to "13 °C. The arithmetic: 2,000 m of gain at 6.5 °C per 1,000 m is 2 × 6.5 = 13 °C. That estimate is very practical before a trip — it decides how thick your insulation and sleeping bag must be.",

    // ---------- m02 ----------
    "q.m02#0.p" to "What kind of fitness matters most for high-altitude climbing?",
    "q.m02#0.o0" to "Explosive power and short sprints",
    "q.m02#0.o1" to "Aerobic endurance sustained over hours",
    "q.m02#0.o2" to "Maximum grip strength",
    "q.m02#0.o3" to "Flexibility",
    "q.m02#0.e" to "High-altitude climbing is long, low-intensity work: six to ten hours a day, never steep but relentless. Hypoxia sharply limits anaerobic capacity, so what carries you is an aerobic base and the ability to hold a steady pace.",

    "q.m02#1.p" to "How should training be arranged before departure?",
    "q.m02#1.o0" to "Cram in a big block the week before",
    "q.m02#1.o1" to "Taper over the last two to three weeks and go up rested",
    "q.m02#1.o2" to "Train at maximum intensity right up to the day before",
    "q.m02#1.o3" to "Do not train at all; rely on acclimatising there",
    "q.m02#1.e" to "Training gains are made during recovery. Arriving tired undermines both performance and acclimatisation — and acclimatising itself costs energy. The taper is what converts training into form.",

    "q.m02#2.p" to "At altitude, what should the diet be based on?",
    "q.m02#2.o0" to "High-fat food",
    "q.m02#2.o1" to "Carbohydrate",
    "q.m02#2.o2" to "High-protein food",
    "q.m02#2.o3" to "Liquids only",
    "q.m02#2.e" to "Carbohydrate is metabolised more efficiently and uses less oxygen under hypoxic conditions, and the body instinctively prefers it up high. This runs against the intuition that altitude demands calorie-dense fat — the constraint is oxygen efficiency.",

    "q.m02#3.p" to "What is a practical indicator of adequate hydration?",
    "q.m02#3.o0" to "How thirsty you feel",
    "q.m02#3.o1" to "Urine staying pale",
    "q.m02#3.o2" to "Drinking a fixed 1 litre a day",
    "q.m02#3.o3" to "Changes in body weight",
    "q.m02#3.e" to "Thirst is unreliable at altitude — cold and hypoxia both blunt it. Urine colour and smell are a more direct daily gauge: pale means roughly enough, darker and stronger means drink more.",

    "q.m02#4.p" to "Why avoid alcohol at altitude?",
    "q.m02#4.o0" to "Because it makes you put on weight",
    "q.m02#4.o1" to "Because it suppresses respiratory drive and worsens nocturnal hypoxia",
    "q.m02#4.o2" to "Because it speeds up UV damage",
    "q.m02#4.o3" to "Because there is no fridge",
    "q.m02#4.e" to "Alcohol and sedatives both suppress the respiratory centre. Nights at altitude already tend towards periodic breathing, and adding respiratory depression drops saturation markedly — one of the key mechanisms by which altitude illness worsens overnight.",

    "q.m02#5.p" to "[Multiple choice] Which are the right ways to take on energy while moving at altitude?",
    "q.m02#5.o0" to "Small amounts often, before you are starving",
    "q.m02#5.o1" to "Prefer easy-to-digest food with moderate water content",
    "q.m02#5.o2" to "Base it on carbohydrate",
    "q.m02#5.o3" to "Eat one large meal to cut down on eating occasions",
    "q.m02#5.e" to "Small and often eases digestion and keeps blood sugar steady. A large meal in hypoxia tends to cause bloating and nausea — and since appetite loss is itself a common symptom, forcing down a big meal backfires.",

    "q.m02#6.p" to "Appetite drops at altitude. What is the right response?",
    "q.m02#6.o0" to "Stop eating and wait for hunger",
    "q.m02#6.o1" to "Eat deliberately, choosing high-carbohydrate, easy-to-digest food",
    "q.m02#6.o2" to "Drink a lot of coffee instead of eating",
    "q.m02#6.o3" to "Take electrolytes only",
    "q.m02#6.e" to "Loss of appetite is part of altitude illness, and under-eating weakens acclimatisation — a vicious circle. Eat deliberately, in small amounts, often: this is not about whether you feel hungry, it is a necessary measure.",

    "q.m02#7.p" to "Which statement about fitness and altitude is correct?",
    "q.m02#7.o0" to "If you are fit you will not get altitude illness",
    "q.m02#7.o1" to "Fitness improves performance but cannot replace acclimatisation",
    "q.m02#7.o2" to "Unfit people should not go to altitude",
    "q.m02#7.o3" to "The fitter you are, the less acclimatisation you need",
    "q.m02#7.e" to "Fitness and acclimatisation are two separate lines. A fit person may feel more comfortable at the same altitude, but physiology still needs time measured in days — treating 'I am fit' as 'I will not get sick' is the logic behind many accidents.",

    "q.m02#8.p" to "[Order] Put a sensible pre-climb preparation sequence in time order.",
    "q.m02#8.o0" to "Base fitness training (two to three months ahead)",
    "q.m02#8.o1" to "Taper and protect recovery (two to three weeks out)",
    "q.m02#8.o2" to "Check equipment, itinerary and insurance (one week out)",
    "q.m02#8.o3" to "Acclimatise on schedule (during the trip)",
    "q.m02#8.e" to "The order is the method: train early, leave room to recover, prepare in detail, acclimatise slowly. The steps most often disrupted are the last two — plenty of people check gear thoroughly, then chase the schedule on the mountain and cut acclimatisation short.",

    "q.m02#9.p" to "What problem can over-drinking (a large volume in a short time) cause at altitude?",
    "q.m02#9.o0" to "None at all",
    "q.m02#9.o1" to "It dilutes blood electrolytes and in severe cases causes hyponatraemia",
    "q.m02#9.o2" to "It effectively prevents pulmonary oedema",
    "q.m02#9.o3" to "It can replace eating",
    "q.m02#9.e" to "'Drink enough' is not 'drink desperately'. A large volume in a short time without electrolytes can dilute blood sodium and cause headache, nausea and altered consciousness — symptoms that closely mimic altitude illness and are easily misread. Steady, adequate intake is the answer.",

    // ---------- m03 ----------
    "q.m03#0.p" to "What is the core meaning of the low-impact principle?",
    "q.m03#0.o0" to "Carry lighter kit to reduce impact on your body",
    "q.m03#0.o1" to "Minimise the impact of human activity on the mountain environment",
    "q.m03#0.o2" to "Lower the difficulty of the climb to stay safe",
    "q.m03#0.o3" to "Reduce the number of people in the team",
    "q.m03#0.e" to "The low-impact principle is the environmental ethic promoted in outdoor mountaineering. It is not about how lightly you travel but about how much the mountain is changed by your presence — rubbish, trampling, fire and disturbance to wildlife all count.",

    "q.m03#1.p" to "When leaving camp, what is the right approach to rubbish?",
    "q.m03#1.o0" to "Food scraps can be buried on the spot",
    "q.m03#1.o1" to "Carry it all out, including toilet paper and hygiene items",
    "q.m03#1.o2" to "Take only plastic",
    "q.m03#1.o3" to "Burn it in a pit",
    "q.m03#1.e" to "The manual is explicit: bag everything you produce and carry it out, check the camp and activity area, and carry out hygiene items such as toilet paper. Burying and burning both leave traces, and in cold high-altitude conditions waste breaks down extremely slowly.",

    "q.m03#2.p" to "What principle guides the siting of a toilet in the wild?",
    "q.m03#2.o0" to "The more hidden the better — privacy first",
    "q.m03#2.o1" to "Away from water sources, camps and trails",
    "q.m03#2.o2" to "Wherever the snow is flattest",
    "q.m03#2.o3" to "Near a stream so it washes away",
    "q.m03#2.e" to "The aim is to avoid contaminating water and to avoid the next party walking into it. In practice that means a set distance from water and trails, a shallow hole, and packing out used paper — and above the snowline, packing everything out, because it barely decomposes.",

    "q.m03#3.p" to "Why seal food and rubbish away?",
    "q.m03#3.o0" to "To stop it getting damp",
    "q.m03#3.o1" to "To stop animals raiding it and becoming habituated",
    "q.m03#3.o2" to "To save pack space",
    "q.m03#3.o3" to "To make it easier to weigh",
    "q.m03#3.e" to "Animals that raid food are usually taught to do so by teams: once they associate camp with food, the risk on that route rises permanently. Sealing it protects your food, the animals and everyone who comes after you.",

    "q.m03#4.p" to "What does the sensitive period for wildlife mainly refer to?",
    "q.m03#4.o0" to "Daytime feeding hours",
    "q.m03#4.o1" to "Mating and suckling seasons",
    "q.m03#4.o2" to "Migration season",
    "q.m03#4.o3" to "Winter dormancy",
    "q.m03#4.e" to "Animals are especially sensitive to disturbance while mating and rearing young, and a mother defending young can be aggressive. So besides avoiding their range, avoid fixed watering times and places — it protects them and it protects you.",

    "q.m03#5.p" to "Why stay on established trails?",
    "q.m03#5.o0" to "Because the rules require it",
    "q.m03#5.o1" to "Because trampling creates lasting new paths and triggers erosion",
    "q.m03#5.o2" to "Because trails are easier to walk",
    "q.m03#5.o3" to "Because guides mark them",
    "q.m03#5.e" to "High-altitude vegetation grows extremely slowly; a single bootprint can persist for years. Parallel 'shortcuts' cut through vegetation and concentrate water flow, eventually carving gullies — which is how a route starts to degrade.",

    "q.m03#6.p" to "[Multiple choice] Which of these must be carried out of the mountains?",
    "q.m03#6.o0" to "Food packaging",
    "q.m03#6.o1" to "Fruit peel and food scraps",
    "q.m03#6.o2" to "Used toilet paper",
    "q.m03#6.o3" to "Cigarette ends",
    "q.m03#6.o4" to "Tape and cord can be burned on site",
    "q.m03#6.e" to "The first four all go out with you. The most common misunderstanding is fruit peel and scraps — they look biodegradable, but in cold dry alpine conditions they break down very slowly and they attract animals and change their behaviour.",

    "q.m03#7.p" to "What is the right attitude to collecting natural objects (stones, plants, fossils) as souvenirs?",
    "q.m03#7.o0" to "Small items are fine to take",
    "q.m03#7.o1" to "Take nothing natural — take photographs instead",
    "q.m03#7.o2" to "Fine as long as you do not damage the environment",
    "q.m03#7.o3" to "Collecting specimens helps science",
    "q.m03#7.e" to "'Take only photographs, leave only footprints' is the classic formulation. Natural objects are part of the local ecology and landscape, and once every team takes a little, the cumulative effect is substantial.",

    "q.m03#8.p" to "How does mountaineering mainly affect mountain environments?",
    "q.m03#8.o0" to "Only through rubbish",
    "q.m03#8.o1" to "Vegetation damage, shrinking wildlife range, rubbish, and the cultural impact of outside visitors on local communities",
    "q.m03#8.o2" to "Mainly noise",
    "q.m03#8.o3" to "The impact is negligible",
    "q.m03#8.e" to "The manual splits impact into ecological and social: vegetation damage, wildlife displacement and rubbish on one side, cultural pressure on local ways of life on the other. Understanding this is why etiquette is part of mountaineering training.",

    "q.m03#9.p" to "[Order] Put the low-impact routine for leaving camp in the correct order.",
    "q.m03#9.o0" to "Pack up personal and group equipment",
    "q.m03#9.o1" to "Sort and bag all rubbish",
    "q.m03#9.o2" to "Deal with human waste (bury or pack out)",
    "q.m03#9.o3" to "Walk the camp and activity area and confirm nothing is left",
    "q.m03#9.e" to "The last step — the walk-round — is the most skipped and the most important: people instinctively take 'their own things', which is exactly how tent pegs, rope ends and dropped wrappers get left behind. Looking back costs almost nothing.",

    // ---------- m04 ----------
    "q.m04#0.p" to "What is the most reliable sign that the weather is turning?",
    "q.m04#0.o0" to "Whether it is sunny right now",
    "q.m04#0.o1" to "Trends in pressure, cloud and wind",
    "q.m04#0.o2" to "The forecast from before departure",
    "q.m04#0.o3" to "How your partners feel",
    "q.m04#0.e" to "The present is a snapshot; the trend is the direction. Pressure falling steadily, cloud thickening and lowering, wind strengthening — when all three appear together, the weather is turning. That is the practical value of carrying a barometer, whether in a watch or separately.",

    "q.m04#1.p" to "What is typical of cumulonimbus, and what does it mean?",
    "q.m04#1.o0" to "Thin and even — settled weather",
    "q.m04#1.o1" to "Vertical development with an anvil top — thunderstorms and heavy precipitation",
    "q.m04#1.o2" to "Spread in layers — only drizzle",
    "q.m04#1.o3" to "Wispy threads — good weather",
    "q.m04#1.e" to "The vertical growth shows strong convection, and the anvil means it has reached maturity. Meeting one at altitude means lightning, hail and heavy precipitation are all possible — leave exposed ridges and high ground immediately.",

    "q.m04#2.p" to "Which map scales are commonly used in mountaineering?",
    "q.m04#2.o0" to "1:1,000 and 1:5,000",
    "q.m04#2.o1" to "1:50,000 and 1:10,000",
    "q.m04#2.o2" to "1:250,000 and 1:500,000",
    "q.m04#2.o3" to "Any scale will do",
    "q.m04#2.e" to "1:50,000 and 1:10,000 are the usual pair: the first covers a large area and suits itinerary planning, the second carries detail and suits technical terrain. 1:200,000 is used occasionally, and 1:10,000 less often — the sheet covers so little ground that you walk off it quickly.",

    "q.m04#3.p" to "Closely spaced contours on a topographic map mean what?",
    "q.m04#3.o0" to "A gentle slope",
    "q.m04#3.o1" to "A steep slope",
    "q.m04#3.o2" to "A valley",
    "q.m04#3.o3" to "A glacier",
    "q.m04#3.e" to "The closer the contours, the more height is gained over the same horizontal distance — in other words, the steeper it is. This is a useful reading skill in planning: you can mark the steep sections, the shelves and possible tent sites before you leave.",

    "q.m04#4.p" to "What does a closed contour line on a topographic map indicate?",
    "q.m04#4.o0" to "A lake",
    "q.m04#4.o1" to "An independent peak",
    "q.m04#4.o2" to "A glacier",
    "q.m04#4.o3" to "A cliff",
    "q.m04#4.e" to "A closed contour means the massif falls away on every side — the very definition of an independent peak. Several concentric closed loops mean the mountain rises step by step, with the innermost loop marking the summit area.",

    "q.m04#5.p" to "[Multiple choice] What should you watch when using a compass?",
    "q.m04#5.o0" to "Keep it as level as possible",
    "q.m04#5.o1" to "Stay away from magnetic objects",
    "q.m04#5.o2" to "Do not mistake the S end of the needle for north",
    "q.m04#5.o3" to "Correct for the local magnetic declination",
    "q.m04#5.o4" to "Hold it close to the metal buckles on your pack to keep it steady",
    "q.m04#5.e" to "All four are listed explicitly in the manual. The S-end error alone produces a 180° direction error — in complex terrain that can send you the opposite way without you noticing.",

    "q.m04#6.p" to "What is magnetic declination?",
    "q.m04#6.o0" to "A manufacturing error in the compass",
    "q.m04#6.o1" to "The offset between magnetic north and true north, which must be corrected",
    "q.m04#6.o2" to "An angle change caused by altitude",
    "q.m04#6.o3" to "Distortion caused by map projection",
    "q.m04#6.e" to "The needle points to magnetic north while maps are referenced to true north, and the two differ. Declination varies by region, so it must be corrected when working map and compass together — otherwise the whole route shifts.",

    "q.m04#7.p" to "What do the neat square grid lines on a topographic map represent?",
    "q.m04#7.o0" to "Lines of latitude and longitude",
    "q.m04#7.o1" to "A UTM (Universal Transverse Mercator) grid",
    "q.m04#7.o2" to "Contours",
    "q.m04#7.o3" to "Administrative boundaries",
    "q.m04#7.e" to "The grid is not latitude and longitude but UTM. That matters because the earth is an ellipsoid, so lat/long cells are not equal in size at different latitudes, while UTM squares are — which makes measuring distance and coordinates straightforward.",

    "q.m04#8.p" to "Why not rely on GPS alone?",
    "q.m04#8.o0" to "Because GPS is not accurate enough",
    "q.m04#8.o1" to "Because the device can lose power, get wet, break or lose signal",
    "q.m04#8.o2" to "Because GPS only works in cities",
    "q.m04#8.o3" to "Because GPS requires a subscription",
    "q.m04#8.e" to "GPS is an excellent aid, but it presupposes a working device. Batteries fade fast in high-altitude cold, and water and drops are common. Map and compass need no power — which is why they remain compulsory in mountaineering training.",

    "q.m04#9.p" to "When visibility collapses (fog, whiteout), what should you do first?",
    "q.m04#9.o0" to "Speed up and get through it",
    "q.m04#9.o1" to "Confirm your position and heading immediately, and wait in place if necessary",
    "q.m04#9.o2" to "Keep walking straight on the original plan",
    "q.m04#9.o3" to "Split up and look for the route",
    "q.m04#9.e" to "The danger of a whiteout is losing every visual reference, and people instinctively walk in the wrong direction. Fix your position, record the heading and wait if needed — far safer than pushing on, and splitting up is the worst option of all.",

    // ---------- m05 ----------
    "q.m05#0.p" to "What is the core difference between a trekking peak and a technical peak?",
    "q.m05#0.o0" to "Altitude",
    "q.m05#0.o1" to "Whether technical equipment and technical movement are required",
    "q.m05#0.o2" to "Which country it is in",
    "q.m05#0.o3" to "Whether a permit is needed",
    "q.m05#0.e" to "The dividing line is technical demand, not height. Kilimanjaro at 5,895 m needs no technical gear, while Haba Snow Mountain at 5,396 m requires crampons and an axe above the snowline. Altitude is only one dimension of difficulty.",

    "q.m05#1.p" to "What is the highest point of Kilimanjaro called?",
    "q.m05#1.o0" to "Uhuru Peak",
    "q.m05#1.o1" to "Kibo",
    "q.m05#1.o2" to "Mawenzi",
    "q.m05#1.o3" to "Shira",
    "q.m05#1.e" to "The summit is Uhuru Peak at 5,895 m. Kilimanjaro is a dormant volcano built from three cones — Kibo, Mawenzi and Shira — and Uhuru is the highest point on Kibo.",

    "q.m05#2.p" to "What makes Kilimanjaro unique?",
    "q.m05#2.o0" to "It is the least-climbed 5,000 m peak in the world",
    "q.m05#2.o1" to "It sits near the equator yet carries glaciers, crossing climate zones from rainforest to alpine desert",
    "q.m05#2.o2" to "It demands highly technical equipment",
    "q.m05#2.o3" to "It can only be climbed one month a year",
    "q.m05#2.e" to "Equator plus glaciers makes Kilimanjaro a vertical climate corridor: rainforest to ice in a single trip. That also creates a practical problem — a big vertical span with fast altitude gain, so acclimatisation becomes the main challenge.",

    "q.m05#3.p" to "Aotaina belongs to which group of peaks?",
    "q.m05#3.o0" to "Siguniang",
    "q.m05#3.o1" to "The San'ao Snow Mountains",
    "q.m05#3.o2" to "Gongga",
    "q.m05#3.o3" to "Meili Snow Mountain",
    "q.m05#3.e" to "The San'ao group in Heishui, Sichuan, consists of Aotaiji (father of the mountains), Aotaimei (mother) and Aotaina (son). Aotaina is the easiest of the three and is often chosen as a first snow peak.",

    "q.m05#4.p" to "Which description of Aotaina's altitude is accurate?",
    "q.m05#4.o0" to "All sources agree on 4,800 m",
    "q.m05#4.o1" to "Official altitude 5,211 m, but measured around 4,800 m — sources differ",
    "q.m05#4.o2" to "Official 4,800 m, measured 5,211 m",
    "q.m05#4.o3" to "The altitude has never been disputed",
    "q.m05#4.e" to "Such discrepancies are common in peak data: official figures, measured values and different survey standards all vary. The practical lesson is to cite the source whenever you quote peak data, rather than treating one number as absolute truth.",

    "q.m05#5.p" to "What are the altitudes of Siguniang's Da Feng and Er Feng?",
    "q.m05#5.o0" to "5,025 m and 5,276 m",
    "q.m05#5.o1" to "5,276 m and 5,025 m",
    "q.m05#5.o2" to "5,025 m and 5,355 m",
    "q.m05#5.o3" to "4,850 m and 5,276 m",
    "q.m05#5.e" to "Da Feng is 5,025 m and Er Feng 5,276 m. They are often paired as an entry progression: Da Feng first for altitude experience, then Er Feng, whose final section needs simple technical assistance — a natural step towards technical climbing.",

    "q.m05#6.p" to "[Multiple choice] When choosing a first snow peak, which factors are most worth comparing?",
    "q.m05#6.o0" to "How established the route is and its summit rate",
    "q.m05#6.o1" to "Whether guiding and rescue support are reliable",
    "q.m05#6.o2" to "Whether the altitude gain is paced sensibly",
    "q.m05#6.o3" to "Your current fitness and the time you can commit",
    "q.m05#6.o4" to "How popular the peak is on social media",
    "q.m05#6.e" to "The first four together answer 'is this mountain right for me now'. Looking only at the altitude number misleads: a 5,000 m peak with sensible pacing and good support can be safer than a 5,500 m peak that forces three rushed days.",

    "q.m05#7.p" to "What most often causes failure on an introductory peak?",
    "q.m05#7.o0" to "Technical difficulty",
    "q.m05#7.o1" to "Altitude illness and weather, not technical difficulty",
    "q.m05#7.o2" to "Inadequate equipment",
    "q.m05#7.o3" to "Too small a team",
    "q.m05#7.e" to "This is the most underestimated point: on introductory peaks, failure is almost always 'we ran out of legs' or 'the weather did not wait', not 'we could not pass the crux'. So the real homework at this level is acclimatisation, pacing and fitness — not technical moves.",

    "q.m05#8.p" to "Why is summit rate a useful figure when choosing a peak?",
    "q.m05#8.o0" to "Because it reflects how scenic the peak is",
    "q.m05#8.o1" to "Because it integrates route difficulty, pacing and the real level of support",
    "q.m05#8.o2" to "Because it determines the cost",
    "q.m05#8.o3" to "Because it has nothing to do with safety",
    "q.m05#8.e" to "Summit rate is the product of many things: how hard the route is, whether the altitude gain is sensible, how wide the weather windows are, how reliable logistics are. It tells you more about what you will actually face than altitude alone.",

    "q.m05#9.p" to "What is the right attitude to an introductory snow peak?",
    "q.m05#9.o0" to "Introductory means no risk",
    "q.m05#9.o1" to "Introductory only means lower technical demand; altitude and weather risks remain real",
    "q.m05#9.o2" to "Introductory peaks need no guide",
    "q.m05#9.o3" to "Introductory peaks need no fitness preparation",
    "q.m05#9.e" to "'Introductory' describes the technical threshold, not the total risk. Altitude itself, sudden weather and exhaustion can kill at any elevation. Treating introductory as 'easy' is where poor preparation begins.",

    // ---------- m06 ----------
    "q.m06#0.p" to "What are the three basic systems of technical climbing?",
    "q.m06#0.o0" to "Gear, fitness, weather",
    "q.m06#0.o1" to "Arrest, protection, movement",
    "q.m06#0.o2" to "Ascent, descent, rest",
    "q.m06#0.o3" to "Crampons, axe, rope",
    "q.m06#0.e" to "Arrest answers 'what do I do after losing my footing', protection answers 'who catches me if I fall', and movement answers 'how do I move over dangerous ground'. Together they close the loop — remove any one and technical climbing does not work.",

    "q.m06#1.p" to "What is the fundamental purpose of learning technical climbing?",
    "q.m06#1.o0" to "To climb harder routes",
    "q.m06#1.o1" to "To turn an uncontrolled slide into a managed risk",
    "q.m06#1.o2" to "To earn a certificate",
    "q.m06#1.o3" to "To move faster",
    "q.m06#1.e" to "Technique does not lower the mountain; it changes what happens after a mistake. With an arrest, a slip is no longer an irreversible disaster; with protection, one error does not automatically mean a fall. That is the real value.",

    "q.m06#2.p" to "What is the most effective way to master a technical movement?",
    "q.m06#2.o0" to "Watch instructional videos repeatedly",
    "q.m06#2.o1" to "Practise repeatedly on protected ground until it is a reflex",
    "q.m06#2.o2" to "Read the manual and memorise the points",
    "q.m06#2.o3" to "Learn it in one go on a real steep slope",
    "q.m06#2.e" to "Technical actions have to be performed under pressure, and pressure drops you back to the level you actually trained at. Gentle slope, soft snow, clean run-out and an instructor on belay — when all four are present, that is where a skill is really learned.",

    "q.m06#3.p" to "Why can you not learn self-arrest from video?",
    "q.m06#3.o0" to "Because the video quality is poor",
    "q.m06#3.o1" to "Because it is a reflex that must be built through repeated field practice",
    "q.m06#3.o2" to "Because the technique shown is wrong",
    "q.m06#3.o3" to "Because self-arrest is actually simple",
    "q.m06#3.e" to "After a slip you have one or two seconds, with no room to think. Muscle memory is bought with repetitions — which is why every proper course insists you drill it until you can do it without thinking.",

    "q.m06#4.p" to "What are the three starter items of technical gear?",
    "q.m06#4.o0" to "Helmet, gloves, goggles",
    "q.m06#4.o1" to "Crampons matched to your boots, an ice axe, and a harness",
    "q.m06#4.o2" to "Tent, sleeping bag, mat",
    "q.m06#4.o3" to "GPS, radio, headlamp",
    "q.m06#4.e" to "Crampons give grip, the axe gives arrest and support, the harness connects you to the protection system. What they share is that they only create safety when matched and used as a system with a partner — no single item protects anyone on its own.",

    "q.m06#5.p" to "Once you have the technical skills, what becomes the most important ability?",
    "q.m06#5.o0" to "Climbing speed",
    "q.m06#5.o1" to "Judging when you do not need the technical gear at all",
    "q.m06#5.o2" to "Maintaining equipment",
    "q.m06#5.o3" to "Further fitness gains",
    "q.m06#5.e" to "This is the most counter-intuitive point in technical climbing: skill lets you enter harder terrain, while real experts use it to buy the option of not going there. Judgement always outranks execution.",

    "q.m06#6.p" to "[Multiple choice] Which of these count as technical climbing?",
    "q.m06#6.o0" to "Moving on an ice slope and arresting",
    "q.m06#6.o1" to "Crossing a glacier roped up",
    "q.m06#6.o2" to "Building a belay anchor",
    "q.m06#6.o3" to "Rappelling",
    "q.m06#6.o4" to "Hiking a well-established trail",
    "q.m06#6.e" to "The first four are technical: each needs equipment, systems and specific training. Simply walking on snow or following an established trail is not — the distinction is whether those systems are required.",

    "q.m06#7.p" to "Why can technical ability never replace judgement?",
    "q.m06#7.o0" to "Because technical ability cannot be trained",
    "q.m06#7.o1" to "Because bad judgement puts you in terrain you should never have entered, where technique cannot save you",
    "q.m06#7.o2" to "Because judgement is easier to learn",
    "q.m06#7.o3" to "Because technique only applies to rock",
    "q.m06#7.e" to "Technique is what you use once you are already in danger; judgement decides whether you enter danger at all. Accident reviews rarely find 'the move was wrong' — far more often the finding is 'they should not have been there'.",

    "q.m06#8.p" to "[Order] Put the learning sequence for technical climbing in a sensible order.",
    "q.m06#8.o0" to "Understand the gear: how crampons, axe and harness work",
    "q.m06#8.o1" to "Practise the basic actions repeatedly on safe ground (self-arrest, for instance)",
    "q.m06#8.o2" to "Learn rope systems: knots, roping up, anchors",
    "q.m06#8.o3" to "Apply it all on real but controlled routes",
    "q.m06#8.e" to "The logic is: protect yourself first, then connect to others, then enter real terrain. Skipping a step leaves a gap in ability — roping up onto a glacier with unpolished arrest skills, for instance, multiplies risk across the whole team.",

    "q.m06#9.p" to "What has this unit accomplished?",
    "q.m06#9.o0" to "Completed all high-altitude training",
    "q.m06#9.o1" to "Built the foundation in environment, science and equipment, ready to start technical movement",
    "q.m06#9.o2" to "Completed 8,000 m preparation",
    "q.m06#9.o3" to "Earned a rescue certification",
    "q.m06#9.e" to "The 5,000 m introductory unit is about laying the base: environmental science, equipment, clothing, fitness, low-impact practice, weather and navigation, and finally technical climbing. The next unit starts properly on crampons, the axe, arrest and rope work.",

    // ---------- m07 ----------
    "q.m07#0.p" to "What is the core idea behind anchor design?",
    "q.m07#0.o0" to "Use as little gear as possible",
    "q.m07#0.o1" to "No single protection point failing should collapse the system",
    "q.m07#0.o2" to "Build the anchor as high as possible",
    "q.m07#0.o3" to "Use natural protection only",
    "q.m07#0.e" to "Rock and snow anchors can never be absolutely certain, so the system is designed to tolerate error rather than to be absolutely strong. Everything else — redundancy, equalising, no extension — is just that idea spelled out.",

    "q.m07#1.p" to "With two protection points at 90° to each other, roughly what share of the load does each carry?",
    "q.m07#1.o0" to "About 50%",
    "q.m07#1.o1" to "About 58%",
    "q.m07#1.o2" to "About 71%",
    "q.m07#1.o3" to "About 100%",
    "q.m07#1.e" to "These are the key numbers from the manual's table: at 0° each point carries about 50%, at 60° about 58%, at 90° about 71%. The wider the angle, the more force each point feels from the same person — which directly drives how you choose and arrange the points.",

    "q.m07#2.p" to "From a load standpoint, how should the angle between protection points be handled?",
    "q.m07#2.o0" to "As small as possible, so the load directions are nearly parallel",
    "q.m07#2.o1" to "As large as possible, to spread load in different directions",
    "q.m07#2.o2" to "It must be 90°",
    "q.m07#2.o3" to "The angle does not affect the load",
    "q.m07#2.e" to "The smaller the angle, the closer the split is to 50/50; widen it and the load on each point rises. The common rule 'keep the sling angle within 60°' comes directly from those figures.",

    "q.m07#3.p" to "[Multiple choice] Which dimensions should you consider when assessing an anchor?",
    "q.m07#3.o0" to "Solid: each point is strong enough",
    "q.m07#3.o1" to "Redundant: several independent points",
    "q.m07#3.o2" to "Equalised: the load is shared sensibly",
    "q.m07#3.o3" to "No extension: a failure does not create a shock-loading extension",
    "q.m07#3.o4" to "Symmetry: a tidy, visually balanced layout",
    "q.m07#3.e" to "These four are the basic framework. No Extension is the one most often missed: leave slack between points and a failure shocks the remaining ones. Shock loads are far larger than static loads, which many people do not realise.",

    "q.m07#4.p" to "[Matching] Match each protection type to its medium and method.",
    "q.m07#4.l0" to "Natural protection",
    "q.m07#4.l1" to "Snow protection",
    "q.m07#4.l2" to "Ice protection",
    "q.m07#4.r0" to "Rock pillars, large trees, big blocks — confirm they are intact and stable",
    "q.m07#4.r1" to "Pickets, deadmen, T-slots — reliability depends heavily on snow quality and burial",
    "q.m07#4.r2" to "Ice screws — confirm the ice is solid, with no voids or honeycombing",
    "q.m07#4.e" to "Three media, three completely different sets of criteria. One of the commonest causes of accidents is judging snow or ice with rock instincts — 'it looks solid' is almost meaningless in a snowpack.",

    "q.m07#5.p" to "Which of these is false redundancy?",
    "q.m07#5.o0" to "Using two pieces of different strengths",
    "q.m07#5.o1" to "Two protection points that actually depend on the same crack or the same block",
    "q.m07#5.o2" to "Connecting the points with slings",
    "q.m07#5.o3" to "Placing three protection points",
    "q.m07#5.e" to "Redundancy requires independent failure. If two points share one crack, the crack opening takes both out at once — it looks like two points but works as one. False redundancy is common and lethal.",

    "q.m07#6.p" to "Why pre-tension the system to achieve no extension?",
    "q.m07#6.o0" to "For a tidy appearance",
    "q.m07#6.o1" to "To stop a failure shock-loading the remaining points",
    "q.m07#6.o2" to "To save sling length",
    "q.m07#6.o3" to "To make it quicker to dismantle",
    "q.m07#6.e" to "A shock load is far greater than a static one — the same person suddenly loading a point generates much more force than hanging still. A slack anchor looks 'more flexible' but actually amplifies one failure into a shock across the whole system.",

    "q.m07#7.p" to "[Order] Put the steps of building an anchor in a sensible order.",
    "q.m07#7.o0" to "Look around and pick usable, mutually independent point positions",
    "q.m07#7.o1" to "Place each point and confirm it is strong on its own",
    "q.m07#7.o2" to "Connect the points with sling or rope, control the angle and pre-tension",
    "q.m07#7.o3" to "Check the whole system for false redundancy and extension",
    "q.m07#7.e" to "The order is: choose the positions, build the single points, connect the system, then review it. The review is not a formality — while building you concentrate on each placement, and it is easy to miss the overall relationship, such as two points sharing one feature.",

    "q.m07#8.p" to "When using natural protection, what most needs checking?",
    "q.m07#8.o0" to "Whether it is big enough",
    "q.m07#8.o1" to "Whether it is intact — not loose, weathered or detached from the main mass",
    "q.m07#8.o2" to "Whether it looks good",
    "q.m07#8.o3" to "Whether it is easy to sling",
    "q.m07#8.e" to "The danger with natural protection is usually that it looks big but is already loose. What matters is whether it is genuinely part of the main mass, and whether there are cracks or signs of weathering. Big, thick and obvious do not mean solid.",

    "q.m07#9.p" to "Why build an anchor as quickly as you reasonably can?",
    "q.m07#9.o0" to "To save energy",
    "q.m07#9.o1" to "Because the time spent building it is time spent exposed to risk",
    "q.m07#9.o2" to "Because partners will hurry you",
    "q.m07#9.o3" to "Because gear gets lost",
    "q.m07#9.e" to "While building an anchor you are often unprotected or poorly protected, so that exposure should be short. This is why the assessment looks not only at solid, redundant and equalised, but also at efficiency and timeliness.",

    "q.m07#10.p" to "What does the reliability of a snow anchor mainly depend on?",
    "q.m07#10.o0" to "The brand of the gear",
    "q.m07#10.o1" to "Snow quality and how well it is buried",
    "q.m07#10.o2" to "The altitude",
    "q.m07#10.o3" to "The colour of the rope",
    "q.m07#10.e" to "The same picket or deadman holds vastly different loads in deep snow, wet snow or at the edge of a snow bridge. Snow anchors require reading the snowpack on the spot, which is also what makes snow protection one of the most demanding skills.",

    "q.m07#11.p" to "If an anchor has only a single protection point, what is the biggest problem?",
    "q.m07#11.o0" to "The load is too high",
    "q.m07#11.o1" to "There is no margin at all — if that point fails, the system fails",
    "q.m07#11.o2" to "It is awkward to operate",
    "q.m07#11.o3" to "It looks ugly",
    "q.m07#11.e" to "A single-point anchor hands your life to one uncertain factor. Sometimes it really is the only option — one good ice screw, for example — and then the approach is to make that point as good as it can be, and to minimise how long the system depends on it.",

    // ---------- m08 ----------
    "q.m08#0.p" to "What is the altitude of Gangshika main peak?",
    "q.m08#0.o0" to "5,005 m",
    "q.m08#0.o1" to "5,150 m",
    "q.m08#0.o2" to "5,254.5 m",
    "q.m08#0.o3" to "5,396 m",
    "q.m08#0.e" to "The main peak is 5,254.5 m. Note the hierarchy: third peak 5,005 m < shoulder peak 5,150 m < main peak 5,254.5 m — three heights, three levels of difficulty, which is why Gangshika is often used as a step-by-step objective.",

    "q.m08#1.p" to "What are the altitude and character of Gangshika's third peak?",
    "q.m08#1.o0" to "5,005 m, entry-level technical, about 95% summit rate for beginners",
    "q.m08#1.o1" to "5,254 m, highly technical",
    "q.m08#1.o2" to "5,150 m, pure trekking",
    "q.m08#1.o3" to "5,396 m, glacier route",
    "q.m08#1.e" to "The third peak is 5,005 m and entry-level technical. A beginner summit rate of about 95% tells you the route is manageable and logistics are mature — well suited to putting on technical gear for the first time.",

    "q.m08#2.p" to "What is Gangshika's geographical significance?",
    "q.m08#2.o0" to "The highest peak of the Kunlun range",
    "q.m08#2.o1" to "The highest peak of the eastern Qilian range",
    "q.m08#2.o2" to "The highest peak of the Tibetan plateau",
    "q.m08#2.o3" to "The highest peak of the Hengduan range",
    "q.m08#2.e" to "Gangshika is the highest peak of the eastern Qilian range, in Menyuan county, Haibei prefecture, Qinghai. It is also one of the high snow peaks closest to a city in China — accessibility directly drives how popular a peak becomes as a training objective.",

    "q.m08#3.p" to "What are the approach distance and typical time for Gangshika's third peak?",
    "q.m08#3.o0" to "About 3 km / 2 hours",
    "q.m08#3.o1" to "About 10 km / 6 hours",
    "q.m08#3.o2" to "About 25 km / two days",
    "q.m08#3.o3" to "About 1 km / 30 minutes",
    "q.m08#3.e" to "About 10 km and six hours. That load is exactly right for a first technical climb: you are not winning by enduring a long slog, but by concentrating on technique and judgement.",

    "q.m08#4.p" to "What is the altitude of Haba Snow Mountain?",
    "q.m08#4.o0" to "5,005 m",
    "q.m08#4.o1" to "5,254 m",
    "q.m08#4.o2" to "5,396 m",
    "q.m08#4.o3" to "5,642 m",
    "q.m08#4.e" to "Haba is 5,396 m, in Shangri-La, Yunnan. Its value is that above the snowline there is real ice, requiring crampons and an axe, yet without the strict acclimatisation pressure of a 6,000 m peak.",

    "q.m08#5.p" to "Where does Haba Snow Mountain demand technical skill?",
    "q.m08#5.o0" to "It requires rock climbing ability",
    "q.m08#5.o1" to "Above the snowline there is an ice slope requiring crampons and an axe",
    "q.m08#5.o2" to "It requires diving ability",
    "q.m08#5.o3" to "It needs no technical equipment at all",
    "q.m08#5.e" to "Haba's keyword is 'ice above the snowline'. You must be able to move steadily on ice in crampons and use the axe for support and arrest — exactly what the earlier lessons in this 5,000 m progression unit cover.",

    "q.m08#6.p" to "What are Elbrus's altitude and status?",
    "q.m08#6.o0" to "5,642 m, the highest peak in Europe",
    "q.m08#6.o1" to "5,895 m, the highest in Africa",
    "q.m08#6.o2" to "5,254 m, the highest in the Qilian range",
    "q.m08#6.o3" to "6,178 m, a high peak of the Kunlun",
    "q.m08#6.e" to "Elbrus is 5,642 m, the highest peak in Europe, in Russia's Caucasus. Its place in the progression is unusual: 5,000 m class in altitude, but requiring glacier travel and roping up — a classic bridge from trekking peaks to technical ones.",

    "q.m08#7.p" to "What are the basic requirements for climbing Elbrus?",
    "q.m08#7.o0" to "Fitness alone",
    "q.m08#7.o1" to "Crampons and an axe; glacier travel and roping up are basic requirements",
    "q.m08#7.o2" to "Supplemental oxygen",
    "q.m08#7.o3" to "Rock climbing ability",
    "q.m08#7.e" to "Elbrus's route crosses glaciers, so roping up, crevasse awareness and crampon use are all baseline. It is often compared with Kilimanjaro: both 5,000 m class, one a pure trek and one needing genuine technical work.",

    "q.m08#8.p" to "[Multiple choice] When moving from trekking peaks to technical peaks, which abilities should you build first?",
    "q.m08#8.o0" to "Correct use of technical gear (crampons, axe, harness)",
    "q.m08#8.o1" to "Basic technical actions such as arresting a fall",
    "q.m08#8.o2" to "Roped glacier travel and basic protection systems",
    "q.m08#8.o3" to "Judgement about when not to continue",
    "q.m08#8.o4" to "Buying more expensive equipment",
    "q.m08#8.e" to "The first three are abilities; the fourth is a constraint. Many people build only the first three and end up more confident as they become more skilled — which raises the risk. Technical and judgement training must advance together, which is why this unit pairs technique lessons with peak lessons.",

    "q.m08#9.p" to "[Order] Put these objectives in order of increasing difficulty.",
    "q.m08#9.o0" to "Aotaina (trekking, no technical difficulty)",
    "q.m08#9.o1" to "Gangshika third peak (entry-level technical)",
    "q.m08#9.o2" to "Haba / Elbrus (mixed, crampons and roping up)",
    "q.m08#9.o3" to "Yuzhu south slope (6,000 m mixed)",
    "q.m08#9.e" to "The key is adding one new variable at a time: no technique, then technical gear, then using it on real ice, then adding altitude. The usual mistake is not skipping a step but maxing difficulty and altitude at once, so you cannot tell which one you were unprepared for.",

    "q.m08#10.p" to "Why is third peak to main peak a sensible progression?",
    "q.m08#10.o0" to "Because the third peak is closest to the main peak",
    "q.m08#10.o1" to "Because different routes on one mountain separate technical difficulty from environmental difficulty",
    "q.m08#10.o2" to "Because the main peak is cheaper",
    "q.m08#10.o3" to "Because it is easier to get lost on the third peak",
    "q.m08#10.e" to "Advancing on the same mountain keeps the environmental variables — weather, access, logistics, guides — roughly constant, so you can feel clearly where the extra difficulty comes from. Change mountain every time and you can never tell whether technique or acclimatisation was the limit.",

    "q.m08#11.p" to "What is the right attitude to choosing a 5,000 m progression objective?",
    "q.m08#11.o0" to "Pick the highest one and skip the steps",
    "q.m08#11.o1" to "Add one new difficulty at a time, and prioritise reliable support",
    "q.m08#11.o2" to "Pick the cheapest",
    "q.m08#11.o3" to "Look only at summit rate, not technical demands",
    "q.m08#11.e" to "Ability builds cumulatively, and every skipped step multiplies risk. Reliable support — guides, rescue, a retreat plan — is the shared safety base at every entry level: it cannot stop you making a mistake, but it keeps a mistake from being fatal.",

    // ---------- m09 ----------
    "q.m09#0.p" to "What are the two basic goals of medication at altitude?",
    "q.m09#0.o0" to "Cure altitude illness and replace descent",
    "q.m09#0.o1" to "Speed up acclimatisation and buy time for descent",
    "q.m09#0.o2" to "Improve fitness and endurance",
    "q.m09#0.o3" to "Prevent colds and improve sleep",
    "q.m09#0.e" to "Keeping these two apart is critical: acetazolamide belongs to the first (faster acclimatisation), dexamethasone and nifedipine to the second (buying time). Treating a time-buying drug as evidence of recovery is the most dangerous misjudgement in altitude care.",

    "q.m09#1.p" to "Does dexamethasone affect acclimatisation?",
    "q.m09#1.o0" to "Yes, it speeds it up",
    "q.m09#1.o1" to "No, it has no effect on acclimatisation at all",
    "q.m09#1.o2" to "Yes, it slows it down",
    "q.m09#1.o3" to "Only with long-term use",
    "q.m09#1.e" to "The manual is blunt: dexamethasone relieves cerebral oedema symptoms, has no effect on acclimatisation and does not treat pulmonary oedema. It is purely buying time — and the time it buys must be spent descending.",

    "q.m09#2.p" to "Which side effect of nifedipine needs the most caution?",
    "q.m09#2.o0" to "Drowsiness",
    "q.m09#2.o1" to "A rapid drop in blood pressure, so standing up quickly can cause fainting",
    "q.m09#2.o2" to "Tinnitus",
    "q.m09#2.o3" to "Loss of appetite",
    "q.m09#2.e" to "This is dangerous in real situations: fainting from postural hypotension on a steep slope or stepping out of a tent at night can have more immediate consequences than the altitude illness itself. The manual also notes nifedipine may help trekkers but is not the best choice for climbers.",

    "q.m09#3.p" to "What is the right attitude to altitude medication?",
    "q.m09#3.o0" to "Memorise the dose and use it yourself",
    "q.m09#3.o1" to "It is a medical decision — assess with a doctor and follow their instructions",
    "q.m09#3.o2" to "Team members can share it freely",
    "q.m09#3.o3" to "Side effects do not affect use",
    "q.m09#3.e" to "Each drug has specific indications, contraindications and side effects (nifedipine lowers blood pressure, aspirin carries bleeding risk, dexamethasone is a steroid). These are not 'altitude common sense' but medical interventions — hence the repeated emphasis on medical advice.",

    "q.m09#4.p" to "Symptoms ease after dexamethasone. What should you do?",
    "q.m09#4.o0" to "Continue ascending as planned",
    "q.m09#4.o1" to "Still do not ascend; descend as soon as possible",
    "q.m09#4.o2" to "Increase the dose and continue",
    "q.m09#4.o3" to "Stop the drug immediately and observe",
    "q.m09#4.e" to "The drug removes the symptoms, but the cause of the cerebral oedema — hypoxia — remains. The manual's conclusion is clear: even with symptom relief, do not continue gaining altitude. Descent is the only action that removes the cause.",

    "q.m09#5.p" to "How is aspirin used for altitude headache?",
    "q.m09#5.o0" to "Take it when the pain starts",
    "q.m09#5.o1" to "Preventively: start early and dose regularly",
    "q.m09#5.o2" to "Only at bedtime",
    "q.m09#5.o3" to "Only after descending",
    "q.m09#5.e" to "The manual gives 320 mg three times daily starting the day before ascent, until acclimatisation is complete — a regular preventive regimen, not take-it-when-it-hurts. The two approaches work on completely different logic.",

    "q.m09#6.p" to "What is the fundamental difference between acetazolamide and dexamethasone?",
    "q.m09#6.o0" to "One is cheap and one is expensive",
    "q.m09#6.o1" to "One speeds acclimatisation, the other only relieves symptoms",
    "q.m09#6.o2" to "One is oral and one injectable",
    "q.m09#6.o3" to "They work identically",
    "q.m09#6.e" to "This distinction decides everything downstream: with acetazolamide, improvement can be read as the body genuinely acclimatising; with dexamethasone, improvement is only masking — and whether you may keep ascending has opposite answers in the two cases.",

    "q.m09#7.p" to "[Multiple choice] Which statements about altitude medication are correct?",
    "q.m09#7.o0" to "Medication cannot replace descent",
    "q.m09#7.o1" to "Dose and timing need medical guidance",
    "q.m09#7.o2" to "Different drugs target different conditions and must not be mixed up",
    "q.m09#7.o3" to "Once medication masks the symptoms, judgement becomes harder",
    "q.m09#7.o4" to "Once symptoms ease you can safely keep ascending",
    "q.m09#7.e" to "The first four are key. The most overlooked is that masking makes judgement harder: with symptoms gone you lose your most direct gauge, and must rely on more objective signs — gait, consciousness, breathing. So after giving the drug, watch those three even more closely.",

    "q.m09#8.p" to "Why is 'no drugs, descend now' often the most reliable choice?",
    "q.m09#8.o0" to "Because drugs do not work",
    "q.m09#8.o1" to "Because descent removes the cause, while drugs only act indirectly",
    "q.m09#8.o2" to "Because drugs are expensive",
    "q.m09#8.o3" to "Because drugs are awkward to carry",
    "q.m09#8.e" to "The cause of altitude illness is hypoxia, and hypoxia comes directly from altitude. Descent removes the cause; drugs only change how the body responds to it. Whenever conditions allow, descent is the highest-priority action.",

    "q.m09#9.p" to "[Order] A team member shows signs of severe altitude illness. What is the right sequence?",
    "q.m09#9.o0" to "Stop ascending immediately; assess consciousness, gait and breathing",
    "q.m09#9.o1" to "Arrange descent (at least 1,000 m), with oxygen if available",
    "q.m09#9.o2" to "Give the appropriate drug (such as dexamethasone) under medical supervision",
    "q.m09#9.o3" to "If descent is impossible, use a hyperbaric chamber and call for rescue",
    "q.m09#9.e" to "The order is the priority: assess, descend, support with drugs, and only then reach for time-buying measures. The commonest real-world error is reversing it — hunting for the drug first and forgetting that descent is the definitive treatment.",

    "q.m09#10.p" to "Why is discussing a medication plan with a doctor beforehand so important for high-altitude trips?",
    "q.m09#10.o0" to "Because you cannot buy drugs on the mountain",
    "q.m09#10.o1" to "Because professional advice is unavailable up there, and vomiting can change the route of administration",
    "q.m09#10.o2" to "Because drugs expire",
    "q.m09#10.o3" to "Because guides require it",
    "q.m09#10.e" to "At altitude there is no doctor and no diagnostics; worse, the patient may be vomiting and unable to take anything orally. The plan — dose, timing, route and contraindications — has to be agreed before departure.",

    "q.m09#11.p" to "[Matching] Match each drug to its main action.",
    "q.m09#11.l0" to "Acetazolamide",
    "q.m09#11.l1" to "Dexamethasone",
    "q.m09#11.l2" to "Nifedipine",
    "q.m09#11.r0" to "Speeds acclimatisation; used preventively",
    "q.m09#11.r1" to "Lowers intracranial pressure and eases cerebral oedema",
    "q.m09#11.r2" to "Relieves pulmonary vasoconstriction; used for pulmonary oedema",
    "q.m09#11.e" to "Three cards, three jobs: acetazolamide for acclimatisation, dexamethasone for the brain, nifedipine for the lungs. First work out which problem the patient has, then pick the card — rather than treating every drug as a generic 'altitude pill'.",

    // ---------- m10 ----------
    "q.m10#0.p" to "What is a weather window?",
    "q.m10#0.o0" to "The day with the lowest precipitation chance in the forecast",
    "q.m10#0.o1" to "The period in which you can safely complete the objective",
    "q.m10#0.o2" to "The hours with the most daylight",
    "q.m10#0.o3" to "The time with the least wind",
    "q.m10#0.e" to "A weather window is a combined idea: it satisfies both 'the weather allows it' and 'the team can do it'. So under identical weather, a strong team's window and a weak team's window are completely different widths — windows are relative, not absolute.",

    "q.m10#1.p" to "Why is mountain weather forecasting relatively imprecise?",
    "q.m10#1.o0" to "Because there are too few weather stations",
    "q.m10#1.o1" to "Because complex terrain creates huge local variation — different altitudes and aspects can have completely different weather",
    "q.m10#1.o2" to "Because forecasters are careless",
    "q.m10#1.o3" to "Because there is no data at altitude",
    "q.m10#1.e" to "Orographic lift, blocking and flow around ridges split the weather sharply at small scales — a few kilometres away can be a different world. A regional forecast is background only; field observation is what you decide on.",

    "q.m10#2.p" to "Cloud thickening and the cloud base dropping usually indicate what?",
    "q.m10#2.o0" to "Improving weather",
    "q.m10#2.o1" to "Deteriorating weather, with visibility likely to fall fast",
    "q.m10#2.o2" to "Imminent clearing",
    "q.m10#2.o3" to "Nothing in particular",
    "q.m10#2.e" to "A lowering cloud base means rising humidity and a falling condensation level — often the precursor of a precipitation system. In the mountains it also means your view is about to shrink, which is a risk in its own right.",

    "q.m10#3.p" to "Why does the pressure trend matter more than the pressure value?",
    "q.m10#3.o0" to "Because the value is always wrong",
    "q.m10#3.o1" to "Because weather is driven by the change in pressure, and baseline values differ with altitude anyway",
    "q.m10#3.o2" to "Because trends are easier to remember",
    "q.m10#3.o3" to "Because values fluctuate too much",
    "q.m10#3.e" to "The same pressure reading means completely different things at different altitudes and places, so an isolated number has no reference frame. A sustained fall, by contrast, points to the same thing everywhere: the weather is turning.",

    "q.m10#4.p" to "What is the practical value of the Beaufort scale?",
    "q.m10#4.o0" to "It makes wind look more professional",
    "q.m10#4.o1" to "It converts wind speed into an observable, communicable scale for judging mobility and talking to each other",
    "q.m10#4.o2" to "It measures precipitation",
    "q.m10#4.o3" to "It estimates temperature",
    "q.m10#4.e" to "Wind is information that has to be spoken: a team needs a shared language for 'can we keep going'. Beaufort turns an abstract speed into observable signs — leaves, spindrift, how it feels — so the judgement travels quickly through the group.",

    "q.m10#5.p" to "[Multiple choice] Which of these are field signs that the weather is deteriorating?",
    "q.m10#5.o0" to "Pressure falling steadily",
    "q.m10#5.o1" to "Cloud thickening quickly and the base lowering",
    "q.m10#5.o2" to "Wind strengthening noticeably and shifting direction often",
    "q.m10#5.o3" to "Cumulonimbus building in the distance",
    "q.m10#5.o4" to "Pressure rising steadily and wind easing",
    "q.m10#5.e" to "The first four are the main deterioration signals in the manual. They all describe a trend rather than an instant — which is why regular, timed observation matters. Only with something to compare against does a trend mean anything.",

    "q.m10#6.p" to "During a thunderstorm, which behaviour is most dangerous?",
    "q.m10#6.o0" to "Stopping and descending",
    "q.m10#6.o1" to "Staying on a ridge, summit or open water — anywhere exposed",
    "q.m10#6.o2" to "Packing away metal equipment",
    "q.m10#6.o3" to "Crouching low and waiting",
    "q.m10#6.e" to "The worst thing in a thunderstorm is to be the tallest object around. Ridges and summits are exactly the most exposed places, so leave as soon as lightning threatens. Keep metal gear together and away from your body.",

    "q.m10#7.p" to "Why are summit pushes usually started before dawn?",
    "q.m10#7.o0" to "To avoid the crowds",
    "q.m10#7.o1" to "Because early morning is usually the most stable part of the day, while afternoon convection increases and the odds worsen",
    "q.m10#7.o2" to "Because you have the most energy at 3 a.m.",
    "q.m10#7.o3" to "Because it is too hot during the day",
    "q.m10#7.e" to "It follows the daily cycle: daytime heating drives convection, so cloud and precipitation chances rise in the afternoon. Putting the hardest, most critical part of the climb before dawn is buying a more forgiving window.",

    "q.m10#8.p" to "How does the turnaround time relate to the weather window?",
    "q.m10#8.o0" to "They are unrelated",
    "q.m10#8.o1" to "The turnaround should be derived from the weather window; a narrowing window moves it earlier",
    "q.m10#8.o2" to "The turnaround is always fixed",
    "q.m10#8.o3" to "Good weather means no turnaround is needed",
    "q.m10#8.e" to "The turnaround is not a fixed number; it is calculated from the day's window. How long to the summit, how long to descend, when the window starts closing — working backwards gives the latest moment you must turn.",

    "q.m10#9.p" to "[Order] Put the steps of a routine weather judgement in a sensible order.",
    "q.m10#9.o0" to "Before departure, check the regional forecast and the pressure trend",
    "q.m10#9.o1" to "While moving, observe cloud, wind and visibility at regular intervals",
    "q.m10#9.o2" to "Compare field observations with the forecast to judge the direction of the trend",
    "q.m10#9.o3" to "Adjust the plan or turn back early according to that trend",
    "q.m10#9.e" to "Step three is the crux — many people stop at step two, feeling that the weather is changing without turning it into a decision. Observation that never becomes action is not observation.",

    "q.m10#10.p" to "As the weather window narrows, what should you give up first?",
    "q.m10#10.o0" to "Safety equipment",
    "q.m10#10.o1" to "The summit objective itself",
    "q.m10#10.o2" to "Team members",
    "q.m10#10.o3" to "Communication equipment",
    "q.m10#10.e" to "This is a question of priority: when the window cannot hold both the summit and a safe descent, what you keep is the descent and what you drop is the summit. Decide that before you leave, not on the mountain.",

    "q.m10#11.p" to "Which view of whiteout conditions is correct?",
    "q.m10#11.o0" to "Just poor visibility, no danger",
    "q.m10#11.o1" to "You lose every visual reference and instinctively walk the wrong way — fix your position first",
    "q.m10#11.o2" to "It brings precipitation",
    "q.m10#11.o3" to "It only happens at night",
    "q.m10#11.e" to "The danger of a whiteout is not that you cannot see — it is that you think you can. Without references your sense of direction drifts systematically, so the first job is to fix position and record the heading, not to keep walking.",

    // ---------- m11 ----------
    "q.m11#0.p" to "What are Yuzhu Peak's altitude and location?",
    "q.m11#0.o0" to "6,178 m, Golmud, Qinghai, eastern Kunlun range",
    "q.m11#0.o1" to "6,206 m, Damxung, Tibet, Nyainqêntanglha range",
    "q.m11#0.o2" to "6,119 m, Khumbu, Nepal",
    "q.m11#0.o3" to "6,189 m, Khumbu, Nepal",
    "q.m11#0.e" to "Yuzhu is 6,178 m, in the eastern Kunlun range within Golmud, Qinghai. Its south-slope route is relatively gentle and access is good, which is why it is many people's first 6,000 m peak.",

    "q.m11#1.p" to "What are Qizi Peak's altitude and range?",
    "q.m11#1.o0" to "6,178 m, Kunlun range",
    "q.m11#1.o1" to "6,206 m, Nyainqêntanglha range",
    "q.m11#1.o2" to "6,119 m, Himalaya",
    "q.m11#1.o3" to "6,189 m, Karakoram",
    "q.m11#1.e" to "Qizi is 6,206 m, in the Nyainqêntanglha range at Damxung, Tibet. Its hallmark is stable snow slopes and easy access — stable slopes mean avalanche and crevasse risk are comparatively manageable, which suits it for progression training.",

    "q.m11#2.p" to "What are Lobuche East's altitude and location?",
    "q.m11#2.o0" to "6,119 m, Khumbu, Nepal",
    "q.m11#2.o1" to "6,189 m, Khumbu, Nepal",
    "q.m11#2.o2" to "6,206 m, Damxung, Tibet",
    "q.m11#2.o3" to "6,178 m, Golmud, Qinghai",
    "q.m11#2.e" to "Lobuche East is 6,119 m in the Khumbu region of Nepal, right beside the Everest trekking route. That position means established acclimatisation and logistics, and its steeper snow slopes make it a good step towards higher altitude.",

    "q.m11#3.p" to "What is Island Peak's (Imja Tse) most typical technical feature?",
    "q.m11#3.o0" to "No technical equipment required at all",
    "q.m11#3.o1" to "Roping up and travelling over crevasses",
    "q.m11#3.o2" to "Supplemental oxygen required",
    "q.m11#3.o3" to "Rock climbing ability required",
    "q.m11#3.e" to "Island Peak at 6,189 m is a classic 6,000 m technical peak: you rope up and you manage crevasses. That is also why it is used as preparation for 7,000 m — it puts the glacier-travel-plus-rope-team system into real use.",

    "q.m11#4.p" to "Compared with 5,000 m, what risk rises most at 6,000 m?",
    "q.m11#4.o0" to "Rockfall",
    "q.m11#4.o1" to "Altitude acclimatisation pressure and the risk of altitude illness",
    "q.m11#4.o2" to "Insects",
    "q.m11#4.o3" to "The weight of equipment",
    "q.m11#4.e" to "Above 6,000 m the incidence and severity of altitude illness rise markedly — which is why this unit treats altitude illness as a core chapter. Technically the step may be gradual, but the physiological step is real.",

    "q.m11#5.p" to "[Multiple choice] What should you already have mastered before a 6,000 m peak?",
    "q.m11#5.o0" to "Basic use of crampons and an ice axe",
    "q.m11#5.o1" to "Basic knots and roped travel",
    "q.m11#5.o2" to "Recognising and managing altitude illness",
    "q.m11#5.o3" to "A basic understanding of crevasse risk",
    "q.m11#5.o4" to "Leading WI5 ice independently",
    "q.m11#5.e" to "The first four map onto the 5,000 m entry and progression units. The 6,000 m unit does not reteach them; it puts them into a harsher environment. Going straight to 6,000 m with weak fundamentals multiplies the risk.",

    "q.m11#6.p" to "Why is Yuzhu's south slope often the first 6,000 m objective?",
    "q.m11#6.o0" to "Because it is the cheapest",
    "q.m11#6.o1" to "Because the route is relatively gentle and access and logistics are established, so you can focus on acclimatisation",
    "q.m11#6.o2" to "Because it has no danger",
    "q.m11#6.o3" to "Because it needs no guide",
    "q.m11#6.e" to "The value of a first objective is adding only one new variable. The south slope keeps technical difficulty inside a manageable range so you can concentrate on the real challenge — acclimatisation. Choose a technically demanding 6,000 m and you will not be able to tell what went wrong.",

    "q.m11#7.p" to "[Order] Arrange these objectives from lowest to highest altitude.",
    "q.m11#7.o0" to "Lobuche East (6,119 m)",
    "q.m11#7.o1" to "Yuzhu Peak (6,178 m)",
    "q.m11#7.o2" to "Island Peak (6,189 m)",
    "q.m11#7.o3" to "Qizi Peak (6,206 m)",
    "q.m11#7.e" to "The altitude spread is tiny — 6,119 to 6,206 m, less than 90 m. Which makes the point neatly: in the 6,000 m band you should choose by route type, support and your own weak points, not by the height number.",

    "q.m11#8.p" to "Why must you assume crevasses are present at 6,000 m?",
    "q.m11#8.o0" to "Because crevasses make noise",
    "q.m11#8.o1" to "Because snow bridges can be completely covered by fresh snow and look like ordinary ground",
    "q.m11#8.o2" to "Because crevasses only appear at night",
    "q.m11#8.o3" to "Because crevasses are easy to identify",
    "q.m11#8.e" to "That is exactly what makes crevasses so lethal: unlike rockfall they give no clear warning. The right mindset at 6,000 m is 'they are everywhere', managing the risk with rope teams and equipment rather than judging by whether it looks safe.",

    "q.m11#9.p" to "When choosing a 6,000 m peak, what matters more than altitude?",
    "q.m11#9.o0" to "How famous the peak is",
    "q.m11#9.o1" to "Route type (trekking / mixed / technical), support conditions and the pace of ascent",
    "q.m11#9.o2" to "The cost",
    "q.m11#9.o3" to "Social media popularity",
    "q.m11#9.e" to "Peaks of similar altitude can differ hugely in technical demand and acclimatisation pressure. Only by combining route type, support and ascent pace do you get an answer to 'is this mountain right for me now'.",

    "q.m11#10.p" to "Which view of the 6,000 m technical threshold is correct?",
    "q.m11#10.o0" to "It is very low; fitness is all that matters",
    "q.m11#10.o1" to "It is not high, but you cannot start from zero, and glacier travel skills are mandatory",
    "q.m11#10.o2" to "You must have a rock climbing background",
    "q.m11#10.o3" to "You must know how to use supplemental oxygen",
    "q.m11#10.e" to "The typical 6,000 m profile: moderate technical difficulty, but you must already be able to rope up, judge crevasse risk and move independently on a glacier. It is where 'I can protect myself with a system' begins — not where you watch others do it.",

    "q.m11#11.p" to "Why is a peak's best season so critical to the plan?",
    "q.m11#11.o0" to "Because permits are cheaper off-season",
    "q.m11#11.o1" to "Because the climbable window depends heavily on seasonal weather patterns; the wrong season may offer almost no window",
    "q.m11#11.o2" to "Because the season changes the colour of the snow",
    "q.m11#11.o3" to "Because guides only work in high season",
    "q.m11#11.e" to "The reasons differ by peak: some seasons avoid monsoon precipitation, others avoid extreme winter cold and wind. Understanding why a season works matters far more than memorising which month — especially as climate change is shifting these patterns.",

    // ---------- m12 ----------
    "q.m12#0.p" to "Why does a 3:1 Z-system (Z-drag) produce three times the pulling force?",
    "q.m12#0.o0" to "Because it uses a thicker rope",
    "q.m12#0.o1" to "Because the prusik and pulley combination multiplies your pull distance by three",
    "q.m12#0.o2" to "Because gravity helps",
    "q.m12#0.o3" to "Because pulleys save effort automatically",
    "q.m12#0.e" to "Mechanical advantage is fundamentally trading distance for force: you pull three metres of rope and the load rises one metre. The cost is speed — and in crevasse rescue that cost is entirely acceptable.",

    "q.m12#1.p" to "What is the pulley's main job in a rescue system?",
    "q.m12#1.o0" to "To provide extra strength",
    "q.m12#1.o1" to "To reduce rope friction losses and improve system efficiency",
    "q.m12#1.o2" to "To fix the rope",
    "q.m12#1.o3" to "To protect the rope from wear",
    "q.m12#1.e" to "Friction is the hidden enemy of mechanical advantage: every redirect costs some force. A pulley turns sliding friction into rolling friction, so the theoretical 3:1 comes closer to a real 3:1.",

    "q.m12#2.p" to "Can a rescue system be built without pulleys?",
    "q.m12#2.o0" to "Not at all",
    "q.m12#2.o1" to "Yes, with carabiners — but friction rises noticeably and efficiency drops",
    "q.m12#2.o2" to "Yes, with rope alone, at the same efficiency",
    "q.m12#2.o3" to "No, you must wait for equipment",
    "q.m12#2.e" to "Carabiners can substitute for pulleys, which is why many teams treat spare lockers as mandatory. The difference is that actual advantage falls well below the theoretical value — knowing that lets you prepare mentally and physically when the rack is incomplete.",

    "q.m12#3.p" to "[Multiple choice] What does the manual list as standard rope-team rescue kit?",
    "q.m12#3.o0" to "2–3 snow pickets or ice screws",
    "q.m12#3.o1" to "2–5 carabiners and 2–5 slings",
    "q.m12#3.o2" to "1 belay pulley",
    "q.m12#3.o3" to "2–3 prusiks and 1 ascender",
    "q.m12#3.o4" to "1 portable stove and gas canister",
    "q.m12#3.e" to "The key line in that list is that every rope-team member should carry enough rescue kit — meaning it is personal equipment, not shared group gear. When someone falls, what is on your harness is the only equipment available.",

    "q.m12#4.p" to "How does an ascender brake?",
    "q.m12#4.o0" to "With a spring clamping the rope",
    "q.m12#4.o1" to "By reverse friction between steel teeth and the rope",
    "q.m12#4.o2" to "By magnetic attraction",
    "q.m12#4.o3" to "By the rope's own weight",
    "q.m12#4.e" to "Understanding the mechanism matters in use: because steel teeth bite into the fibres, excessive force damages the rope and can cut fibres at the loaded point. That is why the manual stresses using it with an assisted-braking method where possible.",

    "q.m12#5.p" to "What happens if you yank an ascender too hard?",
    "q.m12#5.o0" to "Nothing at all",
    "q.m12#5.o1" to "The steel teeth damage the rope",
    "q.m12#5.o2" to "The ascender jams",
    "q.m12#5.o3" to "The ascender falls off",
    "q.m12#5.e" to "The teeth brake by reverse friction, so heavy force scars the sheath and, cumulatively, can create a failure point. You will see plenty of people habitually ripping on the ascender — trading a habit for risk.",

    "q.m12#6.p" to "[Order] Put the steps of building a 3:1 Z-system in a sensible order.",
    "q.m12#6.o0" to "Confirm the anchor is sound and transfer the fallen climber's weight to it",
    "q.m12#6.o1" to "Fit the main prusik on the loaded rope and add a backup prusik",
    "q.m12#6.o2" to "Connect a pulley or carabiner to the prusik to form the Z path",
    "q.m12#6.o3" to "Check the whole system, then haul, re-tensioning after each pull",
    "q.m12#6.e" to "The first step is the foundation: without transferring the weight, your hands stay committed to holding the arrest. And the last step — re-tensioning after each pull — is easily skipped, which is how people haul for ages and then slide back.",

    "q.m12#7.p" to "[Matching] Match each rescue item to its role in the system.",
    "q.m12#7.l0" to "Prusik",
    "q.m12#7.l1" to "Pulley",
    "q.m12#7.l2" to "Belay pulley",
    "q.m12#7.l3" to "Ascender",
    "q.m12#7.r0" to "One-way grip, so the system can advance and not run back",
    "q.m12#7.r1" to "Reduces friction losses and improves efficiency",
    "q.m12#7.r2" to "Locks in one direction; used to control paying out and tightening",
    "q.m12#7.r3" to "Travels up the rope; also useful for fixing the system",
    "q.m12#7.e" to "Four different jobs: the prusik provides one-way behaviour, the pulley cuts friction, the belay device provides control, and the ascender provides mobility. Lose any one and the system becomes either inefficient or uncontrollable.",

    "q.m12#8.p" to "Why add a backup prusik alongside the main one?",
    "q.m12#8.o0" to "For appearance",
    "q.m12#8.o1" to "Because a prusik can fail through icing, dirt or mismatched diameters, and failure instantly loses the advantage",
    "q.m12#8.o2" to "Because the rules require it",
    "q.m12#8.o3" to "To prevent the rope kinking",
    "q.m12#8.e" to "A prusik works by friction, and friction depends on many things. If the main one slips, the fallen climber drops again with no warning — the backup's job is to catch that instant.",

    "q.m12#9.p" to "How do you choose between a 2:1 and a 3:1 system?",
    "q.m12#9.o0" to "2:1 is always better",
    "q.m12#9.o1" to "By manpower, rope length and terrain: more advantage needs more rope and is slower",
    "q.m12#9.o2" to "3:1 is always better",
    "q.m12#9.o3" to "They are identical",
    "q.m12#9.e" to "Mechanical advantage is not unconditionally good: 3:1 needs more rope, and crevasse rescue often has limited rope. The real choice is the system you can complete with the rope and people you have — not the theoretically optimal one.",

    "q.m12#10.p" to "Why can a mechanical-advantage system never replace judgement?",
    "q.m12#10.o0" to "Because systems break",
    "q.m12#10.o1" to "Because a system only multiplies force; it cannot decide whether to haul or which way",
    "q.m12#10.o2" to "Because systems are heavy",
    "q.m12#10.o3" to "Because they need many people",
    "q.m12#10.e" to "The hard part of a rescue is never the physics; it is the judgement — which way, over which edge, and whether the casualty can survive it. The system is a tool; direction comes from people. Get the direction wrong and more force makes it worse.",

    "q.m12#11.p" to "Which of these does not cause a prusik to fail?",
    "q.m12#11.o0" to "Mismatched rope diameters",
    "q.m12#11.o1" to "Ice or dirt",
    "q.m12#11.o2" to "Too few wraps",
    "q.m12#11.o3" to "A lighter-coloured main rope",
    "q.m12#11.e" to "Diameter, cleanliness and the number of wraps all directly affect friction; colour has nothing to do with mechanics. It also shows that prusik reliability cannot be judged by eye — only by checking the combination beforehand and testing it in the field.",

    "q.m12#12.p" to "Why is a belay pulley often used instead of a plain pulley?",
    "q.m12#12.o0" to "Because it is lighter",
    "q.m12#12.o1" to "Because it locks in one direction, so you can control release without the system running back",
    "q.m12#12.o2" to "Because it is cheaper",
    "q.m12#12.o3" to "Because the colour is more visible",
    "q.m12#12.e" to "Rescues often involve hauling and adjusting at the same time, and a plain pulley runs freely both ways — let go and you lose progress. A one-way locking component makes holding position a property of the system. A clear example of hardware choice affecting operational safety.",

    "q.m12#13.p" to "Fill in: the mechanical advantage of the Z-system is ( ):1.",
    "q.m12#13.a0" to "3",
    "q.m12#13.a1" to "three",
    "q.m12#13.e" to "3:1. The practical value of that number is load estimation: an adult with equipment may weigh 80–100 kg, so at 3:1 you still have to pull with about 30 kg of force — far harder than it sounds, which is why rescues need several people.",

    "q.m12#14.p" to "[Multiple choice] What should the post-build check cover?",
    "q.m12#14.o0" to "Prusik wraps and load direction are correct",
    "q.m12#14.o1" to "Pulleys and carabiners are locked",
    "q.m12#14.o2" to "Attachment points are on the right part of the harness",
    "q.m12#14.o3" to "A backup is in place and the rope is not jammed",
    "q.m12#14.o4" to "The rope and your partners' clothing are the same colour",
    "q.m12#14.e" to "The four checks map onto four classic errors: prusik reversed, gate unlocked, clipped to the wrong loop, no backup. Rescue system failures are rarely a lack of knowledge — they are a missed step in the dark and the stress. Use a checklist, not memory.",

    "q.m12#15.p" to "Why must a rescue system be rehearsed before departure?",
    "q.m12#15.o0" to "To pass an assessment",
    "q.m12#15.o1" to "Because the real rescue happens at altitude, in cold and darkness, performed from instinct",
    "q.m12#15.o2" to "To get familiar with the gear",
    "q.m12#15.o3" to "Because regulations specify rehearsal hours",
    "q.m12#15.e" to "Conditions at a real rescue are almost always the worst possible: windy, cold hands, poor light, a partner getting worse. The only actions that get done in those conditions are the ones you have repeated many times before — learning on the spot is not an option.",

    // ---------- m13 自救能力（14 题） ----------
    "q.m13#0.p" to "Why is self-rescue a hard requirement at 7,000 m?",
    "q.m13#0.o0" to "Because teammates are unwilling to rescue you",
    "q.m13#0.o1" to "Because in high-altitude conditions partners may not reach you in time — you must be able to handle your own situation",
    "q.m13#0.o2" to "Because rescue gear is insufficient",
    "q.m13#0.o3" to "Because the rules require it",
    "q.m13#0.e" to "The higher you go, the more costly and slower rescue becomes. A partner may be fighting their own altitude illness, and the weather may forbid any movement at all. Handing yourself entirely to outside rescue means accepting a premise nobody can guarantee.",

    "q.m13#1.p" to "What is the basic principle of prusik self-ascent?",
    "q.m13#1.o0" to "Pulling yourself up with arm strength",
    "q.m13#1.o1" to "Alternating two prusiks: one bears weight while the other slides up the rope",
    "q.m13#1.o2" to "Doing it alone with an ascender",
    "q.m13#1.o3" to "Gripping the rope between your legs",
    "q.m13#1.e" to "A single prusik only holds a position — it cannot move — so two must alternate: while the lower one bears weight the upper one slides up, and vice versa. This alternating motion has to be drilled in a safe setting; it will decide, at the moment you most need it, whether you get up at all.",

    "q.m13#2.p" to "Why must at least one prusik always stay loaded during prusik ascent?",
    "q.m13#2.o0" to "To save effort",
    "q.m13#2.o1" to "Because releasing both at once sends you sliding back to the start or falling outright",
    "q.m13#2.o2" to "To keep the rope tidy",
    "q.m13#2.o3" to "To climb faster",
    "q.m13#2.e" to "This is the three-point rule applied to rope: always keep one reliable point of support. In a crevasse, one slip not only drains strength but may let the rope cut further into the snow lip, raising the difficulty of the whole rescue.",

    "q.m13#3.p" to "[Order] Put the four steps of a rope-team rescue in the correct order.",
    "q.m13#3.o0" to "Self-arrest immediately and stabilise yourself",
    "q.m13#3.o1" to "Build an independent anchor",
    "q.m13#3.o2" to "Transfer the load to the anchor",
    "q.m13#3.o3" to "Haul with a 3:1 system",
    "q.m13#3.e" to "You learned these four steps in the 6,000 m unit; what matters here is executing them under pressure. The biggest gap between practice and the real thing: in the real thing you must finish the first three steps in tens of seconds, while in practice you may have taken five minutes.",

    "q.m13#4.p" to "How far apart should team members stay when caught in a thunderstorm?",
    "q.m13#4.o0" to "Huddled together",
    "q.m13#4.o1" to "About 50 m",
    "q.m13#4.o2" to "About 500 m",
    "q.m13#4.o3" to "No limit",
    "q.m13#4.e" to "The handbook suggests roughly 50 m apart — the point is to avoid one strike injuring several people at once, so that someone remains able to give first aid. Behind the number is a simple idea: never stake everything in one place.",

    "q.m13#5.p" to "What is the only effective way to reduce danger during a thunderstorm?",
    "q.m13#5.o0" to "Throw away metal gear such as ice axes",
    "q.m13#5.o1" to "Leave high points and exposed terrain as fast as possible, staying as low as you can",
    "q.m13#5.o2" to "Crouch and hug your knees",
    "q.m13#5.o3" to "Open all your zips",
    "q.m13#5.e" to "The handbook explicitly rejects several common practices: there is no evidence that small metal objects like ice axes or tent poles attract lightning, so don't waste time discarding them. What actually works is changing your position — from the tallest object around to an inconspicuous part of the landscape.",

    "q.m13#6.p" to "If you can hear thunder, the lightning is no farther than about:",
    "q.m13#6.o0" to "3 km",
    "q.m13#6.o1" to "10–16 km",
    "q.m13#6.o2" to "30 km",
    "q.m13#6.o3" to "50 km",
    "q.m13#6.e" to "Hearing thunder means the lightning is within 10–16 km, already inside the range where you must respond. Seeing lightning means the distance is no more than about 24 km — two numbers, two different response levels.",

    "q.m13#7.p" to "How do you estimate lightning distance from the flash-to-thunder delay?",
    "q.m13#7.o0" to "Seconds × 0.34 = distance in km",
    "q.m13#7.o1" to "Seconds ÷ 0.34 = distance in km",
    "q.m13#7.o2" to "Seconds × 3.4 = distance in km",
    "q.m13#7.o3" to "It cannot be estimated",
    "q.m13#7.e" to "Sound travels in air at about 0.34 km per second, so each second counted after the flash is roughly 0.34 km. The practical value: with no equipment at all, you can tell whether the storm is approaching or moving away.",

    "q.m13#8.p" to "Do small metal objects (ice axe, tent poles) attract lightning?",
    "q.m13#8.o0" to "Yes — throw them away immediately",
    "q.m13#8.o1" to "There is no evidence they do, so don't waste time discarding them",
    "q.m13#8.o2" to "Yes, but only at high altitude",
    "q.m13#8.o3" to "Only when wet",
    "q.m13#8.e" to "This is a classic high-altitude myth. The handbook is blunt: there is no supporting evidence, so don't spend precious time ditching gear. What you must do is leave the exposed position as fast as possible — that is the decisive variable.",

    "q.m13#9.p" to "What is the best place to shelter during a thunderstorm?",
    "q.m13#9.o0" to "A summit",
    "q.m13#9.o1" to "The middle of woodland away from the summit and ridge — but never leaning against a tree",
    "q.m13#9.o2" to "The middle of a grassy slope",
    "q.m13#9.o3" to "Inside a tent",
    "q.m13#9.e" to "The middle of woodland works because there are taller objects around you, yet you are not directly against a conductor. The counter-example is camping on an open ridge — the handbook calls this extremely foolish, because it means you have deliberately taken up residence at the highest point around.",

    "q.m13#10.p" to "Why should you not camp on a ridge while cumulus clouds are building?",
    "q.m13#10.o0" to "Because the wind is strong",
    "q.m13#10.o1" to "Because cumulus growing into cumulonimbus means lightning, and a ridge is the most exposed place of all",
    "q.m13#10.o2" to "Because visibility is poor",
    "q.m13#10.o3" to "Because the ground is uneven",
    "q.m13#10.e" to "The transition from cumulus to cumulonimbus often takes only one or two hours. Camping on a ridge puts you at the very front of the storm's path — with all your gear and tents, in a state where rapid evacuation is nearly impossible.",

    "q.m13#11.p" to "Someone has just been struck by lightning. What is the first priority?",
    "q.m13#11.o0" to "Check for external injuries first",
    "q.m13#11.o1" to "Check breathing and pulse immediately, start CPR if needed, and get medical help as soon as possible",
    "q.m13#11.o2" to "Change them into dry clothing first",
    "q.m13#11.o3" to "Move them to lower ground first",
    "q.m13#11.e" to "A strike can cause cardiac arrest and internal injury while leaving no visible sign. Checking breathing and pulse therefore comes before anything else — and even a conscious patient must be evacuated, because the current's effect on the heart can appear later.",

    "q.m13#12.p" to "[Multi] What does self-rescue capability usually include?",
    "q.m13#12.o0" to "Prusik self-ascent",
    "q.m13#12.o1" to "Self-arrest and self-protection",
    "q.m13#12.o2" to "Building an anchor without a partner's help",
    "q.m13#12.o3" to "Judging when to wait in place and when to extricate yourself",
    "q.m13#12.o4" to "Free-soloing without protection",
    "q.m13#12.e" to "The first three are skills, the fourth is judgement. Pay particular attention to \"judging when to wait in place and when to extricate yourself\": not every situation calls for self-extrication — if you are injured or the weather is deteriorating, staying put and waiting for rescue may be safer than moving rashly.",

    "q.m13#13.p" to "Why can't \"wait for my partner to rescue me\" serve as your main safety strategy?",
    "q.m13#13.o0" to "Because partners may be unwilling",
    "q.m13#13.o1" to "Because the partner may themselves be in danger, injured, or unable to move",
    "q.m13#13.o2" to "Because there isn't enough rescue equipment",
    "q.m13#13.o3" to "Because the rules don't allow it",
    "q.m13#13.e" to "The point of roping up is mutual protection, but you cannot assume your partner has reserve capacity. At altitude, one team member handling two people's problems often exceeds what is possible — so self-rescue is a requirement, and partner rescue is a bonus.",

    // ---------- m14 危险判断与决策（17 题） ----------
    "q.m14#0.p" to "What question is hazard judgement really trying to answer?",
    "q.m14#0.o0" to "Is there danger?",
    "q.m14#0.o1" to "Is this risk acceptable, and on what grounds?",
    "q.m14#0.o2" to "How big is the danger?",
    "q.m14#0.o3" to "Will my partners be scared?",
    "q.m14#0.e" to "\"Is there danger?\" is almost always \"yes\" — no mountain activity is risk-free. The real question is whether this risk is worth taking relative to the gain, and what we base that on. Which is exactly why the judgement has to be speakable and open to discussion.",

    "q.m14#1.p" to "What is the \"accident chain\"?",
    "q.m14#1.o0" to "The number of casualties in one accident",
    "q.m14#1.o1" to "A process in which several small errors stack up in sequence until an accident occurs",
    "q.m14#1.o2" to "The timeline of a rescue",
    "q.m14#1.o3" to "A chain of equipment failures",
    "q.m14#1.e" to "The most valuable thing about the concept is that it turns an accident from bad luck into an intervenable process. Make a different choice at any single link and the outcome changes.",

    "q.m14#2.p" to "What is the most effective way to break the accident chain?",
    "q.m14#2.o0" to "Make a more conservative choice at any one link",
    "q.m14#2.o1" to "Focus only on the final link",
    "q.m14#2.o2" to "Carry more equipment",
    "q.m14#2.o3" to "Improve the team's fitness",
    "q.m14#2.e" to "Any link will do — start earlier, turn around on time, don't cut protection to save time. This is also why margin beats remedy: margin acts early in the chain, while remedy usually happens at the last link.",

    "q.m14#3.p" to "[Multi] Which of the following are common decision biases?",
    "q.m14#3.o0" to "Sunk cost",
    "q.m14#3.o1" to "Team pressure",
    "q.m14#3.o2" to "Goal fixation",
    "q.m14#3.o3" to "Risk normalisation",
    "q.m14#3.o4" to "Belief in equipment brands",
    "q.m14#3.e" to "The four work in combination: we have already invested a lot (sunk cost), everyone else is still heading up (team pressure), we're nearly there (goal fixation), and last time it was fine (risk normalisation). When all four appear at once, judgement almost inevitably leans toward taking the risk.",

    "q.m14#4.p" to "How does sunk cost affect mountaineering decisions?",
    "q.m14#4.o0" to "It makes people more cautious",
    "q.m14#4.o1" to "Having already invested so much time and money, you are reluctant to admit you should quit",
    "q.m14#4.o2" to "It improves fitness",
    "q.m14#4.o3" to "It has no effect",
    "q.m14#4.e" to "What defines sunk cost is that it cannot be recovered — yet psychologically it becomes a reason to keep investing. On the mountain, combined with goal fixation, it turns a rational retreat into \"giving up\", and people have a natural resistance to giving up.",

    "q.m14#5.p" to "What is \"risk normalisation\"?",
    "q.m14#5.o0" to "Keeping danger within an acceptable range",
    "q.m14#5.o1" to "After passing a given condition safely several times, unconsciously reclassifying it as \"safe\"",
    "q.m14#5.o2" to "Learning risk assessment methods",
    "q.m14#5.o3" to "Using a standardised risk rating",
    "q.m14#5.e" to "Risk normalisation happens slowly, which is why the person involved barely notices it. The same climber may be extremely careful the first time on a steep slope and no longer roping up by the tenth time — the slope hasn't changed, the judgement has.",

    "q.m14#6.p" to "Why is majority rule problematic in high-risk environments?",
    "q.m14#6.o0" to "Because it is inefficient",
    "q.m14#6.o1" to "Because majority rule lets a minority's legitimate concern be suppressed",
    "q.m14#6.o2" to "Because voting isn't always fair",
    "q.m14#6.o3" to "Because team sizes differ",
    "q.m14#6.e" to "Danger signals are often noticed by only one or two people — someone saw a crack in the snow layer — and that observation is information held by a minority yet lethal if true. Deciding its fate by vote systematically ignores low-probability, high-consequence signals.",

    "q.m14#7.p" to "Why does \"the most conservative opinion prevails\"?",
    "q.m14#7.o0" to "Because conservative people are more experienced",
    "q.m14#7.o1" to "Because under uncertainty, the cost of being wrong on the conservative option is far lower than on the risky one",
    "q.m14#7.o2" to "Because the rules require it",
    "q.m14#7.o3" to "To keep everyone satisfied",
    "q.m14#7.e" to "This is a textbook case of asymmetric cost: being conservative may mean a wasted trip, being risky may mean death. When the costs are asymmetric, the decision should tilt toward the side whose cost is controllable — and that tilt has to be agreed before departure, otherwise it is very hard to execute on the ground.",

    "q.m14#8.p" to "[Match] Match each decision bias with its typical expression.",
    "q.m14#8.l0" to "Sunk cost",
    "q.m14#8.l1" to "Team pressure",
    "q.m14#8.l2" to "Goal fixation",
    "q.m14#8.l3" to "Risk normalisation",
    "q.m14#8.r0" to "We've come this far — turning back now would be a waste",
    "q.m14#8.r1" to "Everyone wants to keep going; I'd feel awkward saying we should quit",
    "q.m14#8.r2" to "It's just the last stretch",
    "q.m14#8.r3" to "It was fine last time",
    "q.m14#8.e" to "Interestingly, these four sentences show up constantly in accident reviews — and the people saying them are often experienced climbers. Which is precisely the point: these are not beginner problems, they are problems in how human cognition is built.",

    "q.m14#9.p" to "Why does \"more experienced\" not mean \"judges more accurately\"?",
    "q.m14#9.o0" to "Because experience slows you down",
    "q.m14#9.o1" to "Because experience gradually raises your tolerance for risk",
    "q.m14#9.o2" to "Because experience doesn't matter",
    "q.m14#9.o3" to "Because veterans are more stubborn",
    "q.m14#9.e" to "Experience brings familiarity, and familiarity dulls alertness. Experienced teams therefore need external constraints more, not less — fixed turnaround times, quantified weather thresholds — using rules to counter an intuition that has already blunted.",

    "q.m14#10.p" to "[Order] What is a sound process for making a retreat decision?",
    "q.m14#10.o0" to "Check the objective signals agreed before departure (time, weather, team condition)",
    "q.m14#10.o1" to "Verify whether actual conditions have triggered any of them",
    "q.m14#10.o2" to "Have the pre-designated decision-maker call the retreat",
    "q.m14#10.o3" to "Execute the retreat and notify the people back home",
    "q.m14#10.e" to "The value of the process is checking the standard first and the situation second — not the other way round. Reverse the order and the standard gets nibbled away by the mood on the ground until it becomes \"let's see a bit longer\".",

    "q.m14#11.p" to "Why designate in advance who has the authority to call a retreat?",
    "q.m14#11.o0" to "To make it easier to assign blame",
    "q.m14#11.o1" to "Because it is very hard for anyone to spontaneously act against the mood of the group",
    "q.m14#11.o2" to "To strengthen the leader's authority",
    "q.m14#11.o3" to "To document the process",
    "q.m14#11.e" to "Retreating means denying the whole team's expectation, which is very hard to initiate inside a group atmosphere. Turn \"calling the retreat\" into a duty granted in advance rather than an act of personal courage — only then does it actually happen.",

    "q.m14#12.p" to "When should you consider ending the trip?",
    "q.m14#12.o0" to "Never, as long as the summit is still possible",
    "q.m14#12.o1" to "When any pre-agreed objective signal has been triggered",
    "q.m14#12.o2" to "Only when a team member is injured",
    "q.m14#12.o3" to "Whenever the least fit person decides",
    "q.m14#12.e" to "Trigger means stop: that is the entire point of quantified criteria. It turns the decision from \"should we\" into \"has it been triggered\". The first needs argument and persuasion; the second only needs verifying facts — which is why it can actually be executed on the ground.",

    "q.m14#13.p" to "What is the most effective counter to goal fixation?",
    "q.m14#13.o0" to "Personal willpower",
    "q.m14#13.o1" to "Quantify the criteria before departure, so that \"relaxing them\" becomes an explicit act that must be justified to your partners",
    "q.m14#13.o2" to "Set no goal at all",
    "q.m14#13.o3" to "Carry more equipment",
    "q.m14#13.e" to "Psychological bias cannot be avoided by reminding yourself not to fall for it. The workable method is to make \"turn around when the time comes\" the default, so that whoever wants to continue must actively give reasons — reversing the burden of proof in one move.",

    "q.m14#14.p" to "Why does \"nobody objected\" not equal \"everyone agreed\"?",
    "q.m14#14.o0" to "Because they may not have heard",
    "q.m14#14.o1" to "Because silence may only mean reluctance to spoil the atmosphere, with real doubts left unspoken",
    "q.m14#14.o2" to "Because someone was asleep",
    "q.m14#14.o3" to "Because objections were ignored",
    "q.m14#14.e" to "This is why good teams deliberately manufacture dissent — the leader asks outright \"who thinks we shouldn't continue\", or goes round asking each person to state a position. Silence on the mountain does not mean agreement; it only means nothing was said.",

    "q.m14#15.p" to "Fill in the blank: when making decisions under uncertainty, the most ( ) opinion should be adopted first.",
    "q.m14#15.a0" to "conservative",
    "q.m14#15.e" to "\"Conservative first\" is a rule you can execute directly on the ground: you don't have to judge whose argument is stronger, only which option is more conservative. The price is possibly a wasted trip — a price worth paying.",

    "q.m14#16.p" to "Scenario: the weather deteriorates on a 7,000 m summit day",
    "q.m14#16.c" to "It is summit day at 7,000 m and you left at 3 a.m. At 8 a.m. you reach a point about two hours from the summit. The wind has clearly picked up, cloud is rushing in from the west and the temperature is dropping. One team member has begun coughing persistently and is visibly slowing.",
    "q.m14#16.e" to "The core of this scenario is not any single answer but the sequence: verify the facts, identify the danger signals, resist the psychological pull, then execute the retreat properly. The two steps most likely to fail are the first (skipped) and the third (hijacked by emotion).",
    "q.m14#16.s0.p" to "Step 1: what is the first judgement to make right now?",
    "q.m14#16.s0.o0" to "Confirm team condition and weather trend, and check them against the turnaround signals agreed before departure",
    "q.m14#16.s0.o1" to "Speed up and summit before the weather worsens",
    "q.m14#16.s0.o2" to "Wait in place for the weather to improve",
    "q.m14#16.s0.o3" to "Send the slow member down alone",
    "q.m14#16.s0.e" to "Every decision should start with verifying facts: how is the team, is the weather improving or worsening, has a preset signal been triggered. Skip this and let emotion make the decision for you.",
    "q.m14#16.s1.p" to "Step 2: a team member has a persistent cough. What is the most reasonable response?",
    "q.m14#16.s1.o0" to "It's just cold air irritating the airway — keep walking",
    "q.m14#16.s1.o1" to "At altitude this needs high suspicion of pulmonary oedema: stop ascending and descend as soon as possible",
    "q.m14#16.s1.o2" to "Give cough medicine and continue",
    "q.m14#16.s1.o3" to "Let them rest 10 minutes then continue",
    "q.m14#16.s1.e" to "At 7,000 m, a persistent cough at rest or with light exertion is a signal demanding high suspicion. At this altitude, the cost of \"watching it a while longer\" may far exceed the cost of descending immediately.",
    "q.m14#16.s2.p" to "Step 3: you are two hours from the summit and decide to turn around. What is the biggest psychological resistance?",
    "q.m14#16.s2.o0" to "Insufficient fitness",
    "q.m14#16.s2.o1" to "Sunk cost and goal fixation — \"we've come all this way\"",
    "q.m14#16.s2.o2" to "Equipment problems",
    "q.m14#16.s2.o3" to "Unfamiliarity with the route",
    "q.m14#16.s2.e" to "This is exactly why turnaround times exist: they move the decision to a moment when you are still rational. When \"it's just a little further\" shows up, what you need is not fresh judgement but a check against the rule agreed in advance.",
    "q.m14#16.s3.p" to "Step 4: how should the team be organised during the descent?",
    "q.m14#16.s3.o0" to "The fittest go ahead to prepare camp",
    "q.m14#16.s3.o1" to "Stay together as a team, let the strongest person lead and set the pace, and inform the people back home of the team's condition",
    "q.m14#16.s3.o2" to "Split up to descend faster",
    "q.m14#16.s3.o3" to "Let the weakest member walk slowly alone",
    "q.m14#16.s3.e" to "At altitude, once a team spreads out it loses mutual cover — and the descent is precisely the high-accident phase. Moving as a unit, having someone control the pace, and keeping the outside informed: all three are indispensable.",

    // ---------- m15 天气窗口与云图判读（29 题） ----------
    "q.m15#0.p" to "What is the core value of reading clouds?",
    "q.m15#0.o0" to "It makes mountaineering look more professional",
    "q.m15#0.o1" to "It gives you lead time on weather change",
    "q.m15#0.o2" to "It replaces the weather forecast",
    "q.m15#0.o3" to "It measures altitude",
    "q.m15#0.e" to "A forecast can tell you a day ahead, but mountain weather changes fast at small scales. Clouds are the forecast directly above your head — the lead time may be only one or two hours, and that hour or two is exactly the window in which you decide whether to turn around.",

    "q.m15#1.p" to "What does vertical development of cumulus indicate?",
    "q.m15#1.o0" to "Stable weather",
    "q.m15#1.o1" to "Strong convection, possibly developing into cumulonimbus",
    "q.m15#1.o2" to "Cooling is imminent",
    "q.m15#1.o3" to "Surface wind is weakening",
    "q.m15#1.e" to "Cumulus itself is not dangerous, but it is a signal that is growing. The key is not to note that it is cumulus but to watch it grow, tower and darken — that process is the atmosphere accumulating energy.",

    "q.m15#2.p" to "What does an anvil top on a cumulonimbus mean?",
    "q.m15#2.o0" to "It is still forming",
    "q.m15#2.o1" to "It has reached maturity; lightning, hail and heavy precipitation are all possible",
    "q.m15#2.o2" to "It is about to dissipate",
    "q.m15#2.o3" to "It only means strong wind aloft",
    "q.m15#2.e" to "The anvil is the top of the cloud sheared flat by high-level wind, which means the updraught has reached the tropopause and can rise no further — the signature of a thunderstorm at maturity. When you see an anvil, your reaction time is already short.",

    "q.m15#3.p" to "At what time of day does cumulus formation mostly occur?",
    "q.m15#3.o0" to "Early morning",
    "q.m15#3.o1" to "Mid-morning",
    "q.m15#3.o2" to "Afternoon",
    "q.m15#3.o3" to "Late at night",
    "q.m15#3.e" to "The cause is solar heating: the ground warms through the day and generates updraughts and convection. This is the physical mechanism behind \"start early, descend in time\" — not just a piece of folk wisdom.",

    "q.m15#4.p" to "What do lenticular clouds (mushroom- or disc-shaped) usually indicate?",
    "q.m15#4.o0" to "Calm weather",
    "q.m15#4.o1" to "Strong wind",
    "q.m15#4.o2" to "Rain is imminent",
    "q.m15#4.o3" to "Rising temperature",
    "q.m15#4.e" to "Lenticulars are standing-wave clouds formed as air crosses a ridge — their very existence shows high wind speeds aloft. On a mountain that means exposed ridges may get very strong gusts, and gusts are the direct cause of losing balance.",

    "q.m15#5.p" to "Cirrus (wispy high cloud) increasing markedly usually indicates:",
    "q.m15#5.o0" to "A weather system is approaching",
    "q.m15#5.o1" to "The cold spell is ending",
    "q.m15#5.o2" to "Wind is about to drop",
    "q.m15#5.o3" to "UV will weaken",
    "q.m15#5.e" to "Cirrus is often the leading edge of a weather system — the weather hasn't changed yet when it appears, but change is on the way. That is valuable lead time, especially for an itinerary that needs to get back early.",

    "q.m15#6.p" to "Stratus lowering, with the cloud base dropping clearly, has what most direct effect?",
    "q.m15#6.o0" to "Temperature rises",
    "q.m15#6.o1" to "Visibility deteriorates fast and terrain judgement becomes difficult",
    "q.m15#6.o2" to "Wind weakens",
    "q.m15#6.o3" to "Precipitation stops",
    "q.m15#6.e" to "Lowering stratus brings not rain but loss of sight — and losing sight is a risk in its own right: you may already be off route, may be nearing a cornice, or may miss the turn-off for the retreat.",

    "q.m15#7.p" to "[Multi] Which cloud changes signal deteriorating weather?",
    "q.m15#7.o0" to "Cloud cover increasing rapidly and the layer thickening",
    "q.m15#7.o1" to "The cloud base continuing to lower",
    "q.m15#7.o2" to "Clouds darkening with obvious vertical development",
    "q.m15#7.o3" to "An anvil top appearing",
    "q.m15#7.o4" to "Cloud cover starting to decrease and the sky clearing",
    "q.m15#7.e" to "These four are stages of one process: cover increases, base lowers, the body darkens and towers, an anvil appears. Recognising them in order turns \"the weather turned\" from a single moment into a process you can be warned about in advance.",

    "q.m15#8.p" to "Why do clouds develop more violently in mountains than on plains?",
    "q.m15#8.o0" to "Because it is higher and colder",
    "q.m15#8.o1" to "Because terrain forces the air upward, intensifying convection",
    "q.m15#8.o2" to "Because UV is stronger",
    "q.m15#8.o3" to "Because the air is thin",
    "q.m15#8.e" to "Wind hitting a mountain is forced upward as if pushed up a ramp — lifting produces cooling and condensation directly, so cloud forms faster and more locally than over a plain. This is why mountain weather can change completely in a very short time.",

    "q.m15#9.p" to "How do you tell whether a cloud is developing rather than dissipating?",
    "q.m15#9.o0" to "By its colour",
    "q.m15#9.o1" to "By watching continuously whether its volume, height and edge outline are growing and hardening",
    "q.m15#9.o2" to "By the temperature",
    "q.m15#9.o3" to "By snow depth",
    "q.m15#9.e" to "The key is continuous observation — a single look gives you a state, two looks give you a trend. A developing cloud grows in volume, its top rises and its edges sharpen; a dissipating one does the reverse. So glancing up at fixed intervals costs almost nothing and is worth a lot.",

    "q.m15#10.p" to "[Match] Match each cloud type with its weather meaning.",
    "q.m15#10.l0" to "Cumulonimbus (anvil top)",
    "q.m15#10.l1" to "Lenticular cloud",
    "q.m15#10.l2" to "Cirrus",
    "q.m15#10.l3" to "Low stratus",
    "q.m15#10.r0" to "Thunderstorm, hail and heavy precipitation",
    "q.m15#10.r1" to "Strong wind aloft, violent gusts on ridges",
    "q.m15#10.r2" to "A weather system is approaching",
    "q.m15#10.r3" to "Visibility drops, terrain judgement becomes difficult",
    "q.m15#10.e" to "These four cover the four kinds of weather information you meet most often on a mountain. One caveat: reading clouds needs picture practice, and this app currently only has text questions — image-based cloud identification will be added once the image pipeline is in place.",

    "q.m15#11.p" to "Why must cloud reading be combined with the pressure trend?",
    "q.m15#11.o0" to "For completeness of data",
    "q.m15#11.o1" to "Because clouds show the present state, while the pressure trend shows the direction of change",
    "q.m15#11.o2" to "Because a barometer is more accurate",
    "q.m15#11.o3" to "To calculate altitude",
    "q.m15#11.e" to "They are different dimensions: clouds tell you what is there now, pressure tells you which way it is heading. Clouds alone make it easy to misread \"getting worse\" as \"just overcast for now\" — add the trend and the picture is complete.",

    "q.m15#12.p" to "What mainly causes whiteout conditions?",
    "q.m15#12.o0" to "Excessive snowfall",
    "q.m15#12.o1" to "Cloud, fog and snow surface being similar in colour, so the boundary between ground and sky disappears",
    "q.m15#12.o2" to "Extremely low temperature",
    "q.m15#12.o3" to "Excessive UV",
    "q.m15#12.e" to "A whiteout is not heavy snow, it is absence of contrast. When snow and cloud are close in brightness the horizon vanishes and your perception of distance and slope fails completely — which explains why it is far more dangerous than ordinary snowfall.",

    "q.m15#13.p" to "Why is a forecast like \"isolated showers\" of limited use in the mountains?",
    "q.m15#13.o0" to "Because forecasts are inaccurate",
    "q.m15#13.o1" to "Because the scale of weather variation in mountains is far smaller than the forecast grid, so conditions on the ground may be completely different",
    "q.m15#13.o2" to "Because climbers don't read forecasts",
    "q.m15#13.o3" to "Because precipitation doesn't matter",
    "q.m15#13.e" to "The forecast grid may be tens of kilometres across, while the two sides of one ridge can have completely different weather. A forecast gives you background risk; on-site judgement decides whether you can move today. Neither substitutes for the other.",

    "q.m15#14.p" to "The forecast says \"sunny\" but you see cumulus growing vertically fast. Which do you trust?",
    "q.m15#14.o0" to "The forecast — continue as planned",
    "q.m15#14.o1" to "Your own observation — decide on the assumption it may deteriorate",
    "q.m15#14.o2" to "Average the two",
    "q.m15#14.o3" to "Keep watching for another hour",
    "q.m15#14.e" to "A forecast is coarse in both lead time and scale, while observation is here and now. When they conflict, on-site evidence wins — which is the basic stance of the whole weather-judgement system: the forecast sets the background, the ground sets the action.",

    "q.m15#15.p" to "Fill in the blank: after seeing lightning, each second counted corresponds to about ( ) kilometres.",
    "q.m15#15.a0" to "0.34",
    "q.m15#15.a1" to ".34",
    "q.m15#15.a2" to "zero point three four",
    "q.m15#15.e" to "0.34 km per second is the speed of sound in air. This conversion turns counting seconds into a usable tool — with no equipment at all, you can tell whether the storm is approaching or moving away.",

    "q.m15#16.p" to "[Multi] In which situations should you seriously consider descending immediately?",
    "q.m15#16.o0" to "Cumulus has developed into a cumulonimbus with an anvil top",
    "q.m15#16.o1" to "A \"whumpf\" collapse sound from the snowpack",
    "q.m15#16.o2" to "Visibility dropping fast and you can no longer fix your position",
    "q.m15#16.o3" to "A team member showing progressively worsening altitude symptoms",
    "q.m15#16.o4" to "A team member says they are a bit tired and wants ten minutes' rest",
    "q.m15#16.e" to "These four come from four dimensions — weather, snowpack, navigation and physiology — and what they share is that they are all progressive, which means the cost now is far lower than the cost ten minutes from now. The earlier you decide to descend, the cheaper it is.",

    "q.m15#17.p" to "Click the curve on the chart that represents the freezing level.",
    "q.m15#17.c" to "This forecast shows the weather at different altitudes on the same mountain in stacked rows. The purple curve in the legend marks the freezing level — the altitude of the rain/snow line.",
    "q.m15#17.e" to "The freezing-level curve is one of the most useful pieces of information in this forecast: it marks the altitude where precipitation turns from rain to snow. A rising curve means warmer, moister air is arriving and precipitation will shift from snow to rain; a falling curve means cold air is in place and higher ground will turn to snow. For judging whether you will meet snowfall at your altitude, it beats reading temperature numbers.",

    "q.m15#18.p" to "This is the forecast for the same mountain as the climbing season ended early. What is the total snowfall, in centimetres, across the three periods on Fri 25 (AM / PM / night)? Enter the sum.",
    "q.m15#18.a0" to "280",
    "q.m15#18.e" to "58 + 88 + 134 = 280 cm. Nearly 2.8 m of snow in a single day means the route is completely buried, avalanche danger rises sharply, and camps risk being crushed. At that magnitude the question is no longer whether you can summit but whether you can evacuate safely — which is the typical way a cyclone ends a climbing season early.",

    "q.m15#19.p" to "Scenario: reading a high-altitude weather forecast",
    "q.m15#19.c" to "A guide puts two Manaslu forecasts in front of you — one from a normal climbing window, one from the record of a season that ended early. Understanding them matters more than memorising any number.",
    "q.m15#19.e" to "Weather judgement never really lands on \"what will the weather be tomorrow\" but on \"can we move in this window\". The same interface, one saying continue and one saying stop — the difference is not in reading the chart but in knowing under what conditions you must stop.",
    "q.m15#19.s0.p" to "Step 1: in the normal-window forecast, what do the pink blocks in the summit-altitude row (8,163 m) represent?",
    "q.m15#19.s0.o0" to "Expected snowfall for that period",
    "q.m15#19.s0.o1" to "Rainfall for that period",
    "q.m15#19.s0.o2" to "Feels-like temperature for that period",
    "q.m15#19.s0.o3" to "Wind speed for that period",
    "q.m15#19.s0.e" to "Pink is snow and blue is rain — the forecast marks precipitation type separately at each altitude precisely because its core question is whether it will snow or rain at your altitude. The top row's blocks are small and sparse, so the summit sees occasional light snow of no great magnitude.",
    "q.m15#19.s1.p" to "Step 2: compared with the end-of-season forecast, what is the most striking change?",
    "q.m15#19.s1.o0" to "Only the temperature drops",
    "q.m15#19.s1.o1" to "Snowfall and wind speed both increase sharply, and precipitation covers every altitude band",
    "q.m15#19.s1.o2" to "Rain replaces snow",
    "q.m15#19.s1.o3" to "The freezing level rises a lot",
    "q.m15#19.s1.e" to "Snowfall goes from scattered 1–4 cm to 280 cm in a day, wind from 25–30 km/h to 55–60 km/h, and the precipitation band runs through every level from 8,163 m down to 1,500 m. All three at once is the signature of a weather system passing straight over you.",
    "q.m15#19.s2.p" to "Step 3: if your team were inside such a forecast window, what is the correct decision?",
    "q.m15#19.s2.o0" to "Speed up the summit push before the weather fully deteriorates",
    "q.m15#19.s2.o1" to "Stop the summit attempt immediately, descend per plan and prepare to evacuate",
    "q.m15#19.s2.o2" to "Wait at high camp for the weather to improve",
    "q.m15#19.s2.o3" to "Split into two groups, one pushing for the summit and one staying behind",
    "q.m15#19.s2.e" to "When a forecast shows a system passing straight over rather than a brief fluctuation, \"waiting for it to pass\" usually means several more days exposed at altitude, which neither supplies nor tents can sustain. That is why so many seasons end not with \"we finished\" but with \"we had to get out\" — and the information needed to make that call is exactly what these two charts provide.",

    "q.m15#20.p" to "Scenario: reading an hourly forecast",
    "q.m15#20.c" to "This is an hourly forecast for one day on Gongga Shan (7,556 m). Its information density is far higher than a 16-day overview, but it is also easier to read the wrong row — the key is knowing what each row actually says.",
    "q.m15#20.e" to "An hourly forecast answers what an overview cannot: which specific period is actionable. The freezing level sets precipitation type, the feels-like temperature sets whether a person can endure, and wind speed and sunshine set how wide the window is. Only read together do they yield a decision you can execute.",
    "q.m15#20.s0.p" to "Step 1: the Freeze row shows the freezing level between 4,895 and 5,304 m, while Gongga's summit is 7,556 m. What does that combination mean?",
    "q.m15#20.s0.o0" to "All precipitation on the mountain falls as snow",
    "q.m15#20.s0.o1" to "There will be rain at the summit",
    "q.m15#20.s0.o2" to "It will also snow below the freezing level",
    "q.m15#20.s0.o3" to "Precipitation type cannot be judged from this",
    "q.m15#20.s0.e" to "The freezing level is the rain/snow line. It sits steadily at 4,900–5,300 m while every climbing route lies above that. In other words the whole route is above the freezing level, so any precipitation arrives as snow. One number answers \"what form of precipitation will I meet\" — which is why the freezing level is more useful than a temperature figure.",
    "q.m15#20.s1.p" to "Step 2: the Feels °C row shows −18 to −21, while Max / Min °C is only −10 to −11. What mainly explains the gap?",
    "q.m15#20.s1.o0" to "Forecast error",
    "q.m15#20.s1.o1" to "Wind chill — the stronger the wind, the lower the felt temperature",
    "q.m15#20.s1.o2" to "Temperature difference caused by altitude",
    "q.m15#20.s1.o3" to "The effect of humidity change",
    "q.m15#20.s1.e" to "Wind speed in the same period is 20–30 km/h. Wind over bare skin accelerates heat loss, so the felt temperature sits nearly 10 °C below the measured air temperature. At altitude, whether you can stay out is decided by felt temperature, not air temperature. The same −10 °C is a completely different proposition with and without wind.",
    "q.m15#20.s2.p" to "Step 3: given this forecast (wind 20–30 km/h, scattered snowfall 2/1/1 cm, feels-like around −20 °C, daylight 6:56–19:15), what is your judgement of the window?",
    "q.m15#20.s2.o0" to "Conditions are severe — abandon all movement",
    "q.m15#20.s2.o1" to "It is a comparatively workable window; the main challenge is cold and wind chill rather than precipitation",
    "q.m15#20.s2.o2" to "Too much precipitation — there is avalanche risk",
    "q.m15#20.s2.o3" to "Not enough data to judge",
    "q.m15#20.s2.e" to "Wind of 20–30 km/h is still within the workable range, and snowfall is only a few centimetres. The real pressure comes from a felt temperature around −20 °C, so frostbite and hypothermia are what you guard against. The logic for this kind of window: precipitation and wind are fine, temperature and duration are the problem. So shorten exposure, beef up extremity insulation, and bring the turnaround time forward.",

    "q.m15#21.p" to "In the same Gongga forecast the measured air temperature is about −11 °C while the feels-like low is −21 °C. What is the difference in degrees Celsius?",
    "q.m15#21.a0" to "10",
    "q.m15#21.e" to "10 °C: −11 − (−21) = 10. The gap is itself decision information — dress for the felt temperature, not the air temperature. It also explains how people get frostbite at −10 °C: they dressed for the number on the chart.",

    "q.m15#22.p" to "This forecast shows wind speed as green circles. What does that most likely mean?",
    "q.m15#22.o0" to "Wind speed in that period is within the range suitable for climbing",
    "q.m15#22.o1" to "Wind speed in that period has reached a dangerous level",
    "q.m15#22.o2" to "There is rain in that period",
    "q.m15#22.o3" to "Wind data is missing for that period",
    "q.m15#22.e" to "Professional mountain weather services usually colour-code wind speed by its effect on movement. 20–30 km/h shown green means it falls in the \"can move\" band; above that the colour shifts to yellow or red.\nBut the colour is the provider's suggestion, not your criterion. Different routes and different teams tolerate the same wind differently. Reading the number matters more than reading the colour.",

    "q.m15#23.p" to "This professional interface shows temperatures for 8000 / 6000 / 4000 / 2000 m in four parallel rows. What is the main value of that design?",
    "q.m15#23.o0" to "You can read the forecast for your own altitude directly, without extrapolating from lowland data",
    "q.m15#23.o1" to "It makes the page look richer",
    "q.m15#23.o2" to "It shows the four rows are unrelated",
    "q.m15#23.o3" to "Only to make printing on paper easier",
    "q.m15#23.e" to "An ordinary forecast gives data for one location, usually the nearest city or airport. You have to extrapolate up the mountain using a lapse rate — a step that is easy to get wrong and throws away terrain detail.\nA professional mountain service does the opposite: it slices the mountain by altitude first, then forecasts each slice. You only have to find the row for the altitude you will be at tomorrow and read it. That is also a simple test of whether a weather service is adequate: does it slice by altitude.",

    "q.m15#24.p" to "In the chart, the \"Cloud base (m)\" row shows a dash (—) for most periods. What is the correct reading?",
    "q.m15#24.o0" to "Cloud base is zero in that period, i.e. cloud is on the ground",
    "q.m15#24.o1" to "No cloud-base data is provided for that period; it must not be treated as \"cloud base = 0\"",
    "q.m15#24.o2" to "It means there is no cloud at all in that period",
    "q.m15#24.o3" to "It means cloud base is above the summit",
    "q.m15#24.e" to "In a weather table, \"blank\" and \"zero\" are two entirely different things. A blank means no data for that item in that period — it may not be covered, or no meaningful estimate can be given. It does not mean the value is zero.\nTreating a blank as zero leads to conclusions like \"cloud on the ground, terrible visibility\" that have nothing to do with the facts. With any weather table, separate the two first. It is the easiest mistake to make in reading a forecast, and the least often pointed out.",

    "q.m15#25.p" to "In the wind row of this interface, the numbers come with arrow symbols. What do the arrows most likely show?",
    "q.m15#25.o0" to "The trend in wind speed",
    "q.m15#25.o1" to "Wind direction",
    "q.m15#25.o2" to "Probability of precipitation",
    "q.m15#25.o3" to "Temperature rising or falling",
    "q.m15#25.e" to "Speed and direction must be read together at altitude. The same 30 km/h feels completely different on the windward and leeward sides, and affects the snowpack differently too: wind transports snow onto lee slopes and piles it into slabs. That is one of the most important pieces of information in judging avalanche danger.\nReading only the number and not the direction throws away half the information. Professional interfaces put the arrow beside the number precisely because the two cannot be read apart.",

    "q.m15#26.p" to "On this 16-day forecast chart, red markers (Snow) cluster around the 6,000 m band while blue markers (Rain) appear below 5,000 m. What does that indicate?",
    "q.m15#26.o0" to "The rain/snow line is roughly between 5,500 and 6,000 m",
    "q.m15#26.o1" to "Only snow falls on the mountain, never rain",
    "q.m15#26.o2" to "Rain continues all the way to the summit",
    "q.m15#26.o3" to "It cannot be judged from this chart",
    "q.m15#26.e" to "This chart does not tell you what falls where at a given hour; it answers directly which altitude band precipitation lands in. For a climber that is exactly the information that matters.\nRed in the 6,000 m band and blue only below 5,000 m puts the rain/snow line roughly between 5,500 and 6,000 m. Combined with the purple freezing-level curve in the legend (falling from about 6,000 m to about 4,800 m), you can also see the line will keep descending through the forecast period: bands that currently get rain will gradually turn to snow.\nThe same amount of precipitation has a completely different effect on a trip depending on whether it falls as rain or snow.",

    "q.m15#27.p" to "In the hourly forecast on the same chart, a lightning icon appears at 5 p.m. What does that signal mean at altitude?",
    "q.m15#27.o0" to "It's only an icon — no special handling needed",
    "q.m15#27.o1" to "Thunderstorm risk: schedule movement for the morning and leave ridges and exposed terrain in the afternoon",
    "q.m15#27.o2" to "Heavy rain is coming — just bring a rain jacket",
    "q.m15#27.o3" to "Wind speed will increase to a dangerous level",
    "q.m15#27.e" to "Afternoon thunderstorms are common at altitude and genuinely dangerous. Terrain lifting makes cumulus grow fast in the afternoon. So \"start early\" is not only about harder snow — it is also about leaving exposed terrain before storms form.\nKey points in a thunderstorm: keep away from summits, ridges, isolated trees and water; do not lie flat on the ground; spread the team about 50 m apart so one strike cannot injure several people. Lightning distance can be estimated in kilometres as seconds between flash and thunder × 0.34.",

    "q.m15#28.p" to "Regarding whether a terrain data source has a summit marker, what is the right trade-off?",
    "q.m15#28.o0" to "A marker always means greater accuracy; trust only maps that have one",
    "q.m15#28.o1" to "Markers are handy for quick positioning and communication, but precise terrain judgement still requires contours",
    "q.m15#28.o2" to "A map without markers is useless",
    "q.m15#28.o3" to "Markers only interfere with reading; ignore them",
    "q.m15#28.e" to "On this Google map of Muztagh Ata the summit is marked directly with a red pin. That is very useful for orientation and communication: you know instantly where the objective is and can tell a partner exactly which point you mean.\nBut a marker does not answer how steep this slope is or where a camp can go. Precise terrain judgement still depends on contours, and the marker plays no part in it.\nThe practical approach: use the marker to locate quickly, then use high-resolution contours (the SRTM version, say) to read slope angle and terrain detail. Each does its own job.",

    // ---------- m16 进阶雪崩判断与地形判读（25 题） ----------
    "q.m16#0.p" to "Which three scales must advanced avalanche judgement combine?",
    "q.m16#0.o0" to "Temperature, wind speed, precipitation",
    "q.m16#0.o1" to "Regional forecast, terrain, snowpack",
    "q.m16#0.o2" to "Altitude, slope angle, sunshine",
    "q.m16#0.o3" to "Team size, equipment, time",
    "q.m16#0.e" to "The three answer three different questions: the forecast says how risky today is overall, the terrain says whether this slope can hold snow and slide, the snowpack says whether it is stable right now. With only the forecast you are judging the slope underfoot by a regional average.",

    "q.m16#1.p" to "At which avalanche danger level do most accidents occur?",
    "q.m16#1.o0" to "1 (Low)",
    "q.m16#1.o1" to "3 (Considerable)",
    "q.m16#1.o2" to "5 (Extreme)",
    "q.m16#1.o3" to "No difference",
    "q.m16#1.e" to "At level 5 people stay away, so accidents are actually fewer; at level 3 the terrain \"looks walkable\", so large numbers of people enter avalanche terrain. The most dangerous condition is never the extreme one, but the moderate one that gets underestimated.",

    "q.m16#2.p" to "In which slope range do most avalanches occur?",
    "q.m16#2.o0" to "10°–25°",
    "q.m16#2.o1" to "34°–45°",
    "q.m16#2.o2" to "55°–70°",
    "q.m16#2.o3" to "There is no pattern",
    "q.m16#2.e" to "About 96% of avalanches occur between 30° and 50°, with most concentrated between 34° and 45°. That is exactly the range climbing routes pass through most often — steep enough to slide, gentle enough to hold snow.",

    "q.m16#3.p" to "[Multi] Which practices are correct when crossing avalanche terrain?",
    "q.m16#3.o0" to "Keep spacing and cross one person at a time",
    "q.m16#3.o1" to "Post a spotter in a safe position",
    "q.m16#3.o2" to "Plan the escape route in advance",
    "q.m16#3.o3" to "Send the whole team across quickly together to shorten exposure",
    "q.m16#3.e" to "The first two confine the risk to one person; the third guarantees a way out if something happens. \"Everyone across at once\" does the opposite — it turns the risk from possibly burying one person into possibly burying the whole team, which is exactly why it is the worst choice.",

    "q.m16#4.p" to "Where should the spotter stand?",
    "q.m16#4.o0" to "On the slope being crossed",
    "q.m16#4.o1" to "Somewhere they can see the person crossing clearly and are themselves safe",
    "q.m16#4.o2" to "At the very top of the slope",
    "q.m16#4.o3" to "At the bottom of the valley",
    "q.m16#4.e" to "A spotter has two jobs: keep the person in sight (so as to know where they are buried) and act immediately if something happens. Standing on the slope or in the valley floor makes them the second victim — the spotter's own safety is a precondition for doing the job.",

    "q.m16#5.p" to "What is the purpose of digging a snow pit?",
    "q.m16#5.o0" to "To rest",
    "q.m16#5.o1" to "To look directly at layer structure, weak-layer position and hardness differences",
    "q.m16#5.o2" to "To measure temperature",
    "q.m16#5.o3" to "To take photographs",
    "q.m16#5.e" to "An avalanche needs a weak layer plus a slab above it, and that structure only becomes visible when you cut into it. A pit turns an invisible internal structure into visible evidence — the key step from inferring risk to observing it.",

    "q.m16#6.p" to "Why is \"follow the tracks of those ahead\" dangerous?",
    "q.m16#6.o0" to "Because the tracks are unclear",
    "q.m16#6.o1" to "Because the tracks may be hours old, and the snowpack has long since changed",
    "q.m16#6.o2" to "Because you may take the wrong route",
    "q.m16#6.o3" to "Because tracks hinder walking",
    "q.m16#6.e" to "Snowpack conditions keep changing with temperature, wind and snowfall — a few hours is enough to go from \"barely stable\" to \"ready to trigger\". Tracks prove only that someone got across then; they say nothing about whether it is safe now.",

    "q.m16#7.p" to "How does wind loading affect avalanche danger?",
    "q.m16#7.o0" to "Wind flattens the snow and lowers the risk",
    "q.m16#7.o1" to "Wind transports snow onto lee slopes, building extra slabs and weak layers that sharply raise the risk",
    "q.m16#7.o2" to "Wind has nothing to do with avalanches",
    "q.m16#7.o3" to "Wind only affects visibility",
    "q.m16#7.e" to "Wind is the most underestimated avalanche maker: in a short time it can move a lot of snow onto lee slopes, building thick slabs and creating weak layers inside them. So even with no snowfall, new avalanche danger can appear after a strong wind.",

    "q.m16#8.p" to "What is the main danger of a cornice?",
    "q.m16#8.o0" to "It obstructs the view",
    "q.m16#8.o1" to "It may collapse at any moment on its own, and its collapse may trigger an avalanche on the slope below",
    "q.m16#8.o2" to "Its colour differs from the snow surface",
    "q.m16#8.o3" to "It blocks the route",
    "q.m16#8.e" to "A cornice is dangerous twice over: stand on it and you may go down with it, or pass beneath it and it may come down on you with a great deal of snow. The usual approach is to detour on the side away from the cornice edge, and never rest on one.",

    "q.m16#9.p" to "[Order] What is the complete procedure for crossing avalanche terrain?",
    "q.m16#9.o0" to "Check the day's avalanche forecast before setting out and mark the slopes to avoid",
    "q.m16#9.o1" to "Observe field signals on the approach (cracks, collapse sounds, wind-loaded surfaces)",
    "q.m16#9.o2" to "Assign the spotter, the crossing order and the escape route",
    "q.m16#9.o3" to "Cross one at a time, keeping spacing, and regroup at a safe point",
    "q.m16#9.e" to "The first three steps all happen before you enter — that is where avalanche safety work actually lives. Once you step onto the slope there are very few choices left, and most accidents trace back to skipping those first two steps.",

    "q.m16#10.p" to "Why must an avalanche rescue be carried out immediately by partners?",
    "q.m16#10.o0" to "Because professional rescue is expensive",
    "q.m16#10.o1" to "Because a buried person's survival window is only about fifteen minutes",
    "q.m16#10.o2" to "Because professional teams won't come up",
    "q.m16#10.o3" to "Because partners know the terrain better",
    "q.m16#10.e" to "A fifteen-minute survival window means the only people who can save you are those beside you. That is also why the avalanche trio must be carried and must be practised — carrying gear you can't use is the same as carrying nothing.",

    "q.m16#11.p" to "[Match] Match each avalanche danger level with its meaning.",
    "q.m16#11.l0" to "Level 1",
    "q.m16#11.l1" to "Level 3",
    "q.m16#11.l2" to "Level 4",
    "q.m16#11.l3" to "Level 5",
    "q.m16#11.r0" to "Low: both natural and human triggering unlikely",
    "q.m16#11.r1" to "Considerable: human triggering possible, and the most easily underestimated",
    "q.m16#11.r2" to "High: natural triggering likely; avoid avalanche terrain",
    "q.m16#11.r3" to "Extreme: widespread natural avalanches very likely",
    "q.m16#11.e" to "Behind each number is a combination of trigger likelihood and consequence size. The beginner's classic mistake is treating level 3 as \"fine\" — yet it is precisely the level where accidents concentrate.",

    "q.m16#12.p" to "What are the function and the limits of an avalanche airbag?",
    "q.m16#12.o0" to "It fully prevents burial; there are no limits",
    "q.m16#12.o1" to "It improves the chance of staying nearer the surface; but it cannot replace beacon, probe and shovel, nor prevent trauma",
    "q.m16#12.o2" to "It is only for ski resorts",
    "q.m16#12.o3" to "It calls for help automatically",
    "q.m16#12.e" to "The principle is bigger volume, more likely to stay near the surface — it raises survival odds but does not guarantee them. And a substantial share of avalanche deaths come from trauma rather than suffocation, which is why an airbag can never be your only reliance.",

    "q.m16#13.p" to "Why are slopes that \"don't look that steep\" often the most dangerous?",
    "q.m16#13.o0" to "Because the snow is deeper",
    "q.m16#13.o1" to "Because 34°–45° is where avalanches concentrate, and the human eye underestimates slope angle",
    "q.m16#13.o2" to "Because few people go there",
    "q.m16#13.o3" to "Because the angle changes quickly",
    "q.m16#13.e" to "Without a reference, people estimate slope angle with large error, often reading 35° as 25°. And 30°–35° is exactly the band that \"looks walkable but can slide\". A slope meter and a contour map are the cure for that bias.",

    "q.m16#14.p" to "[Multi] What must a team complete before entering avalanche terrain?",
    "q.m16#14.o0" to "Confirm everyone can use beacon, probe and shovel",
    "q.m16#14.o1" to "Agree the crossing order and the spotter",
    "q.m16#14.o2" to "Agree a meeting point and escape route",
    "q.m16#14.o3" to "Check that beacons are transmitting",
    "q.m16#14.o4" to "Stamp hard repeatedly to test snowpack stability",
    "q.m16#14.e" to "All four are final checks before entry and take only minutes. They matter because once you are on the slope your only remaining option is hoping it doesn't happen.",

    "q.m16#15.p" to "The snowpack makes a \"whumpf\" collapse sound. What is the correct response?",
    "q.m16#15.o0" to "Keep going — it's just the snow settling",
    "q.m16#15.o1" to "Stop immediately and reassess; a weak layer has begun to fail",
    "q.m16#15.o2" to "Move across faster",
    "q.m16#15.o3" to "Rest in place for ten minutes",
    "q.m16#15.e" to "A whumpf is direct evidence that a weak layer is collapsing — it means a very light load just triggered local failure. Continuing is effectively asking whether a little more will bring the whole thing down.",

    "q.m16#16.p" to "Fill in the blank: about 96% of avalanches occur on slopes of 30°–50°, with most concentrated between 34° and ( )°.",
    "q.m16#16.a0" to "45",
    "q.m16#16.a1" to "forty-five",
    "q.m16#16.e" to "34°–45°. The range is worth remembering because it is both the avalanche hotspot and the gradient climbing routes most often cross — it is the overlap of those two facts that makes avalanches one of the dominant objective hazards in alpine climbing.",

    "q.m16#17.p" to "Scenario: crossing a piece of avalanche terrain",
    "q.m16#17.c" to "The route must cross a snow slope of about 35°, roughly 200 m long. Today's avalanche forecast is Considerable (level 3), with 30 cm of new snow recently, wind from the northwest, and the slope facing southeast.",
    "q.m16#17.e" to "This scenario tests the full avalanche workflow: read terrain and snowpack, complete preparations before entry, then use formation to control the consequences. No single step is hard; what is hard is executing all of them in front of a slope that looks walkable.",
    "q.m16#17.s0.p" to "Step 1: what deserves the most caution on this slope?",
    "q.m16#17.s0.o0" to "Rockfall",
    "q.m16#17.s0.o1" to "Wind-loaded slabs and the slope angle itself",
    "q.m16#17.s0.o2" to "High temperature",
    "q.m16#17.s0.o3" to "Ground vegetation",
    "q.m16#17.s0.e" to "35° sits squarely in the 34°–45° hotspot; northwest wind transports snow onto the lee slope (here the southeast face), building extra slab. Two factors stacking is the classic \"looks walkable, can slide\" combination.",
    "q.m16#17.s1.p" to "Step 2: on approaching the slope, what should be done first?",
    "q.m16#17.s1.o0" to "Start crossing straight away",
    "q.m16#17.s1.o1" to "Observe field signals first, then fix the spotter, crossing order and escape route",
    "q.m16#17.s1.o2" to "Stamp hard on the slope to test it",
    "q.m16#17.s1.o3" to "Send the whole team across quickly",
    "q.m16#17.s1.e" to "All preparation belongs before entry. Stamping hard does not verify stability — it may directly trigger a snowpack that is already near its critical point.",
    "q.m16#17.s2.p" to "Step 3: how should the team be arranged while crossing?",
    "q.m16#17.s2.o0" to "One at a time, with the others waiting at a safe point",
    "q.m16#17.s2.o1" to "All holding hands together",
    "q.m16#17.s2.o2" to "Two abreast so as to watch each other",
    "q.m16#17.s2.o3" to "Single file, close together",
    "q.m16#17.s2.e" to "One at a time confines the risk to one person and lets the spotter concentrate on watching one person. Exposing the whole team at once magnifies the consequence from possibly burying one to possibly burying everyone.",

    "q.m16#18.p" to "Click the approximate area of the Manaslu summit on the map.",
    "q.m16#18.c" to "This is a contour map of Manaslu generated from NASA SRTM elevation data, with a 50 m contour interval; the labels give the elevation of each contour.",
    "q.m16#18.e" to "A summit is unmistakable on a contour map: closed contours tighten inward ring after ring while the labels step upward (7600 → 7750 → 7900 → 7950 …). Find the point enclosed by rings of small closed curves and you have the highest ground.\nConversely, where contours fan outward and labels keep falling, that is downhill — which incidentally tells you which side the climbing route follows.",

    "q.m16#19.p" to "On the same map the contours on the northeast-to-east side are extremely dense. What does that indicate?",
    "q.m16#19.o0" to "That side is very steep and is a hotspot for serac fall and rockfall",
    "q.m16#19.o1" to "That side is gentle and good for camping",
    "q.m16#19.o2" to "That side is lower and therefore less risky",
    "q.m16#19.o3" to "Dense contours mean the terrain there is flat",
    "q.m16#19.e" to "The denser the contours, the greater the elevation change over the same horizontal distance — that is, the steeper the slope. On this map the northeast side drops from 7,950 m to 5,750 m with dozens of contours squeezed into a short horizontal distance: a classic steep face.\nWhen planning a route this reading skill bears directly on two things: whether you pass through serac-fall and rockfall zones, and whether usable retreat terrain exists if something goes wrong. The gentler, sparsely contoured areas are where a camp is more likely to go.",

    "q.m16#20.p" to "Scenario: comparing two terrain data sources",
    "q.m16#20.c" to "A guide gives you two terrain maps of the same mountain: one from Google Maps, one generated from NASA SRTM elevation data. Neither is wrong, but they are not equally capable of answering your questions.",
    "q.m16#20.e" to "The core difference between terrain datasets is not accuracy but contour interval, because the interval sets how fine a slope change you can see. Intuition has value — it builds an overall impression fast — but deciding whether a given stretch is steep or passable still comes back to contour density, which can be quantified and compared.",
    "q.m16#20.s0.p" to "Step 1: on this Google map the contour labels read 6200, 6400, 6600, 6800… What is the contour interval?",
    "q.m16#20.s0.o0" to "50 m",
    "q.m16#20.s0.o1" to "100 m",
    "q.m16#20.s0.o2" to "200 m",
    "q.m16#20.s0.o3" to "500 m",
    "q.m16#20.s0.e" to "Adjacent labels differ by 200 m, so this contour system rises 200 m between lines. A 200 m interval is fine for overall shape, but terrain detail between the lines — a 40 m rock step, say — simply disappears from the map.",
    "q.m16#20.s1.p" to "Step 2: the SRTM map uses a 50 m interval. Compared with the 200 m Google map, what is its most substantive advantage?",
    "q.m16#20.s1.o0" to "It looks nicer",
    "q.m16#20.s1.o1" to "Lines are denser over the same horizontal distance, resolving slope change four times as finely",
    "q.m16#20.s1.o2" to "The colours are more vivid",
    "q.m16#20.s1.o3" to "The labels are in bigger type",
    "q.m16#20.s1.e" to "The smaller the interval, the more terrain detail you can resolve. Judging whether a slope is passable relies precisely on contour density: at 200 m spacing a 150 m steep step gets smoothed into a gentle slope, while at 50 m it is drawn as it is.\nThis is why terrain assessment on technical routes leans on high-resolution sources like SRTM.",
    "q.m16#20.s2.p" to "Step 3: the Google version has pronounced light and shade and looks three-dimensional. How should you treat that shading when judging steepness?",
    "q.m16#20.s2.o0" to "The darker the shade, the steeper the slope — use it directly as evidence",
    "q.m16#20.s2.o1" to "Shading only reflects illumination and aspect; it cannot be used directly as a slope measure",
    "q.m16#20.s2.o2" to "Shading marks areas of snow cover",
    "q.m16#20.s2.o3" to "Shading marks terrain above 7,000 m",
    "q.m16#20.s2.e" to "Relief shading simulates how a slope is lit by sun from a given direction. Dark means the slope faces away from the light, not that it is steep. A gentle north-facing slope can be darker than a steep south-facing one.\nUsing shading as a proxy for steepness is a common and genuinely dangerous misreading. Shading is good for overall impression; to quantify slope, read contour density, and ideally cross-check against high-resolution data with elevation labels.",

    "q.m16#21.p" to "Regarding the claim \"Google Maps is intuitive but imprecise, SRTM is precise but not intuitive\", what is the right understanding?",
    "q.m16#21.o0" to "SRTM is more accurate, so Google Maps has no value",
    "q.m16#21.o1" to "They should be used together: build the overall impression from the intuitive map, then make quantified judgements with high-resolution contours",
    "q.m16#21.o2" to "Google Maps is more intuitive, so trust it first when judging slopes",
    "q.m16#21.o3" to "They differ only in colour; the information is the same",
    "q.m16#21.e" to "The two sources solve different problems. Google's relief shading and place labels build spatial sense quickly: where the mountain is, its rough shape, which way the route goes. SRTM's 50 m contours support quantified judgement: how many degrees this slope is, whether there is anywhere to put a camp.\nScreen with the intuitive map, confirm with the high-resolution one — that is the practical division. Using only one is either slow or wrong.",

    "q.m16#22.p" to "Click the approximate area of the Everest summit on the map.",
    "q.m16#22.c" to "This is an SRTM contour map of the Everest–Lhotse area; two 8,000 m peaks are visible on the same sheet.",
    "q.m16#22.e" to "To find a summit, look for the highest labelled closed contour. Here the labels near this area rise to 8600 and 8700 m with rings tightening inward; the innermost one is the summit (8,848 m).\nBe careful to separate high from steep: summit terrain is often not the steepest part of the mountain — the steepest ground is where contours are densest. That distinction matters for route risk: reaching the top tests acclimatisation and fitness, while technical risk sits mainly on a few slopes on the way up and down.",

    "q.m16#23.p" to "Between the dense closed contours of Everest and Lhotse on the same map there is a zone where contours thin out markedly and the ground dips slightly. What is it, in terrain terms?",
    "q.m16#23.o0" to "The source of a glacier",
    "q.m16#23.o1" to "The saddle between the two peaks",
    "q.m16#23.o2" to "The highest point of the ridge",
    "q.m16#23.o3" to "A steep cliff",
    "q.m16#23.e" to "Between two dense closed high points, where contours thin and the ground dips, you have a saddle (col). The one between Everest and Lhotse is the South Col at about 7,900 m, where the fourth camp of the south-side route sits — the last stop before the summit push.\nRecognising saddles on a contour map is very practical. They usually mean strong wind and exposure but relatively gentle ground: good for a camp, bad for lingering, which is why summit camps are usually on a saddle and are abandoned that same night.",

    "q.m16#24.p" to "Click the approximate area of the Muztagh Ata summit on the map.",
    "q.m16#24.c" to "This is an SRTM contour map of Muztagh Ata (7,509 m). Its top is not a sharp peak but a broad dome of snowfield.",
    "q.m16#24.e" to "Muztagh Ata's summit shape is representative: a dome, broad and gentle on top, where the highest closed contour is widely spread rather than tightly nested as on a sharp peak. To find this kind of summit, look for the highest elevation label (7,500 m here) and the closed ring it sits in.\nShape feeds directly into the climbing experience. A dome means the summit section is not steep but takes a long time; with little relief and no obvious landmarks, it is easy to lose your sense of direction on the snowfield during the descent. That is a risk often mentioned in connection with Muztagh Ata.",

    // ---------- m17 高海拔营地管理（16 题） ----------
    "q.m17#0.p" to "What is the core goal of high-altitude camp management?",
    "q.m17#0.o0" to "Making camp comfortable",
    "q.m17#0.o1" to "Sustaining fighting capacity at the lowest possible cost",
    "q.m17#0.o2" to "Saving fuel",
    "q.m17#0.o3" to "Getting good photographs",
    "q.m17#0.e" to "At altitude every unit of energy is a limited resource, and camp is the only place that gives it back. So every camp decision should answer the same question: will this leave the team in better shape tomorrow?",

    "q.m17#1.p" to "What is the first consideration when choosing a camp site?",
    "q.m17#1.o0" to "The view",
    "q.m17#1.o1" to "Avoiding avalanche paths, serac fall zones, ground below cornices, and crevasses",
    "q.m17#1.o2" to "Being close to water",
    "q.m17#1.o3" to "Being close to the start of the route",
    "q.m17#1.e" to "The first rule of siting is not getting hit by an objective hazard — because camp is where you stay for hours or a whole day and can barely move quickly. View and convenience are secondary variables.",

    "q.m17#2.p" to "Why must you not camp below a cornice?",
    "q.m17#2.o0" to "Because the ground is uneven",
    "q.m17#2.o1" to "Because a cornice can break off at any moment, sending a mass of snow and ice straight onto the camp",
    "q.m17#2.o2" to "Because it is windy",
    "q.m17#2.o3" to "Because you can't see the view",
    "q.m17#2.e" to "A cornice collapse gives no predictable warning: it may come down in the afternoon warmth or at the coldest hour before dawn. Putting camp beneath one means accepting a continuous threat you can neither monitor nor react to in advance.",

    "q.m17#3.p" to "[Multi] Which areas should a camp site avoid?",
    "q.m17#3.o0" to "Below an avalanche path",
    "q.m17#3.o1" to "Directly below or above a cornice",
    "q.m17#3.o2" to "Obvious crevasse fields",
    "q.m17#3.o3" to "Within reach of serac fall",
    "q.m17#3.o4" to "An open viewpoint with a good panorama",
    "q.m17#3.e" to "All four are cases where an objective hazard lands exactly on the camp. What they share is that they are hard to monitor and, if they happen, the consequence is team-level — which is why siting standards for a camp should be more conservative than for a route.",

    "q.m17#4.p" to "How should fuel and food be allocated?",
    "q.m17#4.o0" to "All held by one person",
    "q.m17#4.o1" to "Packed by day, with an emergency reserve set aside",
    "q.m17#4.o2" to "All kept at the tent door",
    "q.m17#4.o3" to "Split evenly by headcount with no margin",
    "q.m17#4.e" to "Packing by day makes consumption trackable, and the reserve guarantees there is always enough energy to descend safely. On a mountain fuel is not only for cooking — it is also how you melt snow for water, dry clothing and keep body temperature up.",

    "q.m17#5.p" to "Why keep an emergency reserve?",
    "q.m17#5.o0" to "Because food spoils",
    "q.m17#5.o1" to "To guarantee fuel and food for a safe descent under any circumstances",
    "q.m17#5.o2" to "Because the shop requires it",
    "q.m17#5.o3" to "To lighten the load on the way back",
    "q.m17#5.e" to "The reserve is aimed at the worst case: weather turning, being forced to stay an extra day, someone injured and needing a slow descent. If all resources are allocated to a best-case schedule, any delay leaves you with neither supplies nor the ability to move.",

    "q.m17#6.p" to "How should electronics (phone, camera, headtorch batteries) be handled overnight?",
    "q.m17#6.o0" to "Left outside the tent",
    "q.m17#6.o1" to "Kept against the body or inside the sleeping bag for warmth",
    "q.m17#6.o2" to "Kept in the outermost pocket of the pack",
    "q.m17#6.o3" to "No handling needed",
    "q.m17#6.e" to "Lithium batteries lose a lot of capacity in the cold and may shut down outright. Keeping them warm is not about protecting the device — it is about making sure the headtorch lights up and the GPS switches on tomorrow. Those are safety equipment, not personal items.",

    "q.m17#7.p" to "What should be done with wet clothing?",
    "q.m17#7.o0" to "Hang it outside to freeze-dry",
    "q.m17#7.o1" to "Keep it close to the body or in the sleeping bag to dry from body heat",
    "q.m17#7.o2" to "Pile it in a corner of the tent",
    "q.m17#7.o3" to "Stuff it straight into the pack",
    "q.m17#7.e" to "Night temperatures at altitude are extremely low, so wet clothing hung outside freezes solid. Drying against the body isn't thorough, but at least it isn't ice when you put it on tomorrow — a classic case of treating body heat as a resource.",

    "q.m17#8.p" to "Why should camp always be kept in a state where you can pack and leave immediately?",
    "q.m17#8.o0" to "To make departure convenient",
    "q.m17#8.o1" to "Because weather or a team member's condition may require an emergency evacuation at any time",
    "q.m17#8.o2" to "To save packing time",
    "q.m17#8.o3" to "To keep things tidy",
    "q.m17#8.e" to "The weather window at high camp can close suddenly, and a team member can develop altitude symptoms suddenly. At that point how long it takes to get moving decides how much risk you carry — and gear spread across the whole tent can cost you an extra half hour.",

    "q.m17#9.p" to "Which is NOT a main cause of poor sleep at altitude?",
    "q.m17#9.o0" to "Periodic breathing causing repeated brief awakenings",
    "q.m17#9.o1" to "Hypoxia and a raised heart rate",
    "q.m17#9.o2" to "Cold and discomfort",
    "q.m17#9.o3" to "The tent being too bright in colour",
    "q.m17#9.e" to "The first three are real physiological causes, and periodic breathing is the most typical: at altitude, night-time breathing involuntarily becomes intermittent and repeatedly pulls you back to light sleep. Sleep quality in turn directly affects acclimatisation — so sleeping badly is not a small matter.",

    "q.m17#10.p" to "[Order] What is a sound sequence for establishing and leaving a camp?",
    "q.m17#10.o0" to "Before arriving, check the surroundings for avalanche, serac fall and cornice threats",
    "q.m17#10.o1" to "Fix the tent position, level the ground and secure the tent",
    "q.m17#10.o2" to "Distribute supplies, melt snow for water, and plan tomorrow's schedule and sleep",
    "q.m17#10.o3" to "Before leaving, inventory gear and rubbish and restore the site",
    "q.m17#10.e" to "The first step is the one most often skipped — especially when tired, when any flat patch looks like a campsite. But once a camp is built, moving it is extremely costly, so looking around before choosing a spot should become a fixed habit.",

    "q.m17#11.p" to "Why is a camp also a pivot for retreat?",
    "q.m17#11.o0" to "Because camps hold supplies",
    "q.m17#11.o1" to "Because retreat usually means returning to camp first, then deciding whether to continue down or wait for weather",
    "q.m17#11.o2" to "Because camps have communications gear",
    "q.m17#11.o3" to "Because the guide is at camp",
    "q.m17#11.e" to "Coming down from height is rarely one continuous run; you return to the nearest camp to recover, observe and decide. That means the camp itself must be a reliable destination — not somewhere you would be afraid to return to.",

    "q.m17#12.p" to "Why must a tent be ventilated?",
    "q.m17#12.o0" to "To stay cool",
    "q.m17#12.o1" to "To avoid carbon monoxide build-up and internal frost, and to prevent suffocation and poisoning",
    "q.m17#12.o2" to "To make getting in and out easier",
    "q.m17#12.o3" to "To reduce wind resistance",
    "q.m17#12.e" to "Cooking with a stove at altitude can raise carbon monoxide levels in a sealed tent fast, and that poisoning tends to happen during sleep with symptoms — headache, fatigue — almost impossible to distinguish from altitude illness. Together these make ventilation a hard requirement.",

    "q.m17#13.p" to "What is the greatest concern when using a stove inside a tent?",
    "q.m17#13.o0" to "Fuel leaks",
    "q.m17#13.o1" to "Carbon monoxide poisoning",
    "q.m17#13.o2" to "Melting the tent",
    "q.m17#13.o3" to "Noise",
    "q.m17#13.e" to "Carbon monoxide is colourless and odourless, and its early symptoms — headache, drowsiness — overlap heavily with altitude illness. That is exactly what makes it dangerous: people fall asleep believing it is just AMS. Stove use always requires ventilation.",

    "q.m17#14.p" to "[Multi] Which health matters should be actively maintained in camp?",
    "q.m17#14.o0" to "Drinking enough water (melting snow)",
    "q.m17#14.o1" to "Eating enough, even without appetite",
    "q.m17#14.o2" to "Keeping clothing dry",
    "q.m17#14.o3" to "Watching each other's condition and gait",
    "q.m17#14.o4" to "Replacing meals with coffee and energy drinks",
    "q.m17#14.e" to "The first three are self-care, the fourth is team care — and it is often more effective than the first three: early signs of altitude illness (unsteady gait, slow responses) are hard to notice in yourself but obvious to a partner at a glance.",

    "q.m17#15.p" to "Fill in the blank: above high camp, fuel and food are usually packed by ( ) with an emergency reserve set aside.",
    "q.m17#15.a0" to "day",
    "q.m17#15.a1" to "the day",
    "q.m17#15.a2" to "days",
    "q.m17#15.a3" to "each day",
    "q.m17#15.e" to "Packed by day. That makes consumption progress obvious at a glance and lets you spot \"how many days are left\" the moment a schedule slips — rather than realising only when it has run out.",

    // ---------- m18 7000 米级目标山峰（16 题） ----------
    "q.m18#0.p" to "What is the elevation of Muztagh Ata?",
    "q.m18#0.o0" to "6,812 m",
    "q.m18#0.o1" to "7,126 m",
    "q.m18#0.o2" to "7,134 m",
    "q.m18#0.o3" to "7,509 m",
    "q.m18#0.e" to "Muztagh Ata is 7,509 m, in Akto County, Xinjiang. It is the first choice for a Chinese 7,000 m objective and the highest of the four mountains in this lesson.",

    "q.m18#1.p" to "Why is Muztagh Ata called the \"Father of Ice Mountains\"?",
    "q.m18#1.o0" to "Because it is the highest peak in the world",
    "q.m18#1.o1" to "Because its glaciers and snow volume are enormous, so from afar it looks like a vast ice cap",
    "q.m18#1.o2" to "Because it was the first 7,000 m peak to be climbed",
    "q.m18#1.o3" to "Because it is a sacred mountain in local legend",
    "q.m18#1.e" to "The name comes from how it looks: the top is covered by a huge ice cap and the snow slopes run very wide, so from a distance it reads as a white massif. That image also explains its climbing character — long snow slopes, moderate angle, but time-consuming.",

    "q.m18#2.p" to "What are the technical characteristics of climbing Muztagh Ata?",
    "q.m18#2.o0" to "Mostly vertical ice walls, extremely technical",
    "q.m18#2.o1" to "Endless snow slopes at moderate technical difficulty, but very demanding on acclimatisation and fitness",
    "q.m18#2.o2" to "Almost no technical equipment required",
    "q.m18#2.o3" to "Mainly rock climbing terrain",
    "q.m18#2.e" to "This is a classic 7,000 m profile: the route itself may not be hard, but long days of carrying loads at altitude magnify every small problem. So the real preparation focus is acclimatisation and fitness, not high-end technique.",

    "q.m18#3.p" to "What is the actual elevation of Ama Dablam?",
    "q.m18#3.o0" to "6,812 m",
    "q.m18#3.o1" to "7,126 m",
    "q.m18#3.o2" to "7,509 m",
    "q.m18#3.o3" to "8,027 m",
    "q.m18#3.e" to "Ama Dablam is 6,812 m, in the Khumbu region of Nepal. By elevation it is a 6,000 m peak, but it sits in the 7,000 m unit because its technical difficulty is on a par with peaks above 7,000 m.",

    "q.m18#4.p" to "Why is Ama Dablam, at only 6,812 m, placed in the 7,000 m unit?",
    "q.m18#4.o0" to "Because it is administratively classified as a 7,000 m peak",
    "q.m18#4.o1" to "Because its steep mixed rock-and-snow terrain and strong exposure put its difficulty on a par with peaks above 7,000 m",
    "q.m18#4.o2" to "Because its summit rate is very low",
    "q.m18#4.o3" to "Because it lies in a 7,000 m mountain range",
    "q.m18#4.e" to "This is the single most important point in the lesson: a mountain's difficulty is not its elevation. Ama Dablam is the classic proof — lower than many 7,000 m peaks, yet its technical threshold and psychological load can be greater. Choosing a mountain by elevation alone is dangerous.",

    "q.m18#5.p" to "What are the elevation and location of Lenin Peak?",
    "q.m18#5.o0" to "7,126 m, Nepal",
    "q.m18#5.o1" to "7,134 m, Pamir Plateau",
    "q.m18#5.o2" to "7,509 m, Xinjiang",
    "q.m18#5.o3" to "6,812 m, Khumbu, Nepal",
    "q.m18#5.e" to "Lenin Peak is 7,134 m on the Pamir Plateau. It is among the gentler 7,000 m options and is therefore often used as a first 7,000 m objective.",

    "q.m18#6.p" to "What is the elevation of Himlung Himal?",
    "q.m18#6.o0" to "7,126 m",
    "q.m18#6.o1" to "7,134 m",
    "q.m18#6.o2" to "7,509 m",
    "q.m18#6.o3" to "6,812 m",
    "q.m18#6.e" to "Himlung Himal is 7,126 m, in Nepal. Its route mixes snow slopes and ice walls, which makes it popular among Nepali 7,000 m peaks.",

    "q.m18#7.p" to "[Order] Arrange these mountains from lowest to highest elevation.",
    "q.m18#7.o0" to "Ama Dablam (6,812 m)",
    "q.m18#7.o1" to "Himlung Himal (7,126 m)",
    "q.m18#7.o2" to "Lenin Peak (7,134 m)",
    "q.m18#7.o3" to "Muztagh Ata (7,509 m)",
    "q.m18#7.e" to "This ordering exposes a common mistake: rank by elevation and Ama Dablam comes before Muztagh Ata — but the real technical difficulty may be the reverse. Again: elevation is only one of many variables.",

    "q.m18#8.p" to "[Multi] What mainly changes at 7,000 m compared with 6,000 m?",
    "q.m18#8.o0" to "Longer acclimatisation, with more high-camp rotations",
    "q.m18#8.o1" to "Narrower weather windows, so timing matters more",
    "q.m18#8.o2" to "Harder retreat, making self-rescue a hard requirement",
    "q.m18#8.o3" to "Generally more technical terrain and more exposure",
    "q.m18#8.o4" to "Supplemental oxygen becomes standard equipment",
    "q.m18#8.e" to "These four multiply rather than add: poor acclimatisation makes you miss the window, missing the window forces a retreat in worse conditions, and the retreat is amplified by altitude and technical terrain. That is why 7,000 m is called the watershed.",

    "q.m18#9.p" to "Why is 7,000 m called a \"watershed\"?",
    "q.m18#9.o0" to "Because ice axes are only needed above 7,000 m",
    "q.m18#9.o1" to "Because from here on, technique, judgement, fitness and logistics all act at once, and no single strength can compensate",
    "q.m18#9.o2" to "Because glaciers are only visible above 7,000 m",
    "q.m18#9.o3" to "Because commercial teams only operate above 7,000 m",
    "q.m18#9.e" to "Failures at 5,000 m tend to have one cause (acclimatisation or fitness), at 6,000 m causes start stacking, and at 7,000 m everything must be in place. That is also why this unit puts technique, judgement, weather, self-rescue and camp management together — they were always one system.",

    "q.m18#10.p" to "What matters most when choosing a 7,000 m objective?",
    "q.m18#10.o0" to "Elevation",
    "q.m18#10.o1" to "A good overall match of route type, logistics, acclimatisation schedule and retreat options",
    "q.m18#10.o2" to "The cost",
    "q.m18#10.o3" to "The summit rate",
    "q.m18#10.e" to "No single item is enough: higher isn't necessarily harder, a high summit rate isn't necessarily safer, cheap isn't necessarily good value. The real judgement is whether the combination of these four is something I, as I am now, can carry.",

    "q.m18#11.p" to "On Muztagh Ata, why are the \"endless snow slopes\" themselves a risk?",
    "q.m18#11.o0" to "Because the slopes are too slippery",
    "q.m18#11.o1" to "Because long exposure to altitude steadily erodes fitness and judgement, and the retreat distance is long",
    "q.m18#11.o2" to "Because the slopes avalanche frequently",
    "q.m18#11.o3" to "Because you cannot rope up on snow slopes",
    "q.m18#11.e" to "\"Not hard but very long\" is the classic 7,000 m risk model: it offers no single crux, but drains you continuously. Long exposure means fitness, attention and decision quality all slide slowly — and that lost margin is exactly your safety margin.",

    "q.m18#12.p" to "[Match] Match each mountain with its typical character.",
    "q.m18#12.l0" to "Muztagh Ata",
    "q.m18#12.l1" to "Ama Dablam",
    "q.m18#12.l2" to "Lenin Peak",
    "q.m18#12.l3" to "Himlung Himal",
    "q.m18#12.r0" to "Father of Ice Mountains: endless snow slopes, a test of acclimatisation and fitness",
    "q.m18#12.r1" to "Steep mixed rock and snow, strong exposure, an 8,000 m proving ground",
    "q.m18#12.r2" to "Pamir Plateau; comparatively gentle among 7,000 m peaks",
    "q.m18#12.r3" to "In Nepal; a mix of snow slopes and ice walls",
    "q.m18#12.e" to "These four profiles map onto four different preparation priorities: Muztagh Ata for acclimatisation, Ama Dablam for technique and psychology, Lenin Peak as a stepping stone, Himlung as an all-round test. Seeing them together lets you choose by your own weak point.",

    "q.m18#13.p" to "If the goal is an 8,000 m peak, what is the most sensible way to pick from the 7,000 m options?",
    "q.m18#13.o0" to "Pick the highest",
    "q.m18#13.o1" to "Pick the one that covers your own weak point (technique, acclimatisation or exposure)",
    "q.m18#13.o2" to "Pick the cheapest",
    "q.m18#13.o3" to "Pick the highest summit rate",
    "q.m18#13.e" to "Treating 7,000 m as a training ground for your weak points is worth more than treating it as levelling up. Weak on technique, choose Ama Dablam; poor acclimatiser, choose Muztagh Ata with its long slopes and established high-camp rotations.",

    "q.m18#14.p" to "What is the correct view of the preparation period for a 7,000 m peak?",
    "q.m18#14.o0" to "About the same as for 6,000 m",
    "q.m18#14.o1" to "Clearly longer, requiring enough high-camp rotations and acclimatisation time",
    "q.m18#14.o2" to "Only fitness training is needed",
    "q.m18#14.o3" to "It can start immediately after the previous climb",
    "q.m18#14.e" to "Acclimatisation is cumulative, and 7,000 m usually requires several high-camp rotations. Building a tight itinerary without budgeting acclimatisation time is the direct reason many 7,000 m teams fail to summit — or have accidents.",

    "q.m18#15.p" to "Why does this unit place \"hazard judgement\" after the technical lessons?",
    "q.m18#15.o0" to "Because judgement is easier than technique",
    "q.m18#15.o1" to "Because technical ability gives you the confidence to enter harder terrain, which makes judgement more necessary to restrain it",
    "q.m18#15.o2" to "Because of space limits in the curriculum",
    "q.m18#15.o3" to "Because technique doesn't matter",
    "q.m18#15.e" to "This is a realistic design: the more skilled you are, the harder the routes you can attempt, so the need to limit yourself actually rises. Putting judgement after technique mirrors that order in reality — capability first, then restraint.",

    // ---------- m19 8000 米级生理与策略（19 题） ----------
    "q.m19#0.p" to "The \"death zone\" usually refers to:",
    "q.m19#0.o0" to "Above 7,000 m",
    "q.m19#0.o1" to "Above 8,000 m",
    "q.m19#0.o2" to "Above 5,500 m",
    "q.m19#0.o3" to "Above 6,000 m",
    "q.m19#0.e" to "Above 8,000 m is called the death zone for a simple reason: the partial pressure of oxygen is so low that no amount of acclimatisation lets the body maintain balance for long. It is not rhetoric but physiological fact — and it is the most fundamental dividing line between 8,000 m and 7,000 m.",

    "q.m19#1.p" to "At 8,000 m, atmospheric pressure is roughly what fraction of sea level?",
    "q.m19#1.o0" to "One half",
    "q.m19#1.o1" to "Two thirds",
    "q.m19#1.o2" to "One third",
    "q.m19#1.o3" to "One fifth",
    "q.m19#1.e" to "About one third. That means each breath delivers only around thirty per cent of the oxygen molecules available at sea level — while climbing demands several times the oxygen of rest. That supply-demand gap is the source of every 8,000 m risk.",

    "q.m19#2.p" to "Why can the human body not stay above 8,000 m for long?",
    "q.m19#2.o0" to "Because it is too cold",
    "q.m19#2.o1" to "Because oxygen partial pressure is below the threshold needed to sustain metabolism, so the body steadily deteriorates",
    "q.m19#2.o2" to "Because there isn't enough food",
    "q.m19#2.o3" to "Because the wind is too strong",
    "q.m19#2.e" to "Staying long means consuming more than you repair: even at rest the body loses muscle and weight and cognitive performance declines. That is why an 8,000 m itinerary must be fast in and fast out — there is no option to wait for conditions to improve.",

    "q.m19#3.p" to "Which capacity does hypoxia usually affect first?",
    "q.m19#3.o0" to "Leg strength",
    "q.m19#3.o1" to "Judgement and cognition",
    "q.m19#3.o2" to "Vision",
    "q.m19#3.o3" to "Hearing",
    "q.m19#3.e" to "This is the most dangerous mechanism at 8,000 m: someone whose judgement has declined cannot judge that their judgement has declined. Conversely, weak legs you notice at once, while the thought \"I can keep going\" may itself already be a product of hypoxia.",

    "q.m19#4.p" to "Why is declining judgement especially dangerous at 8,000 m?",
    "q.m19#4.o0" to "Because you may get lost",
    "q.m19#4.o1" to "Because you have to use already-impaired judgement to decide whether to continue or retreat",
    "q.m19#4.o2" to "Because it affects your partners",
    "q.m19#4.o3" to "Because it slows you down",
    "q.m19#4.e" to "It is a recursive trap: precisely when a critical decision is needed — continue or retreat — your decision-making is least reliable. \"Let's go a bit further and see\" may be reasonable at 4,000 m; at 8,000 m it may already be an error driven by hypoxia.",

    "q.m19#5.p" to "[Multi] Which are typical signs of hypoxia-induced cognitive decline?",
    "q.m19#5.o0" to "Slower reactions, slurred speech",
    "q.m19#5.o1" to "Errors in arithmetic and judgement",
    "q.m19#5.o2" to "Risk assessment becoming overly optimistic",
    "q.m19#5.o3" to "Mood swings, irritability or apathy",
    "q.m19#5.o4" to "Reduced sensation of frostbite in fingers and toes",
    "q.m19#5.e" to "All four are typical, and they share one feature: the person concerned can barely notice them. So the reliable approach is externalising — checklists instead of memory, fixed times instead of \"feels about right\", and partners watching each other instead of self-assessment.",

    "q.m19#6.p" to "What is the most effective counter to declining judgement?",
    "q.m19#6.o0" to "Using willpower to stay alert",
    "q.m19#6.o1" to "Externalising decisions into pre-written checklists and fixed rules (time, oxygen remaining, weather thresholds)",
    "q.m19#6.o2" to "Drinking more hot water",
    "q.m19#6.o3" to "Slowing down",
    "q.m19#6.e" to "Willpower is precisely what hypoxia erodes first. The reliable method is to write the rules down while you are still functioning: what time you must turn around, how much oxygen remaining triggers descent — then you only have to verify facts, not re-judge.",

    "q.m19#7.p" to "Why does an 8,000 m itinerary emphasise \"start early, return early\"?",
    "q.m19#7.o0" to "To avoid crowds",
    "q.m19#7.o1" to "Because the chance of weather deterioration rises in the afternoon, and cold and wind rapidly drain energy and oxygen",
    "q.m19#7.o2" to "Because the route is shorter in the morning",
    "q.m19#7.o3" to "Because of guide habits",
    "q.m19#7.e" to "At 8,000 m the cost of \"late\" is magnified: the same ground takes twice the effort in the afternoon, and once darkness falls both temperature and judgement drop. \"Descending too late\" is almost always the common starting point of that accident chain.",

    "q.m19#8.p" to "Why does 8,000 m require \"simplified decision-making\"?",
    "q.m19#8.o0" to "To save time",
    "q.m19#8.o1" to "Because cognitive resources are limited and should be reserved for the decisions that truly matter",
    "q.m19#8.o2" to "Because you don't want to think at altitude",
    "q.m19#8.o3" to "Because partners will decide for you",
    "q.m19#8.e" to "In practice: fixed places and order for gear, procedures turned into checklists, the schedule fixed in advance. Making \"what to wear today, what to do first\" a default that needs no thought is what preserves judgement for decisions like continue or retreat.",

    "q.m19#9.p" to "Why do even experienced climbers need checklists at 8,000 m?",
    "q.m19#9.o0" to "Because memory is unreliable",
    "q.m19#9.o1" to "Because hypoxia damages working memory first, and a checklist doesn't depend on memory",
    "q.m19#9.o2" to "Because regulations require it",
    "q.m19#9.o3" to "To help beginners learn",
    "q.m19#9.e" to "The logic is the same as in aviation: in high-load, high-consequence environments you cannot rely on \"I probably won't forget\". A checklist is not a teaching aid for novices but insurance against the errors even experts make.",

    "q.m19#10.p" to "What mainly causes continuous weight loss at altitude?",
    "q.m19#10.o0" to "Because food tastes bad",
    "q.m19#10.o1" to "Because the body keeps breaking down its own tissue under hypoxia, while reduced appetite means insufficient intake",
    "q.m19#10.o2" to "Because of the amount of exercise",
    "q.m19#10.o3" to "Because of insufficient drinking water",
    "q.m19#10.e" to "Two factors act together: hypoxia puts the body in a state where breakdown exceeds synthesis, and altitude illness itself suppresses appetite. That is why being able to eat at altitude is a capability, not a pleasure.",

    "q.m19#11.p" to "Why is sleep poor at 8,000 m?",
    "q.m19#11.o0" to "Because the tent is uncomfortable",
    "q.m19#11.o1" to "Because low oxygen causes periodic breathing, with repeated pauses that pull you out of sleep",
    "q.m19#11.o2" to "Because it is windy",
    "q.m19#11.o3" to "Because you slept too much during the day",
    "q.m19#11.e" to "Periodic breathing is the classic high-altitude sleep phenomenon: an unstable breathing drive produces repeated apnoea-then-startle cycles. Sleep quality then directly affects next-day acclimatisation and energy — so being able to sleep is a core competence at high camp.",

    "q.m19#12.p" to "[Order] Arrange the effects of hypoxia on body function in their usual order of appearance.",
    "q.m19#12.o0" to "Faster breathing and raised heart rate (compensation)",
    "q.m19#12.o1" to "Declining endurance on prolonged exertion",
    "q.m19#12.o2" to "Declining judgement and arithmetic ability",
    "q.m19#12.o3" to "Altered consciousness, ataxia",
    "q.m19#12.e" to "The first two are the body trying to cope; the last two are the body failing. The dangerous one is the third — it appears before any obvious change in consciousness, so \"looks normal\" does not mean \"thinking clearly\".",

    "q.m19#13.p" to "What is the most direct and reliable way to counter hypoxia at 8,000 m?",
    "q.m19#13.o0" to "Eat more",
    "q.m19#13.o1" to "Use supplemental oxygen",
    "q.m19#13.o2" to "Rest more",
    "q.m19#13.o3" to "Slow down",
    "q.m19#13.e" to "The others work by reducing consumption or accelerating acclimatisation, while supplemental oxygen directly raises inspired oxygen partial pressure — it changes the root variable. That is why oxygen is standard safety equipment at 8,000 m.",

    "q.m19#14.p" to "What is the correct understanding of the \"limit of acclimatisation\"?",
    "q.m19#14.o0" to "Acclimatisation can continue indefinitely",
    "q.m19#14.o1" to "Acclimatisation has a ceiling; above a certain altitude no amount of it fully compensates",
    "q.m19#14.o2" to "Acclimatisation takes one day",
    "q.m19#14.o3" to "Acclimatisation is unrelated to altitude",
    "q.m19#14.e" to "Acclimatisation is a process with a limit, not a curve that keeps climbing. That is the fundamental reason 8,000 m depends on oxygen and a fast-in-fast-out strategy — not insufficient preparation, but the physiological absence of an option to \"acclimatise and then stay\".",

    "q.m19#15.p" to "Why is the root cause of 8,000 m accidents rarely a single event?",
    "q.m19#15.o0" to "Because of bad luck",
    "q.m19#15.o1" to "Because hypoxia weakens judgement, energy and coordination simultaneously, making several links brittle at once",
    "q.m19#15.o2" to "Because the equipment is inadequate",
    "q.m19#15.o3" to "Because there are too many people",
    "q.m19#15.e" to "At low altitude a mistake usually leaves margin to recover; at 8,000 m judgement, energy and motor control all decline together, so small errors chain directly into accidents. The safety strategy at 8,000 m must therefore be more layers of protection, not simply being more careful.",

    "q.m19#16.p" to "[Multi] What are the main causes of death at 8,000 m?",
    "q.m19#16.o0" to "Avalanche and serac fall",
    "q.m19#16.o1" to "Falls",
    "q.m19#16.o2" to "Hypothermia",
    "q.m19#16.o3" to "Altitude illness and its complications",
    "q.m19#16.o4" to "Environmental injury such as snow blindness and sunburn",
    "q.m19#16.e" to "All four are common, and they often stack: a fall leaves you unable to self-rescue, then waiting in the cold, then hypothermia, then worsening altitude illness. That is why 8,000 m training cannot focus only on altitude illness but must include technique, judgement and systems.",

    "q.m19#17.p" to "Fill in the blank: above 8,000 m is called the \"( ) zone\".",
    "q.m19#17.a0" to "death",
    "q.m19#17.a1" to "dead",
    "q.m19#17.e" to "The death zone. The term's practical value is the hard constraint it conveys: here there is no option to wait or ease off. Every plan, supply calculation and decision must be designed around getting through as fast as possible.",

    "q.m19#18.p" to "At 8,000 m you notice you \"really want to keep going for the summit\". What should you do?",
    "q.m19#18.o0" to "Trust your instinct and keep climbing",
    "q.m19#18.o1" to "Treat it as a possible sign of hypoxia-driven risk underestimation and immediately check the turnaround conditions set in advance",
    "q.m19#18.o2" to "Speed up and get to the top",
    "q.m19#18.o3" to "Let your partners decide",
    "q.m19#18.e" to "This is a very representative situation: a strong urge to continue may be mere desire at low altitude, but at 8,000 m it may be a signal of impaired judgement. The only reliable reference then is not how you feel but the objective conditions written down before departure.",

    // ---------- m20 辅助氧气系统（20 题） ----------
    "q.m20#0.p" to "What is the main role of supplemental oxygen at 8,000 m?",
    "q.m20#0.o0" to "Replacing fitness training",
    "q.m20#0.o1" to "Raising blood oxygen, lowering altitude-illness risk, and improving mobility and judgement",
    "q.m20#0.o2" to "Keeping you warm",
    "q.m20#0.o3" to "Reducing pack weight",
    "q.m20#0.e" to "The item most often overlooked — and the most critical for safety — is improved judgement, because it directly counters the most dangerous factor at 8,000 m. That is also why oxygen is standard safety equipment at this altitude rather than a labour-saving device.",

    "q.m20#1.p" to "What are the components of a supplemental oxygen system?",
    "q.m20#1.o0" to "Cylinder, regulator, flow meter, mask or nasal cannula",
    "q.m20#1.o1" to "Cylinder and backpack",
    "q.m20#1.o2" to "Mask and insulation layer",
    "q.m20#1.o3" to "Regulator and helmet",
    "q.m20#1.e" to "Each part has its job: the cylinder stores, the regulator drops high pressure to a safe range, the flow meter sets the output, and the mask or cannula delivers it. A failure anywhere leaves you inhaling less than you think — which is why the system is checked on every leg.",

    "q.m20#2.p" to "What flow rate is typical in climbing use?",
    "q.m20#2.o0" to "0.5–1 L/min",
    "q.m20#2.o1" to "2–4 L/min",
    "q.m20#2.o2" to "8–10 L/min",
    "q.m20#2.o3" to "Above 15 L/min",
    "q.m20#2.e" to "2–4 L/min is the customary range in climbing; the exact figure depends on altitude, exertion and individual response. Higher flow is more comfortable but consumes faster — a trade-off that directly determines how long you can stay at 8,000 m.",

    "q.m20#3.p" to "Why must an emergency reserve be calculated separately in oxygen planning?",
    "q.m20#3.o0" to "To carry a little extra",
    "q.m20#3.o1" to "Because delays, supporting a partner, or a system failure can all consume extra oxygen",
    "q.m20#3.o2" to "Because cylinders leak",
    "q.m20#3.o3" to "Because regulations require it",
    "q.m20#3.e" to "The classic oxygen planning error is \"just enough to reach the summit\". Real schedules are almost always slower than planned, and partners may run short or the system may leak. Without a reserve, any deviation leaves you gambling at the most dangerous altitude.",

    "q.m20#4.p" to "What can happen when the oxygen runs out?",
    "q.m20#4.o0" to "Nothing at all",
    "q.m20#4.o1" to "Condition may deteriorate rapidly, because the body has adapted to a higher inspired oxygen concentration",
    "q.m20#4.o2" to "Altitude illness strikes instantly",
    "q.m20#4.o3" to "The system switches automatically to ambient air",
    "q.m20#4.e" to "Dropping abruptly from enriched oxygen back to ambient partial pressure is equivalent to gaining a chunk of altitude in an instant at 8,000 m. If you are far from camp and already exhausted, things can turn dangerous fast — which is why the oxygen margin must be kept conservative.",

    "q.m20#5.p" to "[Multi] What discipline applies to using an oxygen system?",
    "q.m20#5.o0" to "Check flow and connections on every leg",
    "q.m20#5.o1" to "Use the planned flow rate; don't turn it up at will",
    "q.m20#5.o2" to "Record what remains and the estimated time it supports",
    "q.m20#5.o3" to "Agree in advance at what remaining amount you must descend",
    "q.m20#5.o4" to "Turn the flow to maximum when you feel unwell",
    "q.m20#5.e" to "The fourth is the most important: make \"descend at this remaining amount\" a number fixed beforehand rather than a discussion on the spot. By the time it matters, the person who needs that rule may already have lost the ability to judge accurately.",

    "q.m20#6.p" to "Why is using oxygen not \"cheating\"?",
    "q.m20#6.o0" to "Because the rules allow it",
    "q.m20#6.o1" to "Because above 8,000 m the body is outside the physiological range it can compensate for long term, so using oxygen is the standard response to that fact",
    "q.m20#6.o2" to "Because everyone does it",
    "q.m20#6.o3" to "Because it improves summit rates",
    "q.m20#6.e" to "The word cheating implies the assumption that a bit more effort lets you slip past the limit — but the limit at 8,000 m is physics and physiology, not a rule. Oxygen raises the physiological ceiling somewhat; it does not change the fact that you cannot stay long.",

    "q.m20#7.p" to "What is the main difference between a mask and a nasal cannula?",
    "q.m20#7.o0" to "A mask delivers a more stable concentration but is stuffier and restricts vision when moving",
    "q.m20#7.o1" to "A cannula can deliver a higher concentration",
    "q.m20#7.o2" to "They are identical",
    "q.m20#7.o3" to "A mask is lighter",
    "q.m20#7.e" to "A mask seals better and holds a stable concentration, but adds breathing resistance, fogs easily and is uncomfortable on the move; a cannula is comfortable with a clear view, but the actual inspired concentration depends heavily on how you breathe. The choice depends on terrain, intensity and personal tolerance — it is not simply which is better.",

    "q.m20#8.p" to "What trade-off comes with raising versus lowering the flow rate?",
    "q.m20#8.o0" to "Comfort against endurance time",
    "q.m20#8.o1" to "Weight against price",
    "q.m20#8.o2" to "There is no trade-off",
    "q.m20#8.o3" to "Altitude against temperature",
    "q.m20#8.e" to "Higher flow means a more comfortable body and better-preserved judgement, but less time before it runs out. An oxygen plan is therefore effectively a budget for how long you can stay high — which sets the summit-day window and the turnaround time directly.",

    "q.m20#9.p" to "Why does cylinder weight become a logistics problem?",
    "q.m20#9.o0" to "Because they are bulky",
    "q.m20#9.o1" to "Because both cylinder and gas are heavy, and above high camp everything has to be carried by people",
    "q.m20#9.o2" to "Because they can't be checked in",
    "q.m20#9.o3" to "Because they break easily",
    "q.m20#9.e" to "At altitude the cost of every kilogram is magnified, and a cylinder is heavy and incompressible. That is why oxygen planning must be designed together with camp layout and manpower — it is not a stand-alone equipment question.",

    "q.m20#10.p" to "Why must oxygen be cached at high camp in advance?",
    "q.m20#10.o0" to "To lighten the summit day and guarantee oxygen is available then",
    "q.m20#10.o1" to "To prevent theft",
    "q.m20#10.o2" to "Because it is colder up there",
    "q.m20#10.o3" to "To save money",
    "q.m20#10.e" to "Summit day is when you are most stretched and least fit; you cannot also carry oxygen up. So it has to be ferried up load by load beforehand — which means oxygen quantity, manpower and weather window are bound together at the planning stage.",

    "q.m20#11.p" to "What should you do if the oxygen system fails en route?",
    "q.m20#11.o0" to "Keep climbing and fix it at home",
    "q.m20#11.o1" to "Immediately assess remaining oxygen and your altitude, then follow the plan: descend or switch to the backup system",
    "q.m20#11.o2" to "Turn the flow up to try to fix it",
    "q.m20#11.o3" to "Take it apart and repair it",
    "q.m20#11.e" to "An oxygen failure means you are suddenly operating under the conditions of a higher altitude, unprotected. Handling it outranks everything else: first decide whether the backup lets you continue, and if not, descend. At 8,000 m, going back down is a meaningful choice, not a failure.",

    "q.m20#12.p" to "[Order] What is the check sequence for the oxygen system on summit day?",
    "q.m20#12.o0" to "Confirm cylinder pressure and the estimated supported time",
    "q.m20#12.o1" to "Check the regulator, hose and mask or cannula for damage",
    "q.m20#12.o2" to "Open the flow and confirm gas actually comes through",
    "q.m20#12.o3" to "Record the remaining amount and tell your partners and the people back home",
    "q.m20#12.e" to "The first three are technical checks, the fourth is team communication — and the latter matters especially at altitude: if your partners know your oxygen margin, they may spot a decline in you before you do.",

    "q.m20#13.p" to "Why can oxygen not replace acclimatisation?",
    "q.m20#13.o0" to "Because oxygen is too expensive",
    "q.m20#13.o1" to "Because acclimatisation is the body's own physiological compensation, while oxygen only raises the inspired concentration",
    "q.m20#13.o2" to "Because oxygen stops working",
    "q.m20#13.o3" to "Because oxygen only helps with altitude illness",
    "q.m20#13.e" to "Acclimatisation changes how the body uses oxygen; oxygen changes how much comes in. You cannot get the former from the latter. So descending, gradual ascent and adequate acclimatisation time remain non-negotiable prerequisites at 8,000 m.",

    "q.m20#14.p" to "[Multi] What are common oxygen system failures?",
    "q.m20#14.o0" to "Icing or blockage at the connection",
    "q.m20#14.o1" to "Hose leaks",
    "q.m20#14.o2" to "Regulator faults causing inaccurate flow",
    "q.m20#14.o3" to "Difficulty opening the cylinder valve",
    "q.m20#14.o4" to "The cylinder weighing more than expected",
    "q.m20#14.e" to "All four relate to cold, icing and awkward handling — and all of them happen at altitude, in fatigue, when they are hardest to deal with. That is why a backup system alone is not enough; you also need a decision plan for failure.",

    "q.m20#15.p" to "Why must the oxygen plan be written into the itinerary?",
    "q.m20#15.o0" to "For appearance",
    "q.m20#15.o1" to "Because the amount of oxygen directly determines the feasible turnaround time and the maximum stay",
    "q.m20#15.o2" to "To record expenses",
    "q.m20#15.o3" to "For easier reimbursement",
    "q.m20#15.e" to "Oxygen is not \"bring some and you're fine\" — it is a quantified budget: how many cylinders, at what flow, supporting how many hours. Those numbers in turn set the turnaround time, so they must be planned with the schedule rather than on a separate list.",

    "q.m20#16.p" to "Fill in the blank: the typical climbing flow rate is about 2 to ( ) L/min.",
    "q.m20#16.a0" to "4",
    "q.m20#16.a1" to "four",
    "q.m20#16.e" to "2–4 L/min. The range is the balance between maintaining adequate blood oxygen and conserving gas. Oxygen management is, in the end, a continuous resource-allocation problem.",

    "q.m20#17.p" to "What should you do if a partner's oxygen is running short?",
    "q.m20#17.o0" to "Keep pushing for the summit; everyone for themselves",
    "q.m20#17.o1" to "Share the information and remaining amounts immediately, then follow the plan to descend together or redistribute oxygen",
    "q.m20#17.o2" to "Let them sort it out",
    "q.m20#17.o3" to "Give them all of your own oxygen",
    "q.m20#17.e" to "Running short is a team-level event, not a personal one: it affects descent speed and mutual cover. The worst options are the two extremes — carrying on to the summit, or giving up your own supply entirely. The sensible response is to redistribute resources and prioritise getting everyone down.",

    "q.m20#18.p" to "A usable cylinder holds 1,200 litres. At a flow of 3 L/min, roughly how many minutes will it last?",
    "q.m20#18.a0" to "400",
    "q.m20#18.e" to "About 400 minutes (roughly 6.7 hours): 1200 ÷ 3 = 400. Calculations like this matter directly on summit day — they determine how long you can stay at 8,000 m, and therefore what time the turnaround must be set for.",

    "q.m20#19.p" to "Summit plan: 5 hours up, 3 hours down, flow at 2 L/min, plus 60 minutes of emergency reserve. What total oxygen volume is required, in litres?",
    "q.m20#19.a0" to "1080",
    "q.m20#19.e" to "1080 litres: (5 + 3) hours × 60 min × 2 L/min = 960 litres, plus 60 × 2 = 120 litres of reserve, totalling 1080. Calculating ascent, descent and reserve as three separate parts is the most basic discipline of oxygen planning — counting only whether there is enough to get up is the most common error.",

    // ---------- m21 8000 米级全景（喜马拉雅）（18 题） ----------
    "q.m21#0.p" to "How many peaks above 8,000 m are there worldwide?",
    "q.m21#0.o0" to "10",
    "q.m21#0.o1" to "12",
    "q.m21#0.o2" to "14",
    "q.m21#0.o3" to "18",
    "q.m21#0.e" to "Fourteen, all within the Himalaya and Karakoram ranges. That number is the origin of the mountaineering objective known as the \"fourteen eight-thousanders\".",

    "q.m21#1.p" to "Which countries hold the fourteen 8,000 m peaks?",
    "q.m21#1.o0" to "China, Nepal, India, Pakistan",
    "q.m21#1.o1" to "China, Nepal, Bhutan, India",
    "q.m21#1.o2" to "Nepal, Pakistan, Afghanistan, Tajikistan",
    "q.m21#1.o3" to "China, India, Pakistan, Myanmar",
    "q.m21#1.e" to "Four countries: China, Nepal, India and Pakistan. Understanding that distribution matters — it drives permits, logistics, rescue and political risk, all of which are part of planning at 8,000 m.",

    "q.m21#2.p" to "What is the elevation of Everest?",
    "q.m21#2.o0" to "8,611 m",
    "q.m21#2.o1" to "8,848 m",
    "q.m21#2.o2" to "8,586 m",
    "q.m21#2.o3" to "8,516 m",
    "q.m21#2.e" to "8,848 m (the 2020 China–Nepal joint survey gave 8,848.86 m). As the world's highest, it also has the most developed commercial infrastructure — but mature means mature logistics and routes, not low risk: congestion, cost and the difficulty of good judgement are real hazards too.",

    "q.m21#3.p" to "What is Annapurna I's place in 8,000 m history?",
    "q.m21#3.o0" to "The last to be climbed",
    "q.m21#3.o1" to "The first 8,000 m peak ever climbed",
    "q.m21#3.o2" to "The lowest fatality rate",
    "q.m21#3.o3" to "The easiest to climb",
    "q.m21#3.e" to "Annapurna I is 8,091 m and was first climbed in 1950 — the first 8,000 m peak in human history. Its fatality rate has long been among the highest. Being climbed first has nothing to do with being easy.",

    "q.m21#4.p" to "What distinguishes Shishapangma?",
    "q.m21#4.o0" to "It is in Nepal",
    "q.m21#4.o1" to "It is the only 8,000 m peak entirely within China, and the last of the fourteen to be climbed",
    "q.m21#4.o2" to "It is the highest",
    "q.m21#4.o3" to "It is the easiest",
    "q.m21#4.e" to "Shishapangma is 8,027 m in Tibet, the only 8,000 m peak lying entirely inside China; it was first climbed in 1964 by a Chinese team and is the last of the fourteen to have been summited.",

    "q.m21#5.p" to "What is the relationship between Lhotse and Everest?",
    "q.m21#5.o0" to "They are far apart",
    "q.m21#5.o1" to "Lhotse adjoins Everest and often shares the same approach route",
    "q.m21#5.o2" to "Lhotse is higher than Everest",
    "q.m21#5.o3" to "They are in different ranges",
    "q.m21#5.e" to "Lhotse is 8,516 m, immediately beside Everest, and from the south the two share most of the route and camps. That is why they are often considered within one itinerary for logistics and acclimatisation.",

    "q.m21#6.p" to "What is the usual assessment of Cho Oyu?",
    "q.m21#6.o0" to "The most technical 8,000 m peak",
    "q.m21#6.o1" to "Generally considered one of the less technical 8,000 m peaks",
    "q.m21#6.o2" to "The 8,000 m peak with the highest fatality rate",
    "q.m21#6.o3" to "No commercial teams climb it",
    "q.m21#6.e" to "Cho Oyu is 8,188 m and, with a relatively gentle route and mature logistics, is often regarded as one of the less technical 8,000 m peaks. But \"relatively easy\" still means operating in the death zone for days — the magnitude cannot be underestimated.",

    "q.m21#7.p" to "What is Nanga Parbat known for?",
    "q.m21#7.o0" to "Gentle routes",
    "q.m21#7.o1" to "Enormous vertical relief and severe avalanche risk",
    "q.m21#7.o2" to "The cheapest permits",
    "q.m21#7.o3" to "The best logistics",
    "q.m21#7.e" to "Nanga Parbat is 8,126 m and known as the \"Naked Mountain\" — it rises an immense distance straight from the valley, with prominent avalanche and rockfall risk. Its historical climbing cost is high even by 8,000 m standards.",

    "q.m21#8.p" to "[Match] Match each peak with its elevation.",
    "q.m21#8.l0" to "Everest",
    "q.m21#8.l1" to "Kangchenjunga",
    "q.m21#8.l2" to "Lhotse",
    "q.m21#8.l3" to "Makalu",
    "q.m21#8.r0" to "8,848 m",
    "q.m21#8.r1" to "8,586 m",
    "q.m21#8.r2" to "8,516 m",
    "q.m21#8.r3" to "8,485 m",
    "q.m21#8.e" to "These are the first, third, fourth and fifth highest peaks in the world. Don't just memorise the numbers — remember the ordering and the range each belongs to. Numbers can be looked up; the overall picture has to be in your head.",

    "q.m21#9.p" to "Why has \"the fourteen\" become a recognised mountaineering objective?",
    "q.m21#9.o0" to "Because it is a round number",
    "q.m21#9.o1" to "Because it happens to form a complete boundary of high-altitude climbing, and the count is within reach of a lifetime",
    "q.m21#9.o2" to "Because commercial companies promoted it",
    "q.m21#9.o3" to "Because the UIAA requires it",
    "q.m21#9.e" to "What makes the fourteen distinctive is that they have an objective, unambiguous boundary (above 8,000 m), a finite count, and can be listed one by one. That makes the goal both clear and lifelong — which is why it became the benchmark.",

    "q.m21#10.p" to "[Multi] What is normally required to summit an 8,000 m peak?",
    "q.m21#10.o0" to "A complete acclimatisation cycle with high-camp rotations",
    "q.m21#10.o1" to "Technical ability and glacier travel experience",
    "q.m21#10.o2" to "A reliable oxygen and logistics system",
    "q.m21#10.o3" to "Fitness and judgement validated at 7,000 m",
    "q.m21#10.o4" to "A professional film crew",
    "q.m21#10.e" to "The four correspond to four dimensions: physiological (acclimatisation), technical, logistical, and accumulated experience. They all act at once at 8,000 m — any missing one becomes a weak link, and weak links are magnified fast at altitude.",

    "q.m21#11.p" to "Dhaulagiri, Manaslu and Annapurna are all in which country?",
    "q.m21#11.o0" to "China",
    "q.m21#11.o1" to "Nepal",
    "q.m21#11.o2" to "Pakistan",
    "q.m21#11.o3" to "India",
    "q.m21#11.e" to "All three are in Nepal. Nepal holds the largest number of 8,000 m peaks, which is why its climbing industry is so developed — and also why it faces persistent pressure over permits, management and environmental protection.",

    "q.m21#12.p" to "Why are \"mature commercial routes\" on 8,000 m peaks still dangerous?",
    "q.m21#12.o0" to "Because they are expensive",
    "q.m21#12.o1" to "Because the altitude itself cannot be changed, and congestion, waiting and difficult rescue create new risks",
    "q.m21#12.o2" to "Because the guides are unprofessional",
    "q.m21#12.o3" to "Because the equipment is poor",
    "q.m21#12.e" to "Commercialisation solves logistics and route familiarity, but it cannot lower the altitude. On the contrary, many teams pushing in the same window creates queueing — and waiting at 8,000 m means burning extra oxygen and body heat.",

    "q.m21#13.p" to "[Order] Arrange these peaks from highest to lowest.",
    "q.m21#13.o0" to "Everest (8,848)",
    "q.m21#13.o1" to "Kangchenjunga (8,586)",
    "q.m21#13.o2" to "Makalu (8,485)",
    "q.m21#13.o3" to "Annapurna I (8,091)",
    "q.m21#13.e" to "Behind the ordering lies the span from world number one to world number ten. Remembering the order is more useful than remembering exact figures — when discussing routes, logistics and difficulty, what you usually need is relative position.",

    "q.m21#14.p" to "Why study first-ascent history when learning about 8,000 m peaks?",
    "q.m21#14.o0" to "For exams",
    "q.m21#14.o1" to "Because first ascents tend to expose the peak's core difficulties and risk types",
    "q.m21#14.o2" to "To memorise names",
    "q.m21#14.o3" to "It has nothing to do with climbing",
    "q.m21#14.e" to "Early teams' failures and losses point precisely at a peak's main difficulties — recurrent avalanche sections, violent wind sections, exposed stretches of route. Reading first-ascent history as a risk file is far more useful than reading it as a story.",

    "q.m21#15.p" to "[Multi] Which of these are Himalayan 8,000 m peaks?",
    "q.m21#15.o0" to "Everest",
    "q.m21#15.o1" to "Annapurna I",
    "q.m21#15.o2" to "Shishapangma",
    "q.m21#15.o3" to "K2",
    "q.m21#15.e" to "The first three are in the Himalaya; K2 is in the Karakoram. The two ranges are geographically adjacent but geologically distinct, and their climbing seasons and weather patterns differ — which is why the fourteen are often discussed grouped by range.",

    "q.m21#16.p" to "How does the title \"highest peak in the world\" affect strategy?",
    "q.m21#16.o0" to "Not at all",
    "q.m21#16.o1" to "It means the greatest media and commercial attention, and therefore the greatest team density and congestion risk",
    "q.m21#16.o2" to "It means the easiest route",
    "q.m21#16.o3" to "It means the easiest rescue",
    "q.m21#16.e" to "Attention brings resources and also crowds. When large numbers of teams concentrate in one window, waiting, congestion and the psychological pressure of not wanting to give up a place in the queue all become additional sources of risk — a strategy problem peculiar to the highest peak.",

    "q.m21#17.p" to "Fill in the blank: worldwide there are ( ) peaks above 8,000 m.",
    "q.m21#17.a0" to "14",
    "q.m21#17.a1" to "fourteen",
    "q.m21#17.e" to "Fourteen. A small number, yet it defines the entire boundary of high-altitude climbing — which is why \"the fourteen\" is still treated as a goal worth a lifetime.",

    // ---------- m22 8000 米级全景（喀喇昆仑）（17 题） ----------
    "q.m22#0.p" to "How many 8,000 m peaks are in the Karakoram?",
    "q.m22#0.o0" to "2",
    "q.m22#0.o1" to "4",
    "q.m22#0.o2" to "6",
    "q.m22#0.o3" to "10",
    "q.m22#0.e" to "Four: K2, Gasherbrum I, Gasherbrum II and Broad Peak. They are also known as K2, K4, K5 and K3 — the K stands for Karakoram.",

    "q.m22#1.p" to "What are K2's elevation and standing?",
    "q.m22#1.o0" to "8,611 m, second highest in the world, and among the most technical and deadliest 8,000 m peaks",
    "q.m22#1.o1" to "8,848 m, highest in the world",
    "q.m22#1.o2" to "8,586 m, third highest in the world",
    "q.m22#1.o3" to "8,051 m, one of the easier ones",
    "q.m22#1.e" to "K2 is 8,611 m, second highest in the world. It is widely regarded as one of the hardest and most dangerous 8,000 m peaks, which is why it is called \"the climber's mountain\" — here technique and judgement weigh far more than logistical support.",

    "q.m22#2.p" to "Why do the Karakoram and Himalaya often have different climbing seasons?",
    "q.m22#2.o0" to "Because of different latitudes and longitudes",
    "q.m22#2.o1" to "Because they are affected by different climate systems: the Karakoram is more strongly influenced by the westerlies",
    "q.m22#2.o2" to "Because of different altitudes",
    "q.m22#2.o3" to "Because of different regulations",
    "q.m22#2.e" to "The Himalaya's best season is driven mainly by the monsoon cycle, while the Karakoram is more affected by the westerlies and orographic precipitation. That decides when to go — and pick the wrong season and even the best team will never see a summit window.",

    "q.m22#3.p" to "What is Broad Peak also called?",
    "q.m22#3.o0" to "K1",
    "q.m22#3.o1" to "K2",
    "q.m22#3.o2" to "K3",
    "q.m22#3.o3" to "K5",
    "q.m22#3.e" to "Broad Peak is also K3, at 8,051 m. Its terrain is relatively open, but snowfall is heavy and strong winds frequent — historically it has seen a number of accidents after being underestimated.",

    "q.m22#4.p" to "What are Gasherbrum I and II also called?",
    "q.m22#4.o0" to "K4 and K5",
    "q.m22#4.o1" to "K5 and K4",
    "q.m22#4.o2" to "K2 and K3",
    "q.m22#4.o3" to "K3 and K4",
    "q.m22#4.e" to "Gasherbrum I is K5 (8,080 m) and Gasherbrum II is K4 (8,035 m) — the numbering does not follow elevation order, which is exactly what makes it confusing. Remember that the K numbers are not sorted by height and you won't get it wrong.",

    "q.m22#5.p" to "The fourteen 8,000 m peaks are all in which two ranges?",
    "q.m22#5.o0" to "Himalaya and Tian Shan",
    "q.m22#5.o1" to "Himalaya and Karakoram",
    "q.m22#5.o2" to "Karakoram and the Alps",
    "q.m22#5.o3" to "Nyainqentanglha and Himalaya",
    "q.m22#5.e" to "All are in the Himalaya and the Karakoram — geographically adjacent ranges subject to different climate systems. Which again shows that at 8,000 m, geography itself is key information.",

    "q.m22#6.p" to "[Match] Match each peak with its elevation.",
    "q.m22#6.l0" to "K2",
    "q.m22#6.l1" to "Nanga Parbat",
    "q.m22#6.l2" to "Gasherbrum I",
    "q.m22#6.l3" to "Shishapangma",
    "q.m22#6.r0" to "8,611 m",
    "q.m22#6.r1" to "8,126 m",
    "q.m22#6.r2" to "8,080 m",
    "q.m22#6.r3" to "8,027 m",
    "q.m22#6.e" to "These are the second, ninth, eleventh and fourteenth highest peaks. They span a wide range yet share the same status within \"above 8,000 m\" — which is exactly what is peculiar about this class: a clear boundary with enormous internal variation.",

    "q.m22#7.p" to "What is the right view of the relationship between 8,000 m ranking and difficulty?",
    "q.m22#7.o0" to "Higher always means harder",
    "q.m22#7.o1" to "Difficulty is set mainly by technical terrain, climate and logistics, and does not map directly onto elevation ranking",
    "q.m22#7.o2" to "Lower always means easier",
    "q.m22#7.o3" to "Difficulty cannot be compared at all",
    "q.m22#7.e" to "This is the most important insight from the panoramic view of the fourteen: Cho Oyu at 8,188 m is considered relatively easy, while K2 at 8,611 m is among the hardest — under 500 m of elevation difference, yet the real threshold is worlds apart.",

    "q.m22#8.p" to "[Multi] What determines the real difficulty of an 8,000 m peak?",
    "q.m22#8.o0" to "Technical terrain and exposure",
    "q.m22#8.o1" to "Climate and weather windows",
    "q.m22#8.o2" to "Logistics and the approach",
    "q.m22#8.o3" to "Rescue feasibility",
    "q.m22#8.o4" to "The peak's elevation ranking",
    "q.m22#8.e" to "All four matter. Rescue feasibility in particular is often ignored: a mountain where rescue is nearly impossible carries a completely different risk level even if the route is not hard, because there is no buffer when something goes wrong.",

    "q.m22#9.p" to "[Order] Arrange these peaks from highest to lowest.",
    "q.m22#9.o0" to "K2 (8,611)",
    "q.m22#9.o1" to "Nanga Parbat (8,126)",
    "q.m22#9.o2" to "Gasherbrum I (8,080)",
    "q.m22#9.o3" to "Shishapangma (8,027)",
    "q.m22#9.e" to "This ordering covers the back half of the fourteen. Combined with the previous lesson's ordering, you now have the full elevation sequence — which is the basis for judging which tier a given mountain belongs to.",

    "q.m22#10.p" to "Why is \"the fourteen\" such a demanding objective?",
    "q.m22#10.o0" to "Because it is extremely expensive",
    "q.m22#10.o1" to "Because it requires sustaining technique, fitness, acclimatisation and judgement over many years, across logistics systems in several countries",
    "q.m22#10.o2" to "Because it takes too long",
    "q.m22#10.o3" to "Because permits are hard to get",
    "q.m22#10.e" to "The fourteen often take more than a decade, during which the body ages and life circumstances change. It tests not only climbing ability but the consistency of long-term maintenance and risk management.",

    "q.m22#11.p" to "Why does success at 8,000 m often hinge on the weather window rather than technique?",
    "q.m22#11.o0" to "Because technique doesn't matter",
    "q.m22#11.o1" to "Because even with sufficient technique, waiting a long time at altitude consumes your safety margin",
    "q.m22#11.o2" to "Because technique can be learned on the mountain",
    "q.m22#11.o3" to "Because guides handle everything",
    "q.m22#11.e" to "This is the reality at 8,000 m: technique is only the entry ticket, while the window decides whether you can get through while you still have capacity. That is why 8,000 m itineraries usually budget generous contingency days.",

    "q.m22#12.p" to "If you could pick only one 8,000 m peak as your first, what is the more sensible approach?",
    "q.m22#12.o0" to "Go straight for K2 and be done with it",
    "q.m22#12.o1" to "Choose one with a mature route, reliable logistics and feasible rescue, and spend your \"first time\" accumulating experience",
    "q.m22#12.o2" to "Just pick the lowest one",
    "q.m22#12.o3" to "Pick any; they're all the same",
    "q.m22#12.e" to "The value of a first 8,000 m peak is learning your real state in the death zone: how you use oxygen, how much judgement drops, what your pace is. Spending it on a harder mountain means testing several unknowns at once.",

    "q.m22#13.p" to "[Multi] Which of these are Karakoram 8,000 m peaks?",
    "q.m22#13.o0" to "K2",
    "q.m22#13.o1" to "Gasherbrum I",
    "q.m22#13.o2" to "Gasherbrum II",
    "q.m22#13.o3" to "Broad Peak",
    "q.m22#13.o4" to "Manaslu",
    "q.m22#13.e" to "All four are Karakoram — in fact they are all of that range's 8,000 m peaks. \"The Karakoram four\" is therefore a fixed phrase, and together with the Himalayan ten it makes exactly fourteen.",

    "q.m22#14.p" to "What is the most practical benefit of studying the fourteen as a whole?",
    "q.m22#14.o0" to "Being able to recite every elevation",
    "q.m22#14.o1" to "Understanding why difficulty and elevation are not the same thing, and using that to assess your own objectives",
    "q.m22#14.o2" to "Being able to guide others",
    "q.m22#14.o3" to "Being able to write route guides",
    "q.m22#14.e" to "The real value is building a multidimensional view of difficulty: technical, climatic, logistical and rescue dimensions together determine a mountain's true threshold. The same framework applies to choosing among 5,000 m and 6,000 m peaks.",

    "q.m22#15.p" to "Why can the approach to an 8,000 m peak itself be a risk factor?",
    "q.m22#15.o0" to "Because it takes a long time",
    "q.m22#15.o1" to "Because the approach often crosses glaciers and avalanche terrain while the team is not yet fully acclimatised",
    "q.m22#15.o2" to "Because the scenery is poor",
    "q.m22#15.o3" to "Because it requires permits",
    "q.m22#15.e" to "The approach usually happens during the ascent phase, when acclimatisation is poorest and judgement least stable, while also dealing with crevasses and avalanche terrain. This doubly vulnerable period is when many accidents occur.",

    "q.m22#16.p" to "If you were building your own list of 8,000 m objectives, what should you determine first?",
    "q.m22#16.o0" to "The names of the mountains you want",
    "q.m22#16.o1" to "Your own weak points (technique, acclimatisation, judgement or logistics experience), then match peaks that address them",
    "q.m22#16.o2" to "The budget",
    "q.m22#16.o3" to "The length of your leave",
    "q.m22#16.e" to "Choosing by weak point treats 8,000 m as a growth path rather than a collection of achievements. The same mountain is worth different things to different people — depending on which of your gaps it fills.",

    // ---------- m23 基础能力综合（18 题） ----------
    "q.m23#0.p" to "[Scenario] A partner at 4,500 m has a headache and nausea and insists that \"one more day of acclimatising and I'll be fine to go up\". From an environmental-science standpoint, what is the correct judgement?",
    "q.m23#0.o0" to "One more day will definitely fix it — encourage them to push on",
    "q.m23#0.o1" to "Symptoms mean compensation is inadequate; do not keep ascending while symptoms persist",
    "q.m23#0.o2" to "Give medication and keep ascending",
    "q.m23#0.o3" to "Descending 100 m is enough",
    "q.m23#0.e" to "The chain starts from the most basic causation: low pressure → low oxygen partial pressure → the body needs time. Symptoms are the signal that time is insufficient, and another day does not guarantee improvement — so the right move is to stop ascending, not to bet on tomorrow.",

    "q.m23#1.p" to "[Multi] A team member is heading for a hard snow slope at 5,000 m. Which items must be confirmed?",
    "q.m23#1.o0" to "Crampons strictly matched to the boots",
    "q.m23#1.o1" to "An ice axe sized to their height",
    "q.m23#1.o2" to "UV400 glacier glasses and high-factor sunscreen",
    "q.m23#1.o3" to "Insulation and shell layers matched to the layering system",
    "q.m23#1.o4" to "A camera and spare batteries for summit photos",
    "q.m23#1.e" to "The four map onto four risk types: slipping (crampons), arrest (axe), UV (glasses and sunscreen), hypothermia (layers). The right way to check gear is to build the list from risks, not to grab things out of habit.",

    "q.m23#2.p" to "[Match] Match each layer of the clothing system with its job.",
    "q.m23#2.l0" to "Base layer",
    "q.m23#2.l1" to "Mid layer",
    "q.m23#2.l2" to "Shell",
    "q.m23#2.l3" to "Down layer (in extreme cold)",
    "q.m23#2.r0" to "Moves sweat away from the skin and keeps you dry",
    "q.m23#2.r1" to "Traps a layer of air for warmth (fleece insulates even when damp)",
    "q.m23#2.r2" to "Waterproof, windproof and breathable; shields you from the weather",
    "q.m23#2.r3" to "The most efficient warmth in a dry environment",
    "q.m23#2.e" to "Each layer does one job. Once you see that division you understand why \"more layers is warmer\" is wrong: skip the wicking layer and you carry your own damp microclimate, while a non-breathable shell traps sweat vapour inside.",

    "q.m23#3.p" to "[Scenario] On the way up a snow slope, the person ahead kicks uneven steps. What is the most likely consequence?",
    "q.m23#3.o0" to "The team moves faster",
    "q.m23#3.o1" to "Those behind must keep re-adjusting their balance, using more energy and losing stability",
    "q.m23#3.o2" to "The slope will collapse",
    "q.m23#3.o3" to "No effect",
    "q.m23#3.e" to "Steps are the team's foundation. Uneven steps force everyone to keep hunting for a foothold, on top of the balance capacity that is already scarce at altitude — a textbook case of small problems accumulating into big risk.",

    "q.m23#4.p" to "[Order] Put the ice-axe self-arrest sequence in the correct order.",
    "q.m23#4.o0" to "Take a firm grip on the axe, confirming the hold is correct",
    "q.m23#4.o1" to "Roll onto your front, facing the snow",
    "q.m23#4.o2" to "Drive the pick into the snow using your body weight",
    "q.m23#4.o3" to "Lift your feet so the crampons cannot catch and send you tumbling",
    "q.m23#4.e" to "This sequence is the foundation of the whole technical system. It has to run without thinking — in a real fall your thinking capacity has a window of one or two seconds, and those two seconds are entirely occupied by muscle memory.",

    "q.m23#5.p" to "[Scenario] A climber falls on a hard snow slope and the arrest fails. What is the most likely cause on review?",
    "q.m23#5.o0" to "The axe was too short",
    "q.m23#5.o1" to "The pick could not bite in hard snow — and a hard snow slope should have been protected with a fixed rope",
    "q.m23#5.o2" to "The boots were wrong",
    "q.m23#5.o3" to "They weren't wearing gloves",
    "q.m23#5.e" to "Arrest success drops markedly on hard snow and ice; that is the limit of the technique itself. So the real question is usually earlier — why were we on a steep hard snow slope without a protected system at all?",

    "q.m23#6.p" to "[Multi] Which risks are easily overlooked during the descent?",
    "q.m23#6.o0" to "Declining fitness weakening leg control",
    "q.m23#6.o1" to "Alertness dropping once the goal is achieved",
    "q.m23#6.o2" to "The snow surface freezing or softening, so conditions differ from the ascent",
    "q.m23#6.o3" to "Fading light reducing visibility and judgement",
    "q.m23#6.o4" to "Descent routes are usually shorter than ascent routes",
    "q.m23#6.e" to "Stack those four together and you have the explanation for why so many accidents happen on the way down. The descent is not the trip home after the job is done; it is a stretch that needs its own plan and carries comparable risk.",

    "q.m23#7.p" to "[Scenario] The bite valve on your hydration hose freezes quickly in the cold. What should you do?",
    "q.m23#7.o0" to "Switch to a wide-mouth insulated flask, and blow the water back or store it inverted after each drink",
    "q.m23#7.o1" to "Keep using it and wait for it to thaw",
    "q.m23#7.o2" to "Carry the bladder outside the pack",
    "q.m23#7.o3" to "Stop drinking",
    "q.m23#7.e" to "A small but critical technique: dehydration at altitude is usually not \"no water brought\" but \"the water froze and I couldn't drink it\". Designing a drinking system that cannot freeze is what actually counts as being prepared to hydrate.",

    "q.m23#8.p" to "Fill in the blank: temperature falls by about ( ) °C for every 1,000 m of ascent.",
    "q.m23#8.a0" to "6.5",
    "q.m23#8.a1" to "six point five",
    "q.m23#8.e" to "6.5 °C. This number runs through the whole course: it explains the snow line, sets how thick your insulation must be, and drives how avalanche and ice conditions change. Understanding it means being able to reason with it.",

    "q.m23#9.p" to "[Scenario] At 5,000 m your goggles fog badly and you can no longer read the terrain. What is the most important risk?",
    "q.m23#9.o0" to "It is merely uncomfortable",
    "q.m23#9.o1" to "You lose the basis for terrain judgement and may stray onto a steep slope, a cornice or a crevasse field",
    "q.m23#9.o2" to "You will get snow blindness",
    "q.m23#9.o3" to "Your partners will complain",
    "q.m23#9.e" to "\"Can't see\" really means losing the evidence you judge by. On complex snow terrain, one or two wrong footholds can be very costly. So \"can I see clearly\" should be treated as a hard criterion of equipment reliability.",

    "q.m23#10.p" to "[Multi] A team member has a severe loss of appetite at altitude. What should be done?",
    "q.m23#10.o0" to "Eat actively in small amounts, often, choosing high-carbohydrate, easy-to-digest food",
    "q.m23#10.o1" to "Ensure steady, adequate fluid intake",
    "q.m23#10.o2" to "Treat the loss of appetite as a possible acclimatisation signal to be watched",
    "q.m23#10.o3" to "Replace meals with large amounts of coffee and energy drinks",
    "q.m23#10.e" to "The first three are right; the fourth is wrong in a very representative way: caffeine gives a temporary feeling but cannot replace energy. At altitude, insufficient energy intake directly weakens acclimatisation, creating a vicious circle.",

    "q.m23#11.p" to "[Scenario] On a snow slope at 5,000 m your phone jumps from 40% straight to shutting down. What is the most sensible response?",
    "q.m23#11.o0" to "Warm it against your body, then power it on again",
    "q.m23#11.o1" to "Keep switching it on repeatedly",
    "q.m23#11.o2" to "Give up on electronics",
    "q.m23#11.o3" to "Use the last of the battery to send a distress message",
    "q.m23#11.e" to "This is typical lithium-battery behaviour in the cold: capacity collapses without the charge being gone. Warming it against the body usually restores power. The lesson: manage electronics as safety equipment that may fail without warning.",

    "q.m23#12.p" to "[Order] Put a complete equipment check in a sensible order.",
    "q.m23#12.o0" to "Build the list from risks (what terrain, weather and altitude each demand)",
    "q.m23#12.o1" to "Check each item for completeness and working condition",
    "q.m23#12.o2" to "Put on and test-operate the critical items (crampons, harness, helmet, headtorch)",
    "q.m23#12.o3" to "Record and tell your partners your gear status and backup plan",
    "q.m23#12.e" to "The key is step three, test-operation: complete does not mean working. A crampon bail not fully seated, or an old battery in the headtorch, only shows up when you wear it and use it.",

    "q.m23#13.p" to "[Scenario] The team decides to descend because of weather, but one member insists on continuing, arguing \"we've come all this way\". What is the best handling?",
    "q.m23#13.o0" to "Respect their choice and let them continue alone",
    "q.m23#13.o1" to "Insist the whole team descends together — solo travel is not permitted at altitude, and stubbornness up there may itself be hypoxia",
    "q.m23#13.o2" to "Put it to a vote",
    "q.m23#13.o3" to "Have them wait an hour and then decide",
    "q.m23#13.e" to "Two reasons: solo travel at altitude is extremely risky, and \"we've come all this way\" is the textbook phrasing of sunk cost — at altitude that emotion and declining judgement tend to be tangled together, so it cannot be treated as reliable input.",

    "q.m23#14.p" to "Regarding whether fitter people are more prone to altitude illness, what is correct?",
    "q.m23#14.o0" to "The fitter you are, the less likely you are to get it",
    "q.m23#14.o1" to "Altitude illness has no direct relationship with fitness; it relates to ascent rate, sleeping altitude and individual response",
    "q.m23#14.o2" to "The fitter you are, the more likely you are to get it",
    "q.m23#14.o3" to "Only unfit people get it",
    "q.m23#14.e" to "Confusing fitness with acclimatisation is the most common beginner error. In fact fitter people may run into more trouble precisely because they walk faster and climb higher — a very real trap.",

    "q.m23#15.p" to "[Multi] Which practices effectively reduce fall risk?",
    "q.m23#15.o0" to "Using the axe for self-belay continuously while moving",
    "q.m23#15.o1" to "Keeping a sustainable steady pace without sudden efforts",
    "q.m23#15.o2" to "Moving at the pace of the slowest team member",
    "q.m23#15.o3" to "Rigging fixed ropes on hard snow and ice slopes",
    "q.m23#15.o4" to "Reducing braking and moving faster on the way down",
    "q.m23#15.e" to "The four correspond to personal technique, pace control, team coordination and system protection. Fall prevention is never a single action but a whole layer of insurance stacked on insurance.",

    "q.m23#16.p" to "[Scenario] During a rest on a snow slope, a team member leaves their axe stuck in the snow and walks away. What risk does this create?",
    "q.m23#16.o0" to "The axe may be lost",
    "q.m23#16.o1" to "If they fall, they have no arrest tool at all",
    "q.m23#16.o2" to "Someone may step on it",
    "q.m23#16.o3" to "No risk",
    "q.m23#16.e" to "Falls happen extremely fast, and the axe is your only means of arrest. Leaving it in the snow means temporarily giving up that ability — and on a snow slope, \"temporarily\" is exactly the most dangerous interval.",

    "q.m23#17.p" to "What core capability does this lesson assess?",
    "q.m23#17.o0" to "Memorising all the figures",
    "q.m23#17.o1" to "Combining environment, equipment, clothing and movement knowledge to judge a specific situation correctly",
    "q.m23#17.o2" to "Reciting all the terminology",
    "q.m23#17.o3" to "Knowing equipment brands well",
    "q.m23#17.e" to "This is the design logic of the whole course: individual facts are easy to memorise, but on the mountain you face combination problems. Being able to string several pieces of knowledge together in a concrete situation is what real mastery means.",

    // ---------- m24 综合考核（18 题） ----------
    "q.m24#0.p" to "[Scenario] A partner has fallen into a crevasse and your body is holding their weight alone. What comes first?",
    "q.m24#0.o0" to "Start hauling immediately",
    "q.m24#0.o1" to "Build an anchor and transfer the load first, then think about hauling",
    "q.m24#0.o2" to "Call for help first",
    "q.m24#0.o3" to "Take a photograph for the record",
    "q.m24#0.e" to "As long as the weight is on you, you have no capacity to operate the system. So anchor, then transfer, then haul — the order cannot be reversed. It is the most practical rule in the whole rescue system, and the step most often skipped under stress.",

    "q.m24#1.p" to "[Match] Match each knot with its use.",
    "q.m24#1.l0" to "Figure-8",
    "q.m24#1.l1" to "Double fisherman's",
    "q.m24#1.l2" to "Prusik",
    "q.m24#1.l3" to "Bowline",
    "q.m24#1.r0" to "Connecting harness to an anchor",
    "q.m24#1.r1" to "Joining two ropes or making a cordelette loop",
    "q.m24#1.r2" to "Friction hitch, grips in one direction",
    "q.m24#1.r3" to "Connecting to an anchor; common in boating",
    "q.m24#1.e" to "These four cover most of glacier travel and basic protection. The point of assessing them: you need to tie them in the dark, wearing gloves.",

    "q.m24#2.p" to "[Scenario] The sling angle between two anchors is close to 100°. What does that mean?",
    "q.m24#2.o0" to "The load is distributed more evenly",
    "q.m24#2.o1" to "The load on each anchor rises markedly (the wider the angle, the greater the load per anchor)",
    "q.m24#2.o2" to "No effect",
    "q.m24#2.o3" to "The rope balances itself automatically",
    "q.m24#2.e" to "The numbers are intuitive: about 50% per anchor at 0°, about 58% at 60°, about 71% at 90°. At 100° each anchor is carrying a great deal — which is why practice keeps the angle within 60°.",

    "q.m24#3.p" to "[Multi] What should an adequate anchor system have?",
    "q.m24#3.o0" to "Each individual placement solid",
    "q.m24#3.o1" to "Independent failure between placements (no false redundancy)",
    "q.m24#3.o2" to "Reasonable load distribution, pre-tensioned",
    "q.m24#3.o3" to "Quick to build, to shorten exposure",
    "q.m24#3.o4" to "As few placements as possible to save gear",
    "q.m24#3.e" to "The first three are safety requirements, the fourth is an efficiency requirement — and efficiency is also safety, because the building process is itself time exposed to risk.",

    "q.m24#4.p" to "[Scenario] A partner becomes unsteady on their feet and confused. What is the priority?",
    "q.m24#4.o0" to "Give oxygen and observe",
    "q.m24#4.o1" to "Descend immediately, and give dexamethasone under medical supervision",
    "q.m24#4.o2" to "Keep ascending to reach camp sooner",
    "q.m24#4.o3" to "Take painkillers and rest",
    "q.m24#4.e" to "Ataxia and altered consciousness are the core signs of HACE, a medical emergency. Descent is the only definitive treatment; dexamethasone only buys time for the descent — the two are not alternatives.",

    "q.m24#5.p" to "[Multi] Which statements about altitude medication are correct?",
    "q.m24#5.o0" to "Dexamethasone does not affect acclimatisation and does not treat pulmonary oedema",
    "q.m24#5.o1" to "Acetazolamide speeds acclimatisation; start one day before ascent and stop about two days after",
    "q.m24#5.o2" to "Nifedipine may cause a rapid drop in blood pressure",
    "q.m24#5.o3" to "Medication cannot replace descent",
    "q.m24#5.o4" to "Acetazolamide can replace the body's acclimatisation process",
    "q.m24#5.e" to "All four are key points, and their shared conclusion is that medication cannot replace descent: whatever is taken, descent remains the fundamental treatment. Drugs only buy the conditions for it.",

    "q.m24#6.p" to "[Scenario] A team member stops shivering in the cold and is slurring their words. What should you NOT do?",
    "q.m24#6.o0" to "Change wet clothing and insulate them",
    "q.m24#6.o1" to "Have them walk around to generate heat",
    "q.m24#6.o2" to "Rewarm the trunk first",
    "q.m24#6.o3" to "Avoid rough handling",
    "q.m24#6.e" to "\"Stopped shivering\" means moderate hypothermia or worse, and a cold heart is highly susceptible to arrhythmia. Making the patient walk or handling them roughly can trigger it directly — the most counter-intuitive rule in hypothermia first aid.",

    "q.m24#7.p" to "[Order] Put the four steps of a rope-team rescue in order.",
    "q.m24#7.o0" to "Self-arrest and stabilise yourself",
    "q.m24#7.o1" to "Build an independent anchor",
    "q.m24#7.o2" to "Transfer the load to the anchor",
    "q.m24#7.o3" to "Haul with a 3:1 system",
    "q.m24#7.e" to "The four cannot be reordered. In an exam you may be able to recite them; in reality you must complete the first three in tens of seconds — that is the real threshold of this knowledge point.",

    "q.m24#8.p" to "[Scenario] The forecast says \"cloudy\" but you can see cumulus developing vertically fast. What should you do?",
    "q.m24#8.o0" to "Trust the forecast and follow the plan",
    "q.m24#8.o1" to "Decide on the assumption it may deteriorate, and consider descending early",
    "q.m24#8.o2" to "Wait an hour and look again",
    "q.m24#8.o3" to "Keep ascending but faster",
    "q.m24#8.e" to "A forecast gives regional background; the cloud in front of you is evidence of here and now. When they conflict, the ground wins. All the more so because cumulus development at altitude is often measured in minutes.",

    "q.m24#9.p" to "[Multi] Which practices are correct when crossing avalanche terrain?",
    "q.m24#9.o0" to "Cross one at a time, keeping spacing",
    "q.m24#9.o1" to "Post a spotter in a safe position",
    "q.m24#9.o2" to "Plan the escape route and meeting point in advance",
    "q.m24#9.o3" to "Send the whole team across quickly together to shorten exposure",
    "q.m24#9.e" to "The first three confine the risk to one person; \"everyone across at once\" amplifies it to team level — from possibly burying one to possibly burying all, which is why it is the least acceptable option.",

    "q.m24#10.p" to "[Scenario] The team is one hour from the summit but past the turnaround time. What is correct?",
    "q.m24#10.o0" to "Continue to the summit, since it's only an hour",
    "q.m24#10.o1" to "Turn around immediately — the whole point of a turnaround time is that it works precisely at \"just a bit further\"",
    "q.m24#10.o2" to "Extend it by half an hour",
    "q.m24#10.o3" to "Let the fittest member continue",
    "q.m24#10.e" to "What this question really tests is what a turnaround time is for. If it is only obeyed when things are easy, and can be relaxed at \"just a bit further\", then it never existed — and that is exactly where accidents happen.",

    "q.m24#11.p" to "[Multi] Which are correct team decision practices in high-risk environments?",
    "q.m24#11.o0" to "Quantifying retreat signals before departure",
    "q.m24#11.o1" to "The most conservative opinion prevailing",
    "q.m24#11.o2" to "Deliberately inviting dissent (for example, going round each person)",
    "q.m24#11.o3" to "Majority rule",
    "q.m24#11.e" to "The first three together form the mechanism against collective misjudgement; majority rule does the opposite — it suppresses the minority's legitimate concern, and it is often that minority who noticed the danger signal first.",

    "q.m24#12.p" to "[Scenario] Communications are down and you were due to check in with the people back home an hour ago. What should you do?",
    "q.m24#12.o0" to "Carry on as planned and wait for signal to return",
    "q.m24#12.o1" to "Follow the lost-contact plan agreed before departure (for example, wait at the rendezvous)",
    "q.m24#12.o2" to "Split up to look for signal",
    "q.m24#12.o3" to "Have everyone descend immediately",
    "q.m24#12.e" to "Losing communications in the mountains is normal, not an accident — so it must have a plan before departure. With a plan, lost contact is a known branch; without one, it becomes confusion on the ground.",

    "q.m24#13.p" to "[Order] Put the full sequence for handling a seriously injured person in order.",
    "q.m24#13.o0" to "Make the scene safe and avoid a second accident",
    "q.m24#13.o1" to "Assess consciousness, breathing and circulation; deal with life threats",
    "q.m24#13.o2" to "Call for help and report the exact location and injuries",
    "q.m24#13.o3" to "Insulate, immobilise and keep observing while waiting for evacuation or professional rescue",
    "q.m24#13.e" to "The order embodies safety first, then treatment, with the call going out in parallel and maintenance after. The most common real-world error is skipping step one and rushing straight to the casualty — the classic route to creating a second casualty.",

    "q.m24#14.p" to "[Multi] Which skills in technical climbing must be practised in the field?",
    "q.m24#14.o0" to "Ice-axe self-arrest",
    "q.m24#14.o1" to "Prusik and rope-team systems",
    "q.m24#14.o2" to "Building anchors",
    "q.m24#14.o3" to "The crevasse rescue sequence",
    "q.m24#14.o4" to "Memorising the names and elevations of the fourteen 8,000 m peaks",
    "q.m24#14.e" to "None of the four can be acquired by reading. What they share: they must be performed under pressure, they allow almost no margin for error, and they depend on muscle memory. That is why this app repeatedly marks them as requiring an instructor's assessment.",

    "q.m24#15.p" to "[Scenario] You have passed all the theory assessments. How should you regard your ability now?",
    "q.m24#15.o0" to "You are now capable of climbing 8,000 m independently",
    "q.m24#15.o1" to "You have a theoretical basis and a judgement framework, but every technical skill still needs an instructor's field assessment before use",
    "q.m24#15.o2" to "You can work as a guide",
    "q.m24#15.o3" to "Passing the theory means the ability is there",
    "q.m24#15.e" to "This is the most important statement in the whole course: theoretical grasp is not field ability. This app builds a cognitive and judgement framework; what actually saves you on an ice face is the movement you have repeated several hundred times on safe ground.",

    "q.m24#16.p" to "After completing the whole course, what is the core asset you have built?",
    "q.m24#16.o0" to "A gear list",
    "q.m24#16.o1" to "A thinking framework of recognise risk, assess risk, decide — including knowing when not to continue",
    "q.m24#16.o2" to "A mountaineering certificate",
    "q.m24#16.o3" to "A pile of facts",
    "q.m24#16.e" to "From 5,000 m basics to the 8,000 m final assessment, the course keeps repeating one thing: safety is not the product of technique but of judgement — and technique exists to give judgement room.",

    "q.m24#17.p" to "Fill in the blank: when deciding under uncertainty, the most ( ) opinion should be adopted first.",
    "q.m24#17.a0" to "conservative",
    "q.m24#17.e" to "\"Conservative first\" is the closing principle of the whole course: simple enough to apply on the spot, strong enough to counter most cognitive bias. The mountain is always there; you are not.",

    // ---------- m25 第一次上高原：真实判断（12 题） ----------
    "q.m25#0.p" to "After going up you feel head pressure and are short of breath, while the team continues ascending as planned. What should you do?",
    "q.m25#0.o0" to "Tough it out — you've come all this way",
    "q.m25#0.o1" to "Stop and tell the guide or your partners honestly, then rest and observe",
    "q.m25#0.o2" to "Take something yourself and keep up with the team",
    "q.m25#0.o3" to "Speed up; reaching camp sooner will fix it",
    "q.m25#0.e" to "There are two things you must never do with body signals at altitude: hide them and self-medicate. The right first step is to say how you feel honestly, then stop to rest and observe.\nThat is not weakness — the guide can only judge once they know, and you need a period of observation yourself to tell whether it is easing or worsening.",

    "q.m25#1.p" to "Why is the phrase \"we've come all this way\" dangerous on an altitude trip?",
    "q.m25#1.o0" to "Because it wastes time",
    "q.m25#1.o1" to "Because it turns time already invested into a reason to keep taking risk",
    "q.m25#1.o2" to "Because it affects team atmosphere",
    "q.m25#1.o3" to "Because it sounds unprofessional",
    "q.m25#1.e" to "This is textbook sunk-cost thinking: we've walked this far, spent this much, taken this much leave — so it can't be for nothing.\nBut risk does not fall because of how much you have invested. What is spent cannot be recovered, while the cost of continuing may be more things that cannot be recovered.",

    "q.m25#2.p" to "You realise you clearly cannot keep the team's pace and have been forcing it. What is the best approach?",
    "q.m25#2.o0" to "Grit your teeth and keep up so as not to hold others back",
    "q.m25#2.o1" to "Say so honestly and ask the team to move at the slowest person's pace",
    "q.m25#2.o2" to "Quietly slow down and pretend everything is fine",
    "q.m25#2.o3" to "Tell nobody and descend alone",
    "q.m25#2.e" to "Forcing the pace at altitude is a hidden overdraft: the immediate cost is only tiredness, but it accumulates into collapse the next day. And a team moving at the fastest person's pace drags everyone to the edge.\nThe right move is to set the pace at what the slowest person can sustain — which protects both the individual and the team.",

    "q.m25#3.p" to "A partner says they feel a bit off but insists \"it's fine, I can walk\". What should you do?",
    "q.m25#3.o0" to "Trust their judgement and keep walking",
    "q.m25#3.o1" to "Take it seriously and tell the guide",
    "q.m25#3.o2" to "Don't interfere; let them decide",
    "q.m25#3.o3" to "Don't take it seriously — lots of people say that",
    "q.m25#3.e" to "Discomfort at altitude has a cruel feature: judgement is affected first, so \"I think I'm fine\" is discounted up there.\nReporting your partner's condition to the guide is the responsible thing — if it really is nothing, the cost is one extra check; if it isn't, you may be the only one who noticed in time.",

    "q.m25#4.p" to "Before departure the guide says tomorrow's route must be crossed roped up. Someone thinks \"a slope that gentle doesn't need it\". What is the right understanding?",
    "q.m25#4.o0" to "A gentle slope really doesn't need a rope",
    "q.m25#4.o1" to "Whether to rope up is the guide's call; they hold the terrain and snowpack information",
    "q.m25#4.o2" to "Roping up is mainly for looking tidy",
    "q.m25#4.o3" to "The fittest person should decide",
    "q.m25#4.e" to "Seeing \"gentle\" from a distance and standing there looking at the distribution of crevasses, snow bridges and hidden cracks are two different things. The guide holds information you don't — that is precisely their value.\nOn technical decisions, letting whoever holds the most information judge is the basic rule of both efficiency and safety.",

    "q.m25#5.p" to "Walking in the middle of the team, you find your water is finished but the next resupply point is two hours away. What should you do?",
    "q.m25#5.o0" to "Keep quiet and don't bother anyone",
    "q.m25#5.o1" to "Tell the leader immediately and see whether it can be coordinated",
    "q.m25#5.o2" to "Ask the nearest partner for water but not tell the leader",
    "q.m25#5.o3" to "Drink less and push on",
    "q.m25#5.e" to "Running short of water or food is team-level information, not a personal trifle — it shapes the leader's judgement of pace and resupply.\nAsking a partner privately looks like not making a fuss, but it cuts the information off: the leader still believes the team is in good shape and may push on as planned.",

    "q.m25#6.p" to "What does \"slow is fast\" actually mean at altitude?",
    "q.m25#6.o0" to "Walking slowly guarantees a summit",
    "q.m25#6.o1" to "A sustainable steady pace saves more time, and is safer, than repeated bursts",
    "q.m25#6.o2" to "Slow is to accommodate the less fit",
    "q.m25#6.o3" to "Speed doesn't matter at altitude",
    "q.m25#6.e" to "Oxygen supply is limited at altitude, and repeated explosive efforts rapidly accumulate lactate and worsen hypoxia.\nA steady pace is actually faster: it removes the need for frequent recovery stops and lowers the chance of being forced to turn back through over-expenditure. The phrase describes energy metabolism, not consolation.",

    "q.m25#7.p" to "You reach camp two hours later than planned and it is already dark. What should you do?",
    "q.m25#7.o0" to "Push on through the night to the next camp",
    "q.m25#7.o1" to "Camp where you are and tell the people back home your position",
    "q.m25#7.o2" to "Go back alone to look for anyone missing",
    "q.m25#7.o3" to "Keep walking until you catch the group ahead",
    "q.m25#7.e" to "Travelling through the night at altitude combines the worst factors: darkness, fatigue, cold, and no ability to read the terrain. Camping where you are is the sound choice.\nBut it must include one more thing: tell the outside world your position. Then if rescue is needed, at least someone knows where to look. Acting alone, by contrast, loses the team two people at once.",

    "q.m25#8.p" to "A partner becomes clearly unwell on the way and keeps slowing. The team splits over whether to wait or send some ahead. What is the more sensible approach?",
    "q.m25#8.o0" to "The whole team continues at the original pace",
    "q.m25#8.o1" to "Never split; the whole team slows down",
    "q.m25#8.o2" to "Assign one experienced person to accompany them while the others continue and stay in contact",
    "q.m25#8.o3" to "Let them walk slowly alone and meet at camp",
    "q.m25#8.e" to "Splitting carries its own risk at altitude, but with enough people, assigning the most experienced to accompany the slower member while the rest continue is often more sensible than either slowing everyone or forcing everyone.\nThree things are essential: someone stays with them, communications are maintained, and the group ahead is told the situation and the expected arrival time. Being completely alone is the worst option.",

    "q.m25#9.p" to "What is the right understanding of the summit's place in the whole trip?",
    "q.m25#9.o0" to "The summit is the end of the trip",
    "q.m25#9.o1" to "The summit is only half the trip; the descent is where risk concentrates",
    "q.m25#9.o2" to "The summit is all that matters",
    "q.m25#9.o3" to "No summit means the trip failed",
    "q.m25#9.e" to "Many accidents happen on the descent, because alertness drops once the goal is achieved while fitness is already near its limit.\nTreating the summit as \"half\" means budgeting equal time, energy and protection for the descent in your plan — rather than spending everything on going up.",

    "q.m25#10.p" to "Scenario: the first 24 hours at altitude",
    "q.m25#10.c" to "It is your first 5,000 m trekking peak. After reaching a camp at 4,300 m, several things happen over the next 24 hours.",
    "q.m25#10.e" to "The point of these four steps is not medical knowledge but two habits: say it honestly, and reassess. What actually pushes people into danger on an altitude trip is not one bad judgement but a chain of small choices — tough it out, don't be a bother — stacking up.",
    "q.m25#10.s0.p" to "Step 1: in the evening you develop a headache and lose your appetite. A partner says \"that's normal, just sleep it off\". What should you do?",
    "q.m25#10.s0.o0" to "Do as they say and sleep it off",
    "q.m25#10.s0.o1" to "Tell the guide honestly how you feel, then rest, eat and drink in small amounts often as instructed",
    "q.m25#10.s0.o2" to "Find some medicine yourself and tell nobody",
    "q.m25#10.s0.o3" to "Have a drink to help you sleep",
    "q.m25#10.s0.e" to "Headache and loss of appetite are common at altitude, but common does not mean ignorable. Honest reporting plus basic measures — rest, fluids, small amounts of food — is the standard response.\nThe key is that the guide needs to know the moment your condition changes, not discover it the next morning.",
    "q.m25#10.s1.p" to "Step 2: you barely sleep all night. In the morning the team prepares to keep ascending. What do you choose?",
    "q.m25#10.s1.o0" to "Say nothing and just follow",
    "q.m25#10.s1.o1" to "Report how you slept and let the guide assess whether to continue",
    "q.m25#10.s1.o2" to "Decide on your own to stay behind without telling the team",
    "q.m25#10.s1.o3" to "Ask the whole team to stop and wait for you to recover",
    "q.m25#10.s1.e" to "Poor sleep is one of the most common altitude complaints; on its own it usually doesn't justify stopping the ascent — but it must feed into the assessment rather than being carried silently.\nThe guide will weigh it together with headache, appetite and how you are moving. That is the value of their experience.",
    "q.m25#10.s2.p" to "Step 3: the team continues and you feel a bit better than yesterday, but you are walking slowly. What mindset should you be most wary of now?",
    "q.m25#10.s2.o0" to "Worrying about being laughed at",
    "q.m25#10.s2.o1" to "The \"can't be for nothing\" feeling — it makes you reluctant to stop when you need to",
    "q.m25#10.s2.o2" to "The urge to take photos",
    "q.m25#10.s2.o3" to "Concern about the weather",
    "q.m25#10.s2.e" to "Sunk cost flares up most on the second day: you suffered all night, so giving up now would make that suffering pointless.\nThat logic turns a cost already paid into a reason to continue, rather than a signal to reassess.",
    "q.m25#10.s3.p" to "Step 4: in the end you don't summit — you turn back an hour short. How should you see this trip?",
    "q.m25#10.s3.o0" to "A failure; don't bother coming back",
    "q.m25#10.s3.o1" to "A useful acclimatisation experience; turning back was judgement, not failure",
    "q.m25#10.s3.o2" to "It was your partners' fault for slowing you down",
    "q.m25#10.s3.o3" to "Next time summit no matter what",
    "q.m25#10.s3.e" to "Acclimatisation is built through repeated exposure; a first trip to 4,000–5,000 m was never supposed to have the summit as its only goal.\nAnd being able to turn around when it is right is the most valued ability in this sport. It will take you further than a lucky summit ever will.",

    "q.m25#11.p" to "Scenario: team pressure",
    "q.m25#11.c" to "Day four of the trip; the weather is starting to turn and the team is divided. Your own judgement differs somewhat from the group's.",
    "q.m25#11.e" to "This scenario is about voicing a reservation. It is hard in practice because the cost looks social — spoiling the mood, not fitting in — while the benefit is invisible: an accident that didn't happen. Remember those three points and you will speak up sooner next time.",
    "q.m25#11.s0.p" to "Step 1: some argue \"let's push, the weather may be better tomorrow\"; others want to descend. You lean toward descending but don't want to be the one who spoils it. What should you do?",
    "q.m25#11.s0.o0" to "Stay silent and go with the flow",
    "q.m25#11.s0.o1" to "State your judgement and the reasoning behind it",
    "q.m25#11.s0.o2" to "Complain privately and leave it there",
    "q.m25#11.s0.o3" to "Pretend to support continuing while keeping your doubts",
    "q.m25#11.s0.e" to "The silent minority is a regular in accident reviews. Having a reservation and not voicing it means the team decides with incomplete information.\nThe cost of speaking up is small, possibly zero; the cost of silence can be very large.",
    "q.m25#11.s1.p" to "Step 2: after discussion the team decides to continue, but you still don't feel right about it. What next?",
    "q.m25#11.s1.o0" to "Comply passively and do the bare minimum",
    "q.m25#11.s1.o1" to "State your reservation clearly and confirm the team's turnaround conditions and retreat plan",
    "q.m25#11.s1.o2" to "Descend alone immediately",
    "q.m25#11.s1.o3" to "Say nothing more but resent it",
    "q.m25#11.s1.e" to "Once the decision is made, three things remain: leave a clear record (I disagreed, because…), confirm the retreat conditions are explicit, and make sure you are still willing and able to execute.\nA reservation is not passive compliance — having said your piece, you still do your part properly.",
    "q.m25#11.s2.p" to "Step 3: it turns out your concern was right and the team descends early. What is the value of this experience?",
    "q.m25#11.s2.o0" to "It proves you are better than the others",
    "q.m25#11.s2.o1" to "It confirms that voicing a reservation beforehand is effective and does not damage relationships",
    "q.m25#11.s2.o2" to "It shows you should act alone in future",
    "q.m25#11.s2.o3" to "Not much, since you didn't summit",
    "q.m25#11.s2.e" to "Many people worry the first time they voice a reservation that they will be seen as not fitting in. In reality a good team ends up more confident in each other for it, because it proves someone is willing to tell the truth.\nHold on to this experience; next time you will speak up sooner.",

    // ---------- l21 穿着与装备细节（10 题） ----------
    "q.l21#0.p" to "In a three-layer system, what is the main job of the base layer?",
    "q.l21#0.o0" to "Blocking wind and snow",
    "q.l21#0.o1" to "Moving sweat away from the skin and keeping you dry",
    "q.l21#0.o2" to "Providing most of the warmth",
    "q.l21#0.o3" to "Storing spare items",
    "q.l21#0.e" to "The core function of the base layer is wicking. It sits against the skin, and if it stays damp then no matter how many layers you wear outside, heat keeps being drawn away — which is why the base layer is called the second skin.",

    "q.l21#1.p" to "Why is fleece more reliable than down in wet conditions?",
    "q.l21#1.o0" to "Because fleece is thicker",
    "q.l21#1.o1" to "Because polyester fibre is naturally hydrophobic and still insulates when wet",
    "q.l21#1.o2" to "Because fleece is cheaper",
    "q.l21#1.o3" to "Because down can't be worn as an inner layer",
    "q.l21#1.e" to "Fleece is made of plastic (polyester) fibre, which absorbs almost nothing, so it still traps a layer of air and insulates when damp. Down collapses and loses its loft once wet — which is why down must be kept strictly dry.",

    "q.l21#2.p" to "What fill power is recommended for a down jacket used in extreme high-altitude cold?",
    "q.l21#2.o0" to "Below 500",
    "q.l21#2.o1" to "Around 600",
    "q.l21#2.o2" to "800 fill power or above",
    "q.l21#2.o3" to "Fill power doesn't matter",
    "q.l21#2.e" to "The higher the fill power, the more air the same weight of down traps, and the more efficient the insulation. 800 and above is the usual recommendation for high-altitude trips, along with a hooded design and no synthetic fill.",

    "q.l21#3.p" to "What is the core function of a hardshell jacket?",
    "q.l21#3.o0" to "Providing most of the warmth",
    "q.l21#3.o1" to "Waterproof, windproof and breathable, with hood that fits over a helmet",
    "q.l21#3.o2" to "Wicking sweat",
    "q.l21#3.o3" to "Adding weight for training effect",
    "q.l21#3.e" to "The shell keeps out wind, rain and snow while letting the moisture you generate escape. If breathability is poor, sweat vapour condenses on the inner layers — you end up creating your own damp environment.",

    "q.l21#4.p" to "Which glove in the system is specifically for operating touchscreen devices?",
    "q.l21#4.o0" to "Thin fleece gloves",
    "q.l21#4.o1" to "A windproof/abrasion-resistant glove with good touchscreen sensitivity",
    "q.l21#4.o2" to "Thick insulated guide gloves",
    "q.l21#4.o3" to "Summit gloves",
    "q.l21#4.e" to "Operating a phone, GPS or camera at altitude needs a glove that is both windproof and touchscreen-sensitive. Taking gloves off to operate things is one of the most common triggers of frostbite — better to carry one extra pair for exactly this.",

    "q.l21#5.p" to "Which statement about hand and foot warmers is correct?",
    "q.l21#5.o0" to "They can be stuck anywhere on the outside of your socks",
    "q.l21#5.o1" to "Use them only in enclosed spaces such as gloves or inside boots; exposed to ventilated air they can reach about 74 °C",
    "q.l21#5.o2" to "The closer to the skin the better",
    "q.l21#5.o3" to "They can be stuck to the outside of a hat",
    "q.l21#5.e" to "Warmers rely on limited air to control their temperature. Exposed to ventilated air they react violently and can reach roughly 74 °C, enough to cause burns. So they belong in enclosed spaces — gloves, inside boots — and must never go directly against skin or on an exposed surface.",

    "q.l21#6.p" to "Why are hooded insulating jackets and down jackets recommended?",
    "q.l21#6.o0" to "Because they look better",
    "q.l21#6.o1" to "Because they are more versatile and markedly reduce heat loss from the head",
    "q.l21#6.o2" to "Because they pack more easily",
    "q.l21#6.o3" to "Because hooded versions are lighter",
    "q.l21#6.e" to "The head is a major source of heat loss, and a hood is the lightest insulation available right at the core. A hooded jacket can be deployed instantly in camp, at rest stops, or when the temperature drops suddenly; a hoodless one forces you to carry a separate hat, which is more hassle and more weight.",

    "q.l21#7.p" to "[Multi] Which practices are correct for using and storing a down jacket?",
    "q.l21#7.o0" to "Keep it strictly dry; once damp it rapidly loses insulation",
    "q.l21#7.o1" to "Store it dry",
    "q.l21#7.o2" to "In extreme cold, choose a hooded version with no synthetic fill",
    "q.l21#7.o3" to "The higher the fill power, the warmer for the same weight",
    "q.l21#7.o4" to "Store it long term in a compression sack to save space",
    "q.l21#7.e" to "Down insulates by trapping air and collapses once wet. That is also why fleece (hydrophobic polyester) is preferred as the working mid layer in wet conditions, with down kept as the core insulation for dry environments.",

    "q.l21#8.p" to "What is a reasonable specification for high-altitude sunscreen?",
    "q.l21#8.o0" to "SPF 15, an ordinary lotion is enough",
    "q.l21#8.o1" to "High zinc oxide content, SPF 50 level",
    "q.l21#8.o2" to "Below SPF 30 is more breathable",
    "q.l21#8.o3" to "Any product containing sunscreen, regardless of the number",
    "q.l21#8.e" to "UV is intense at altitude and snow reflection adds a second dose, so ordinary sunscreen stops being enough quickly. High zinc oxide content and SPF 50 are the usual recommendation — and it must be reapplied on schedule, because sweat, wiping and friction all degrade the protection.",

    "q.l21#9.p" to "What matters when choosing a lip balm for the outdoors?",
    "q.l21#9.o0" to "The cheaper the better",
    "q.l21#9.o1" to "Rich in zinc, somewhat sweat-resistant, with SPF 30–50",
    "q.l21#9.o2" to "Moisturising is enough",
    "q.l21#9.o3" to "Menthol feels cooler",
    "q.l21#9.e" to "Lip skin is thin and has almost no melanin protection, so it burns and cracks easily at altitude. Zinc provides physical protection, and sweat resistance keeps it on through sweating, eating and drinking — the smallest item of gear, the most often overlooked, and the one that most affects how the trip feels.",

    // ---------- l22 技术装备与通讯（10 题） ----------
    "q.l22#0.p" to "What is the most basic piece of equipment for building a crevasse rescue system?",
    "q.l22#0.o0" to "Prusik loops (accessory cord)",
    "q.l22#0.o1" to "Binoculars",
    "q.l22#0.o2" to "A spare sleeping bag",
    "q.l22#0.o3" to "Trekking poles",
    "q.l22#0.e" to "Prusik loops are used to tie friction hitches and are the core of a 3:1 hauling system. Without them you have only the 1:1 pull of your bare hands — and one person can almost never haul a partner out of a crevasse by main force.",

    "q.l22#1.p" to "In high mountain areas, what is usually the most reliable way to call for help?",
    "q.l22#1.o0" to "Mobile phone signal",
    "q.l22#1.o1" to "A satellite phone or GPS tracker",
    "q.l22#1.o2" to "Shouting",
    "q.l22#1.o3" to "Lighting a smoky fire",
    "q.l22#1.e" to "Most mountain areas have no mobile coverage. A satellite phone allows direct calls and texts, and a GPS tracker lets the outside world follow your position — both should be sorted out before departure, not on the mountain.",

    "q.l22#2.p" to "What brightness is recommended for a spare headtorch?",
    "q.l22#2.o0" to "Below 100 lumens",
    "q.l22#2.o1" to "200 lumens is enough",
    "q.l22#2.o2" to "400 lumens or above",
    "q.l22#2.o3" to "Brightness doesn't matter",
    "q.l22#2.e" to "A headtorch is used for moving around the tent at night and for pre-dawn starts (summit pushes usually begin in the early hours). In wind, snow, fog and when you need to identify the route, adequate brightness directly affects the quality of your judgement. Weatherproof models are clearly better in bad conditions.",

    "q.l22#3.p" to "What is the key requirement when choosing a mountaineering harness?",
    "q.l22#3.o0" to "As light as possible, regardless of size",
    "q.l22#3.o1" to "Large enough in waist and legs to fit over your outermost clothing",
    "q.l22#3.o2" to "Must have several gear loops",
    "q.l22#3.o3" to "A conspicuous colour",
    "q.l22#3.e" to "At altitude you are usually wearing bulky clothing, and the harness must still fit correctly over it. A harness stretched to its longest setting just to close over thick layers is a common and dangerous misconfiguration.",

    "q.l22#4.p" to "What does an altimeter watch's storm alarm use to detect storms?",
    "q.l22#4.o0" to "Satellite cloud imagery",
    "q.l22#4.o1" to "A rapid drop in barometric pressure over a short period",
    "q.l22#4.o2" to "Wind speed measurement",
    "q.l22#4.o3" to "A sudden temperature drop",
    "q.l22#4.e" to "A rapid pressure drop is the precursor signal of deteriorating weather. An altimeter watch warns by continuously monitoring pressure change, which is very practical at altitude — because how the weather window shifts is often the decisive variable for a trip.",

    "q.l22#5.p" to "[Match] Match each carabiner shape with its most suitable use.",
    "q.l22#5.l0" to "HMS pear-shaped",
    "q.l22#5.l1" to "D-shaped",
    "q.l22#5.l2" to "X-shaped",
    "q.l22#5.l3" to "B-shaped",
    "q.l22#5.r0" to "Wide gate opening; takes an Italian hitch for abseiling, the most versatile",
    "q.l22#5.r1" to "Often paired with a pulley in rescue systems",
    "q.l22#5.r2" to "Symmetrical, simple locking, easy to clip",
    "q.l22#5.r3" to "The basic carabiner for all sorts of temporary connections",
    "q.l22#5.e" to "Each shape has its strength: HMS opens wide enough for a hitch and abseil, D is strong and takes a pulley well, X is symmetrical and easy to handle, B is the all-purpose baseline. Choosing a carabiner is not about which is \"stronger\" but whether the mechanism matches the job.",

    "q.l22#6.p" to "When using an ascender, what does the handbook specifically warn against?",
    "q.l22#6.o0" to "Using it in wet conditions",
    "q.l22#6.o1" to "Pushing the ascender too close to the fixed end (a knot)",
    "q.l22#6.o2" to "Operating it one-handed",
    "q.l22#6.o3" to "Using it on snow",
    "q.l22#6.e" to "Pushing the ascender right up against a knot or fixed point leaves it unable to travel further yet hard to release quickly, so you are stuck there — unable to go up and unable to get free. That kind of jam is very dangerous when you need to adjust fast, so deal with it while you still have margin.",

    "q.l22#7.p" to "Which statement about choosing fixed ropes versus roped team travel is correct?",
    "q.l22#7.o0" to "Fixed ropes are always safer than roping up as a team",
    "q.l22#7.o1" to "Large teams tend to use fixed ropes; small teams or technical peaks are more efficient roped together",
    "q.l22#7.o2" to "Roped team travel suits only snow slopes",
    "q.l22#7.o3" to "Fixed ropes are only for descending",
    "q.l22#7.e" to "Fixed ropes raise overall safety but demand more people and gear and take longer to rig. A small, efficient team, or a technical peak, is often better served by roped travel. It is a textbook \"no single best answer, only a match\" decision.",

    "q.l22#8.p" to "[Multi] Which of these are high-altitude communication and navigation devices?",
    "q.l22#8.o0" to "Satellite phone",
    "q.l22#8.o1" to "Two-way radio",
    "q.l22#8.o2" to "GPS tracker",
    "q.l22#8.o3" to "Altimeter watch with barometer",
    "q.l22#8.o4" to "Binoculars",
    "q.l22#8.e" to "The four do different jobs: the satellite phone for calling help outward, the radio for coordination within the team, the GPS tracker so the outside world knows where you are, and the altimeter watch for pressure and altitude trends. The risks at altitude are precisely being unable to call for help and not knowing where you are — these devices address those two directly.",

    "q.l22#9.p" to "Why must a helmet accept a headtorch mount?",
    "q.l22#9.o0" to "For visual consistency",
    "q.l22#9.o1" to "Because summit pushes usually start before sunrise, and the headtorch must be held stably on your head",
    "q.l22#9.o2" to "To reduce the headtorch's weight",
    "q.l22#9.o3" to "To increase helmet strength",
    "q.l22#9.e" to "Summit day usually starts in the early hours, and the headtorch is the only light source; with a helmet on, it has to be mounted on the helmet to point steadily. A torch that wobbles or comes off while you are moving means you cannot see your footholds — a genuine risk on technical terrain."
)
